package main

import "fmt"

type node struct {
	val  int
	len  int
	next *node
}

func lis(v []int) {
	n := make([]node, len(v))
	for i, val := range v {
		n[i].val = val
	}

	for i := len(v) - 1; i >= 0; i-- {
		// find longest chain that can follow n[i]
		for p := &n[i]; p!= &n[len(v)]; p++ {
			if p.val > n[i].val && p.len >= n[i].len {
				n[i].next = p
				n[i].len = p.len + 1
			}
		}
	}

	// find longest chain
	var p *node
	for i, val := range n {
		if val.len > p.len {
			p = &n[i]
		}
	}

	for p!= nil {
		fmt.Printf(" %d", p.val)
		p = p.next
	}
	fmt.Println()
}

func main() {
	x := []int{3, 2, 6, 4, 5, 1}
	y := []int{0, 8, 4, 12, 2, 10, 6, 14, 1, 9, 5, 13, 3, 11, 7, 15}

	lis(x)
	lis(y)
}

