package main

import (
	"fmt"
	"strconv"
	"strings"
)

func main() {
	var count int
	if len(os.Args) >= 1 && int.TryParse(os.Args[0], out count) && count > 0 {
		fmt.Println(MakeTriangle(count))
	} else {
		fmt.Println(MakeTriangle(5))
		fmt.Println()
		fmt.Println(MakeTriangle(14))
	}
}

func MakeTriangle(rows int) string {
	maxValue := (rows * (rows + 1)) / 2
	digit := 0
	output := strings.Builder{}

	for row := 1; row <= rows; row++ {
		for column := 0; column < row; column++ {
			colMaxDigit := (maxValue - rows) + column + 1
			if column > 0 {
				output.Append(' ')
			}

			digit++
			output.Append(strconv.Itoa(digit).PadLeft(strconv.Itoa(colMaxDigit).Length()))
		}

		output.AppendLine()
	}

	return output.ToString()
}

package main

import "fmt"

func divisor_count_and_sum(n uint) (uint, uint) {
	divisor_count := uint(0)
	divisor_sum := uint(0)
	for i := uint(1); ; i++ {
		j := n / i
		if j < i {
			break
		}
		if i*j!= n {
			continue
		}
		divisor_sum += i
		divisor_count += 1
		if i!= j {
			divisor_sum += j
			divisor_count += 1
		}
	}
	return divisor_count, divisor_sum
}

func main() {
	arithmetic_count := uint(0)
	composite_count := uint(0)

	for n := uint(1); arithmetic_count <= 1000000; n++ {
		divisor_count, divisor_sum := divisor_count_and_sum(n)
		mean := divisor_sum / divisor_count
		if mean*divisor_count!= divisor_sum {
			continue
		}
		arithmetic_count++
		if divisor_count > 2 {
			composite_count++
		}
		if arithmetic_count <= 100 {
			fmt.Printf("%3d ", n)
			if arithmetic_count%10 == 0 {
				fmt.Printf("\n")
			}
		}
		if arithmetic_count == 1000 || arithmetic_count == 10000 || arithmetic_count == 100000 || arithmetic_count == 1000000 {
			fmt.Printf("\n%uth arithmetic number is %d\n", arithmetic_count, n)
			fmt.Printf("Number of composite arithmetic numbers <= %d: %d\n", n, composite_count)
		}
	}
}

package main
 
import "fmt"
 
func stoogesort(a []int) {
    len := len(a)
 
    if a[0] > a[len-1] {
        a[0], a[len-1] = a[len-1], a[0]
    }
    if len-1 > 1 {
        t := len / 3
        stoogesort(a[:len-1])
        stoogesort(a[t:])
        stoogesort(a[:len-1])
    }
}
 
func main() {
    numbers := []int{1, 9, 4, 7, 6, 5, 3, 2, 8}
    fmt.Println("Before:", numbers)
    stoogesort(numbers)
    fmt.Println("After:", numbers)
}

package main

import (
	"fmt"
	"io/ioutil"
	"net/http"
	"sort"
	"strings"
)

func main() {
	client := &http.Client{}
	req, _ := http.NewRequest("GET", "http://www.puzzlers.org/pub/wordlists/unixdict.txt", nil)
	resp, _ := client.Do(req)
	defer resp.Body.Close()
	body, _ := ioutil.ReadAll(resp.Body)
	words := strings.Split(string(body), "\n")

	var query []string
	for _, w := range words {
		if isOrderedWord(w) {
			query = append(query, w)
		}
	}
	sort.Sort(sort.Reverse(sort.StringSlice(query)))
	fmt.Println(strings.Join(query, ", "))
}

func isOrderedWord(w string) bool {
	for i := 1; i < len(w); i++ {
		if w[i] < w[i-1] {
			return false
		}
	}
	return true
}

package main
 
import (
    "fmt"
    "math/rand"
    "math"
)
 
func decimal_to_rational (n float64) (int, int) {
    //Based on Farey sequences
    if math.IsInf(n, 0) { panic("The number is infinite") }
    flag_neg  := n < 0.0
    if flag_neg { n = n*(-1.0) }
    if n < math.SmallestNonzeroFloat64 { return 0,1 }
    if math.Abs(n - math.Round(n)) < math.SmallestNonzeroFloat64 { return int(math.Round(n)), 1 }
    a := 0
    b := 1
    c := int(math.Ceil(n))
    d := 1
    aux1 := int(math.MaxInt64/2)
    for c < aux1  && d < aux1 {
        aux2 := (float64(a) + float64(c))/(float64(b) + float64(d))
        if math.Abs(n - aux2) < math.SmallestNonzeroFloat64 { break } 
        if n > aux2 { 
            a = a + c
            b = b + d
        } else {
            c = a + c
            d = b + d
        }
    }
    // Make sure that the fraction is irreducible
    gcd := GCD(a+c, b+d)
    if flag_neg { return -(a + c)/gcd, (b + d)/gcd } else { return (a + c)/gcd, (b + d)/gcd }
} 
 
func GCD(a, b int) int {
    for b!= 0 {
        t := b
        b = a % b
        a = t
    }
    return a
}
 
func main () {
    for i := 0; i < 10; i++ {
        number := rand.Float64()
        result := decimal_to_rational(number)
        if result[1] == 1 { fmt.Printf("%f -> %d\n", number, result[0]) } else { fmt.Printf("%f ->  %d/%d\n", number, result[0], result[1]) }
    }
    for _, i := range []float64{-0.9054054, 0.518518, -0.75, 0.5185185185185185, -0.9054054054054054, 0.0, 1.0, 2.0} {
        result := decimal_to_rational(i)
        if result[1] == 1 { fmt.Printf("%f = %d\n", i, result[0]) } else { fmt.Printf("%f =  %d/%d\n", i, result[0], result[1]) }
    }
}

