func relativeBearing(b1Rad, b2Rad float64) float64 {
	b1y := math.Cos(b1Rad)
	b1x := math.Sin(b1Rad)
	b2y := math.Cos(b2Rad)
	b2x := math.Sin(b2Rad)
	crossp := b1y*b2x - b2y*b1x
	dotp := b1x*b2x + b1y*b2y
	if crossp > 0. {
		return math.Acos(dotp)
	}
	return -math.Acos(dotp)
}

