package main

import (
	"fmt"
	"strconv"
)

const MAX = 10000000

var primes = make([]bool, MAX)

func main() {
	sieve()
	fmt.Println("First 35 unprimeable numbers:")
	displayUnprimeableNumbers(35)
	n := 600
	fmt.Printf("\nThe %dth unprimeable number = %,d%n%n", n, nthUnprimeableNumber(n))
	lowest := genLowest()
	fmt.Println("Least unprimeable number that ends in:")
	for i := 0; i <= 9; i++ {
		fmt.Printf(" %d is %,d%n", i, lowest[i])
	}
}

func genLowest() []int {
	lowest := make([]int, 10)
	count := 0
	test := 1
	for count < 10 {
		test++
		if unPrimable(test) && lowest[test%10] == 0 {
			lowest[test%10] = test
			count++
		}
	}
	return lowest
}

func nthUnprimeableNumber(maxCount int) int {
	test := 1
	count := 0
	result := 0
	for count < maxCount {
		test++
		if unPrimable(test) {
			count++
			result = test
		}
	}
	return result
}

func displayUnprimeableNumbers(maxCount int) {
	test := 1
	count := 0
	for count < maxCount {
		test++
		if unPrimable(test) {
			count++
			fmt.Printf("%d ", test)
		}
	}
	fmt.Println()
}

func unPrimable(test int) bool {
	if primes[test] {
		return false
	}
	s := strconv.Itoa(test)
	for i := 0; i < len(s); i++ {
		for j := 0; j <= 9; j++ {
			if primes[parseInt(replace(s, i, j))] {
				return false
			}
		}
	}
	return true
}

func replace(str string, position int, value int) string {
	sChar := []byte(str)
	sChar[position] = byte(value)
	return string(sChar[:position]) + strconv.Itoa(value) + string(sChar[position+1:])
}

func sieve() {
	//  primes
	for i := 2; i < MAX; i++ {
		primes[i] = true
	}
	for i := 2; i < MAX; i++ {
		if primes[i] {
			for j := 2 * i; j < MAX; j += i {
				primes[j] = false
			}
		}
	}
}

func parseInt(str string) int {
	i, _ := strconv.Atoi(str)
	return i
}

package main
 
import (
    "fmt"
)
 
const MAX = 10000000 + 1000
 
var primes = make([]bool, MAX)
 
func main() {
    sieve()
 
    fmt.Println("First 36 strong primes:")
    displayStrongPrimes(36)
    for _, n := range []int{1000000, 10000000} {
        fmt.Printf("Number of strong primes below %,d = %,d\n", n, strongPrimesBelow(n))
    }
 
    fmt.Println("First 37 weak primes:")
    displayWeakPrimes(37)
    for _, n := range []int{1000000, 10000000} {
        fmt.Printf("Number of weak primes below %,d = %,d\n", n, weakPrimesBelow(n))
    }
}
 
func weakPrimesBelow(maxPrime int) int {
    priorPrime := 2
    currentPrime := 3
    count := 0
    for currentPrime < maxPrime {
        nextPrime := getNextPrime(currentPrime)
        if currentPrime*2 < priorPrime+nextPrime {
            count++
        }
        priorPrime = currentPrime
        currentPrime = nextPrime
    }
    return count
}
 
func displayWeakPrimes(maxCount int) {
    priorPrime := 2
    currentPrime := 3
    count := 0
    for count < maxCount {
        nextPrime := getNextPrime(currentPrime)
        if currentPrime*2 < priorPrime+nextPrime {
            count++
            fmt.Printf("%d ", currentPrime)
        }
        priorPrime = currentPrime
        currentPrime = nextPrime
    }
    fmt.Println()
}
 
func getNextPrime(currentPrime int) int {
    nextPrime := currentPrime + 2
    for!primes[nextPrime] {
        nextPrime += 2
    }
    return nextPrime
}
 
func strongPrimesBelow(maxPrime int) int {
    priorPrime := 2
    currentPrime := 3
    count := 0
    for currentPrime < maxPrime {
        nextPrime := getNextPrime(currentPrime)
        if currentPrime*2 > priorPrime+nextPrime {
            count++
        }
        priorPrime = currentPrime
        currentPrime = nextPrime
    }
    return count
}
 
func displayStrongPrimes(maxCount int) {
    priorPrime := 2
    currentPrime := 3
    count := 0
    for count < maxCount {
        nextPrime := getNextPrime(currentPrime)
        if currentPrime*2 > priorPrime+nextPrime {
            count++
            fmt.Printf("%d ", currentPrime)
        }
        priorPrime = currentPrime
        currentPrime = nextPrime
    }
    fmt.Println()
}
 
func sieve() { //  primes
    for i := 2; i < MAX; i++ {
        primes[i] = true
    }
    for i := 2; i < MAX; i++ {
        if primes[i] {
            j := 2 * i
            for j < MAX {
                primes[j] = false
                j += i
            }
        }
    }
}

