package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

func menuSelect(question string, choices []string) string {
	if len(choices) == 0 {
		return ""
	}

	prompt := ""
	for i, choice := range choices {
		prompt += fmt.Sprintf("%d. %s\n", i+1, choice)
	}

	inputChoice := -1
	for inputChoice < 1 || inputChoice > len(choices) {
		inputChoice = getSelection(fmt.Sprintf("\n%s%s: ", prompt, question))
	}

	return choices[inputChoice-1]
}

func getSelection(prompt string) int {
	reader := bufio.NewReader(os.Stdin)
	fmt.Print(prompt)
	response, _ := reader.ReadString('\n')
	inputChoice, _ := strconv.Atoi(response)
	return inputChoice
}

func main() {
	choices := []string{"fee fie", "huff and puff", "mirror mirror", "tick tock"}
	question := "Which is from the three pigs?"
	answer := menuSelect(question, choices)
	fmt.Printf("\nYou chose %s", answer)
}

