package main

import (
	"fmt"
	"reflect"
)

type TestClass struct {
	privateField int
	PublicNumber int
	PrivateNumber int
}

func main() {
	t := TestClass{}
	flags := reflect.Public | reflect.NonPublic | reflect.Instance
	for _, prop := range GetPropertyValues(&t, flags) {
		fmt.Println(prop)
	}
	for _, field := range GetFieldValues(&t, flags) {
		fmt.Println(field)
	}
}

func GetPropertyValues(obj interface{}, flags reflect.BindingFlag) []interface{} {
	var result []interface{}
	t := reflect.TypeOf(obj)
	for i := 0; i < t.NumField(); i++ {
		f := t.Field(i)
		if f.GetIndexParameters().Length == 0 {
			result = append(result, f.Name, f.GetValue(obj, nil))
		}
	}
	return result
}

func GetFieldValues(obj interface{}, flags reflect.BindingFlag) []interface{} {
	var result []interface{}
	t := reflect.TypeOf(obj)
	for i := 0; i < t.NumField(); i++ {
		f := t.Field(i)
		result = append(result, f.Name, f.GetValue(obj))
	}
	return result
}

