func k2c(k float64) float64 {
    return k - 273.15
}
 
func k2r(k float64) float64 {
    return k * 1.8
}
 
func k2f(k float64) float64 {
    return k2r(k) - 459.67
}
 
func toMaxDecimal(f float64, d int) float64 {
    return math.Round(f*math.Pow(10, float64(d))) / math.Pow(10, float64(d))
}
 
func kCnv(k float64) {
    fmt.Printf("%.2fK° = %.2fC° = %.2fR° = %.2fF°\n", k, toMaxDecimal(k2c(k), 2), toMaxDecimal(k2r(k), 2), toMaxDecimal(k2f(k), 2))
}
 
