    kCnv(295)
}

package main
 
import (
    "fmt"
    "math"
)
 
func main() {
    fmt.Println("First 20 primes:\n", primes(20))
    fmt.Println("Primes between 100 and 150:\n", primesBetween(100, 150))
    fmt.Println("There are", countPrimes(8000)-countPrimes(7700), "primes between 7,700 and 8,000")
    fmt.Println("The 10,000th prime is", primes(10000)[9999])
}
 
func primes(n int) []int {
    var primes []int
    for i := 2; len(primes) < n; i++ {
        if isPrime(i) {
            primes = append(primes, i)
        }
    }
    return primes
}
 
func primesBetween(a, b int) []int {
    var primes []int
    for i := a; i < b; i++ {
        if isPrime(i) {
            primes = append(primes, i)
        }
    }
    return primes
}
 
func countPrimes(n int) int {
    count := 0
    for i := 2; i < n; i++ {
        if isPrime(i) {
            count++
        }
    }
    return count
}
 
func isPrime(n int) bool {
    if n < 2 {
        return false
    }
    if n == 2 {
        return true
    }
    if n%2 == 0 {
        return false
    }
    for i := 3; i <= int(math.Sqrt(float64(n))); i += 2 {
        if n%i == 0 {
            return false
        }
    }
    return true
}

package main
 
import (
	"fmt"
	"strings"
)
 
func soundex(word string) string {
	codes := []string{"bfpv", "cgjkqsxz", "dt", "l", "mn", "r"}
	soundDict := make(map[string]string)
	for ix, cod := range codes {
		for _, ch := range cod {
			soundDict[string(ch)] = string(ix + 1)
		}
	}
	cmap2 := func(kar string) string {
		if val, ok := soundDict[kar]; ok {
			return val
		} else {
			return "9"
		}
	}
	sdx := ""
	for _, kar := range strings.ToLower(word) {
		sdx += cmap2(string(kar))
	}
	sdx2 := word[0:1] + strings.Join(strings.Split(sdx, "")[1:], "")
	sdx3 := sdx2[0:4] + strings.Repeat("0", 4-len(sdx2))
	return sdx3
}
 
func main() {
	fmt.Println(soundex("Robert"))
	fmt.Println(soundex("Rupert"))
}

