package main

import (
	"fmt"
	"math/big"
)

func isProbablyPrime(n *big.Int) bool {
	return n.ProbablyPrime(30)
}

func jacobsthalNumber(n uint) *big.Int {
	return new(big.Int).Div(new(big.Int).Sub(new(big.Int).Lsh(big.NewInt(1), n), big.NewInt(int64(n%2 == 0))), big.NewInt(3))
}

func jacobsthalLucasNumber(n uint) *big.Int {
	return new(big.Int).Add(new(big.Int).Lsh(big.NewInt(1), n), big.NewInt(int64(n%2 == 0)))
}

func jacobsthalOblongNumber(n uint) *big.Int {
	return new(big.Int).Mul(jacobsthalNumber(n), jacobsthalNumber(n+1))
}

func main() {
	fmt.Println("First 30 Jacobsthal Numbers:")
	for n := uint(0); n < 30; n++ {
		fmt.Printf("%9d%s", jacobsthalNumber(n), (n+1)%5 == 0? "\n" : " ")
	}
	fmt.Println("\nFirst 30 Jacobsthal-Lucas Numbers:")
	for n := uint(0); n < 30; n++ {
		fmt.Printf("%9d%s", jacobsthalLucasNumber(n), (n+1)%5 == 0? "\n" : " ")
	}
	fmt.Println("\nFirst 20 Jacobsthal oblong Numbers:")
	for n := uint(0); n < 20; n++ {
		fmt.Printf("%11d%s", jacobsthalOblongNumber(n), (n+1)%5 == 0? "\n" : " ")
	}
	fmt.Println("\nFirst 20 Jacobsthal primes:")
	for n, count := uint(0), 0; count < 20; n++ {
		jn := jacobsthalNumber(n)
		if isProbablyPrime(jn) {
			count++
			fmt.Println(jn)
		}
	}
}

package main
 
import (
	"fmt"
	"time"
)
 
func factorial(n int) int {
	if n == 0 {
		return 1
	}
	return n * factorial(n-1)
}
 
func catalan_direct(n int) int {
	return factorial(2*n) / (factorial(n+1) * factorial(n))
}
 
func catalan_rec1(n int) int {
	if n == 0 {
		return 1
	}
	sum := 0
	for i := 0; i < n; i++ {
		sum += catalan_rec1(i) * catalan_rec1(n-1-i)
	}
	return sum
}
 
func catalan_rec2(n int) int {
	if n == 0 {
		return 1
	}
	return 2 * (2*n - 1) * catalan_rec2(n-1) / (n + 1)
}
 
func main() {
	start := time.Now()
	for n := 0; n < 16; n++ {
		catalan_direct(n)
	}
	fmt.Println("catalan_direct:", time.Since(start))
	start = time.Now()
	for n := 0; n < 16; n++ {
		catalan_rec1(n)
	}
	fmt.Println("catalan_rec1:", time.Since(start))
	start = time.Now()
	for n := 0; n < 16; n++ {
		catalan_rec2(n)
	}
	fmt.Println("catalan_rec2:", time.Since(start))
	start = time.Now()
	for n := 0; n < 16; n++ {
		catalan_rec1(n)
	}
	fmt.Println("catalan_rec1(memo):", time.Since(start))
	fmt.Println()
	fmt.Println("       direct     rec1     rec2")
	for n := 0; n < 16; n++ {
		fmt.Printf("%2d :%9d%9d%9d\n", n, catalan_direct(n), catalan_rec1(n), catalan_rec2(n))
	}
}

