import (
	"fmt"
	"strings"
)
 
func EncodeNegBase(n int, b int) string { //Converts from decimal
	if n == 0 {
		return "0"
	}
	out := []string{}
	for n!= 0 {
		n, rem := n/b, n%b
		if rem < 0 {
			n += 1
			rem -= b
		}
		out = append(out, fmt.Sprintf("%d", rem))
	}
	return strings.Join(out, "")
}
 
func DecodeNegBase(nstr string, b int) int { //Converts to decimal
	if nstr == "0" {
		return 0
	}
	total := 0
	for i, ch := range nstr {
		total += int(ch-'0') * int(b)
	}
	return total
}
 
func main() {
	fmt.Println("Encode 10 as negabinary (expect 11110)")
	result := EncodeNegBase(10, -2)
	fmt.Println(result)
	if DecodeNegBase(result, -2) == 10 {
		fmt.Println("Converted back to decimal")
	} else {
		fmt.Println("Error converting back to decimal")
	}
 
	fmt.Println("Encode 146 as negaternary (expect 21102)")
	result = EncodeNegBase(146, -3)
	fmt.Println(result)
	if DecodeNegBase(result, -3) == 146 {
		fmt.Println("Converted back to decimal")
	} else {
		fmt.Println("Error converting back to decimal")
	}
 
	fmt.Println("Encode 15 as negadecimal (expect 195)")
	result = EncodeNegBase(15, -10)
	fmt.Println(result)
	if DecodeNegBase(result, -10) == 15 {
		fmt.Println("Converted back to decimal")
	} else {
		fmt.Println("Error converting back to decimal")
	}
}

