import (
	"fmt"
	"strconv"
)

func isSelfDescribing(a int) bool {
	s := strconv.Itoa(a)
	for i := 0; i < len(s); i++ {
		s0 := string(s[i])
		b, _ := strconv.Atoi(s0) // number of times i-th digit must occur for it to be a self describing number
		count := 0
		for j := 0; j < len(s); j++ {
			temp, _ := strconv.Atoi(string(s[j]))
			if temp == i {
				count++
			}
			if count > b {
				return false
			}
		}
		if count!= b {
			return false
		}
	}
	return true
}

func main() {
	for i := 0; i < 100000000; i++ {
		if isSelfDescribing(i) {
			fmt.Println(i)
		}
	}
}

