import (
	"fmt"
	"sort"
	"strconv"
)

func lexicographicalSort(numbers []int) {
	strings := make([]string, len(numbers))
	for i, v := range numbers {
		strings[i] = strconv.Itoa(v)
	}
	sort.Strings(strings)
	for i, v := range strings {
		numbers[i], _ = strconv.Atoi(v)
	}
}

func lexicographicallySortedVector(n int) []int {
	numbers := make([]int, n)
	for i := range numbers {
		numbers[i] = i + 1
	}
	lexicographicalSort(numbers)
	return numbers
}

func printVector(v []int) {
	fmt.Printf("[")
	if len(v) > 0 {
		fmt.Printf("%d", v[0])
		for i := 1; i < len(v); i++ {
			fmt.Printf(",%d", v[i])
		}
	}
	fmt.Printf("]\n")
}

func main() {
	for _, i := range []int{0, 5, 13, 21, -22} {
		fmt.Printf("%d: ", i)
		printVector(lexicographicallySortedVector(i))
	}
}

package main
 
import (
    "fmt"
    "math/big"
)
 
type Frac struct {
    num   *big.Int
    denom *big.Int
}
 
func NewFrac(n, d int64) *Frac {
    if d == 0 {
        panic("d cannot be zero")
    }
 
    nn := big.NewInt(n)
    dd := big.NewInt(d)
    if nn.Cmp(big.NewInt(0)) == 0 {
        dd.SetInt64(1)
    } else if dd.Cmp(big.NewInt(0)) < 0 {
        nn.Neg(nn)
        dd.Neg(dd)
    }
 
    g := big.NewInt(0)
    g.GCD(nil, nil, nn.Abs(nn), dd.Abs(dd))
    if g.Cmp(big.NewInt(1)) > 0 {
        nn.Div(nn, g)
        dd.Div(dd, g)
    }
 
    return &Frac{num: nn, denom: dd}
}
 
func (f *Frac) String() string {
    if f.denom.Cmp(big.NewInt(1)) == 0 {
        return f.num.String()
    }
    return fmt.Sprintf("%s/%s", f.num, f.denom)
}
 
func (f *Frac) Neg() *Frac {
    return NewFrac(-f.num.Int64(), f.denom.Int64())
}
 
func (f *Frac) Add(rhs *Frac) *Frac {
    return NewFrac(f.num.Int64()*rhs.denom.Int64()+f.denom.Int64()*rhs.num.Int64(), rhs.denom.Int64()*f.denom.Int64())
}
 
func (f *Frac) Sub(rhs *Frac) *Frac {
    return NewFrac(f.num.Int64()*rhs.denom.Int64()-f.denom.Int64()*rhs.num.Int64(), rhs.denom.Int64()*f.denom.Int64())
}
 
func (f *Frac) Mul(rhs *Frac) *Frac {
    return NewFrac(f.num.Int64()*rhs.num.Int64(), rhs.denom.Int64()*f.denom.Int64())
}
 
var FRAC_ZERO = NewFrac(0, 1)
var FRAC_ONE = NewFrac(1, 1)
 
func bernoulli(n int64) *Frac {
    if n < 0 {
        panic("n cannot be negative")
    }
 
    a := make([]*Frac, n+1)
    a[0] = FRAC_ZERO
 
    for m := int64(0); m <= n; m++ {
        a[m] = NewFrac(1, m+1)
        for j := m; j > 0; j-- {
            a[j-1] = a[j-1].Sub(a[j]).Mul(NewFrac(j, 1))
        }
    }
 
    if n!= 1 {
        return a[0]
    }
    return a[0].Neg()
}
 
func binomial(n, k int64) int64 {
    if n < 0 {
        panic("n cannot be negative")
    }
    if k < 0 {
        panic("k cannot be negative")
    }
    if n < k {
        panic("n cannot be less than k")
    }
 
    if n == 0 || k == 0 {
        return 1
    }
 
    num := big.NewInt(1)
    for i := k + 1; i <= n; i++ {
        num.Mul(num, big.NewInt(i))
    }
 
    den := big.NewInt(1)
    for i := int64(2); i <= n-k; i++ {
        den.Mul(den, big.NewInt(i))
    }
 
    return num.Div(num, den).Int64()
}
 
func faulhaberTriangle(p int64) []*Frac {
    coeffs := make([]*Frac, p+1)
    coeffs[0] = FRAC_ZERO
    q := NewFrac(1, p+1)
    sign := -1
    for j := int64(0); j <= p; j++ {
        sign = -sign
        coeffs[p-j] = q.Mul(NewFrac(sign, 1)).Mul(NewFrac(binomial(p+1, j), 1)).Mul(bernoulli(j))
    }
    return coeffs
}
 
func main() {
    for i := int64(0); i <= 9; i++ {
        coeffs := faulhaberTriangle(i)
        for _, coeff := range coeffs {
            fmt.Printf("%5s  ", coeff)
        }
        fmt.Println()
    }
}

