package main
 
import (
    "fmt"
    "math"
)
 
func chowla(n int) int {
    if n < 1 {
        panic("argument must be a positive integer")
    }
    sum := 0
    i := 2
    for i*i <= n {
        if n%i == 0 {
            j := n / i
            if i == j {
                sum += i
            } else {
                sum += i + j
            }
        }
        i++
    }
    return sum
}
 
func sieve(limit int) []bool {
    // True denotes composite, false denotes prime.
    // Only interested in odd numbers >= 3
    c := make([]bool, limit)
    for i := 3; i < limit/3; i += 2 {
        if!c[i] && chowla(i) == 0 {
            for j := 3 * i; j < limit; j += 2 * i {
                c[j] = true
            }
        }
    }
    return c
}
 
func main() {
    for i := 1; i <= 37; i++ {
        fmt.Printf("chowla(%2d) = %d\n", i, chowla(i))
    }
    fmt.Println()
 
    count := 1
    limit := 10_000_000
    c := sieve(limit)
    power := 100
    for i := 3; i < limit; i += 2 {
        if!c[i] {
            count++
        }
        if i == power-1 {
            fmt.Printf("Count of primes up to %,-10d = %,d\n", power, count)
            power *= 10
        }
    }
 
    fmt.Println()
    count = 0
    limit = 35_000_000
    i := 2
    for {
        p := (1 << (i - 1)) * ((1 << i) - 1) // perfect numbers must be of this form
        if p > limit {
            break
        }
        if chowla(p) == p-1 {
            fmt.Printf("%,d is a perfect number\n", p)
            count++
        }
        i++
    }
    fmt.Printf("There are %d perfect numbers <= 35,000,000\n", count)
}

package main
 
import (
    "fmt"
)
 
func hashJoin(table1 [][]string, index1 int, table2 [][]string, index2 int) [][]string {
    h := make(map[string][]string)
    // hash phase
    for _, s := range table1 {
        h[s[index1]] = append(h[s[index1]], s...)
    }
    // join phase
    var result [][]string
    for _, r := range table2 {
        for _, s := range h[r[index2]] {
            result = append(result, []string{s, r[0]})
        }
    }
    return result
}
 
func main() {
    table1 := [][]string{
        {"27", "Jonah"},
        {"18", "Alan"},
        {"28", "Glory"},
        {"18", "Popeye"},
        {"28", "Alan"},
    }
    table2 := [][]string{
        {"Jonah", "Whales"},
        {"Jonah", "Spiders"},
        {"Alan", "Ghosts"},
        {"Alan", "Zombies"},
        {"Glory", "Buffy"},
    }
    for _, row := range hashJoin(table1, 1, table2, 0) {
        fmt.Println(row)
    }
}

