func unique(ary []interface{}) []interface{} {
    u := make([]interface{}, len(ary))
    copy(u, ary)
    sort.Sort(ByString(u))
    for i := 1; i < len(u); {
        if u[i-1] == u[i] {
            u = append(u[:i], u[i+1:]...)
        } else {
            i++
        }
    }
    return u
}

type ByString []interface{}

func (a ByString) Len() int           { return len(a) }
func (a ByString) Swap(i, j int)      { a[i], a[j] = a[j], a[i] }
func (a ByString) Less(i, j int) bool { return a[i].(string) < a[j].(string) }

