    }
}

func (list *LinkedList) InsertAfter(searchValue string, nodeToInsert *LinkedList) {
    if list.Value == searchValue {
        nodeToInsert.Next = list.Next
        list.Next = nodeToInsert
    } else if list.Next == nil {
        panic(fmt.Sprintf("value '%s' not found in linked list.", searchValue))
    } else {
        list.Next.InsertAfter(searchValue, nodeToInsert)
    }
}

