import (
	"fmt"
	"math"
)

var n = 61
var l = []int{0, 1}

func fusc(n int) int {
	if n < len(l) {
		return l[n]
	}
	var f int
	if (n & 1) == 0 {
		f = l[n >> 1]
	} else {
		f = l[(n-1)>>1] + l[(n+1)>>1]
	}
	l = append(l, f)
	return f
}

func main() {
	var lst = true
	var w = -1
	var c = 0
	var t int
	var fs = "%011d  %9d"
	var res = ""
	fmt.Printf("First %d numbers in the fusc sequence:\n", n)
	for i := 0; i < math.MaxInt32; i++ {
		var f = fusc(i)
		if lst {
			if i < 61 {
				fmt.Printf("%d ", f)
			} else {
				lst = false
				fmt.Println()
				fmt.Println("Points in the sequence where an item has more digits than any previous items:")
				fmt.Println(fs, "Index\\", "/Value")
				fmt.Println(res)
				res = ""
			}
		}
		if (t = len(fmt.Sprintf("%d", f))) > w {
			w = t
			res += fmt.Sprintf(fs, i, f)
			if!lst {
				fmt.Println(res)
				res = ""
			}
			if c > 5 {
				break
			}
		}
	}
	l = nil
}

