package main
 
import (
    "fmt"
)
 
func egyptianDivmod(dividend, divisor int) (int, int) {
    assert(divisor!= 0)
    pwrs, dbls := []int{1}, []int{divisor}
    for dbls[len(dbls)-1] <= dividend {
        pwrs = append(pwrs, pwrs[len(pwrs)-1]*2)
        dbls = append(dbls, pwrs[len(pwrs)-1]*divisor)
    }
    ans, accum := 0, 0
    for i := len(pwrs) - 2; i >= 0; i-- {
        if accum+dbls[i] <= dividend {
            accum += dbls[i]
            ans += pwrs[i]
        }
    }
    return ans, abs(accum - dividend)
}
 
func assert(x bool) {
    if!x {
        panic("assertion failed")
    }
}
 
func abs(x int) int {
    if x < 0 {
        return -x
    }
    return x
}
 
func main() {
    // Test it gives the same results as the divmod built-in
    for i := 0; i < 13; i++ {
        for j := 1; j < 13; j++ {
            assert(egyptianDivmod(i, j) == divmod(i, j))
        }
    }
    // Mandated result
    i, j := 580, 34
    fmt.Printf("%d divided by %d using the Egyption method is %d remainder %d\n",
        i, j, egyptianDivmod(i, j))
}
 
func divmod(dividend, divisor int) (int, int) {
    return dividend / divisor, dividend % divisor
}

package main

import (
	"fmt"
	"io/ioutil"
	"os"
)

func main() {
	// Open a file for reading.
	file, err := os.Open("test.txt")
	if err!= nil {
		fmt.Println(err)
		return
	}
	defer file.Close()

	// Get file size.
	stat, err := file.Stat()
	if err!= nil {
		fmt.Println(err)
		return
	}
	// Read file into buffer.
	bs := make([]byte, stat.Size())
	_, err = file.Read(bs)
	if err!= nil {
		fmt.Println(err)
		return
	}
	str := string(bs)
	fmt.Println(str)

	// Write a new string to file.
	_, err = file.WriteString("writes\n")
	if err!= nil {
		fmt.Println(err)
		return
	}

	// Save changes to file.
	err = file.Sync()
	if err!= nil {
		fmt.Println(err)
		return
	}

	// Truncate file.
	err = os.Truncate("test.txt", 10)
	if err!= nil {
		fmt.Println(err)
		return
	}

	// Write bytes to file.
	err = ioutil.WriteFile("test.txt", []byte{115, 111, 109, 101, 10}, 0644)
	if err!= nil {
		fmt.Println(err)
		return
	}
}

