package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
)

type ITransform interface {
	transform(ch byte) byte
}

type Encrypt struct {
}

func (e *Encrypt) transform(ch byte) byte {
	if ch >= 'a' && ch <= 'z' {
		ch = str[ch-'a']
	}
	return ch
}

type Decrypt struct {
}

func (d *Decrypt) transform(ch byte) byte {
	if ch >= 'a' && ch <= 'z' {
		ch = byte(str.Index(string(ch)) + 'a')
	}
	return ch
}

type TransformWriter struct {
	outs  io.Writer
	trans ITransform
}

func (tw *TransformWriter) Write(buf []byte) (int, error) {
	for i := 0; i < len(buf); i++ {
		buf[i] = tw.trans.transform(buf[i])
	}
	return tw.outs.Write(buf)
}

func doEncDec(source, target string, isEncrypt bool) {
	var trans ITransform
	if isEncrypt {
		trans = &Encrypt{}
	} else {
		trans = &Decrypt{}
	}

	sfi, _ := os.Open(source)
	defer sfi.Close()
	sr := bufio.NewReader(sfi)

	tfi, _ := os.Create(target)
	defer tfi.Close()
	tw := &TransformWriter{outs: tfi, trans: trans}
	sw := bufio.NewWriter(tw)

	line, _ := sr.ReadString('\n')
	for line!= "" {
		sw.WriteString(line)
		line, _ = sr.ReadString('\n')
	}
	sw.Flush()
}

func main() {
	doEncDec("e:\\source.txt", "enc.txt", true)
	doEncDec("enc.txt", "dec.txt", false)
	fmt.Println("Done")
}

