}

func writeFile(strPath, strText string) error {
	return ioutil.WriteFile(strPath, []byte(strText), 0644)
}

func main() {
	delimCSV := ",\\s*"

	strSummed := unlines(
		lines(readFile("~/csvSample.txt"))
		.map(func (x, i) {
			xs := x? splitRegex(delimCSV, x) : []

			return (xs.length? xs.concat(
				// 'SUM' appended to first line, others summed.
				i > 0? xs.reduce(
					func (a, b) {
						return a + parseInt(b, 10)
					}, 0
				).toString() : 'SUM'
			) : []).join(',');
		})
	)

	writeFile("~/csvSampleSummed.txt", strSummed)
	fmt.Println(strSummed)
}

package main

import (
    "fmt"
    "sort"
)

func Merge2(source1, source2 []int) []int {
    var q1 = make([]int, len(source1))
    copy(q1, source1)
    var q2 = make([]int, len(source2))
    copy(q2, source2)
    var result []int
    for len(q1) > 0 && len(q2) > 0 {
        if q1[0] <= q2[0] {
            result = append(result, q1[0])
            q1 = q1[1:]
        } else {
            result = append(result, q2[0])
            q2 = q2[1:]
        }
    }
    if len(q1) > 0 {
        result = append(result, q1...)
    }
    if len(q2) > 0 {
        result = append(result, q2...)
    }
    return result
}

type Queue []int

func (q *Queue) Len() int {
    return len(*q)
}

func (q *Queue) Less(i, j int) bool {
    return (*q)[i] < (*q)[j]
}

func (q *Queue) Swap(i, j int) {
    (*q)[i], (*q)[j] = (*q)[j], (*q)[i]
}

func (q *Queue) Push(x interface{}) {
    *q = append(*q, x.(int))
}

func (q *Queue) Pop() interface{} {
    old := *q
    n := len(old)
    x := old[n-1]
    *q = old[0 : n-1]
    return x
}

func MergeN(sources...[]int) []int {
    var queues []Queue
    for _, source := range sources {
        if len(source) > 0 {
            queues = append(queues, source)
        }
    }
    sort.Sort(sort.Reverse(sort.IntSlice(queues)))
    var result []int
    for len(queues) > 0 {
        q := queues[0]
        queues = queues[1:]
        result = append(result, q[0])
        q = q[1:]
        if len(q) > 0 {
            queues = append(queues, q)
            sort.Sort(sort.Reverse(sort.IntSlice(queues)))
        }
    }
    return result
}

func main() {
    a := []int{1, 4, 7, 10}
    b := []int{2, 5, 8, 11}
    c := []int{3, 6, 9, 12}
    fmt.Println(Merge2(a, b))
    fmt.Println(MergeN(a, b, c))
}

package main
 
import "fmt"
 
type node struct {
    priority int
    data     string
}
 
type heap struct {
    nodes []node
    len   int
    size  int
}
 
func push(h *heap, priority int, data string) {
    if h.len+1 >= h.size {
        if h.size == 0 {
            h.size = 4
        } else {
            h.size = h.size * 2
        }
        h.nodes = make([]node, h.size)
    }
    i := h.len + 1
    j := i / 2
    for i > 1 && h.nodes[j].priority > priority {
        h.nodes[i] = h.nodes[j]
        i = j
        j = j / 2
    }
    h.nodes[i].priority = priority
    h.nodes[i].data = data
    h.len++
}
 
func pop(h *heap) string {
    if h.len == 0 {
        return ""
    }
    data := h.nodes[1].data
 
    h.nodes[1] = h.nodes[h.len]
 
    h.len--
 
    i := 1
    for i!= h.len+1 {
        k := h.len + 1
        j := 2 * i
        if j <= h.len && h.nodes[j].priority < h.nodes[k].priority {
            k = j
        }
        if j+1 <= h.len && h.nodes[j+1].priority < h.nodes[k].priority {
            k = j + 1
        }
        h.nodes[i] = h.nodes[k]
        i = k
    }
    return data
}
 
func main() {
    h := new(heap)
    push(h, 3, "Clear drains")
    push(h, 4, "Feed cat")
    push(h, 5, "Make tea")
    push(h, 1, "Solve RC tasks")
    push(h, 2, "Tax return")
    for i := 0; i < 5; i++ {
        fmt.Println(pop(h))
    }
}

