package main

import (
	"bufio"
	"fmt"
	"io"
	"math/rand"
	"os"
	"sort"
	"strings"
)

func main() {
	dictFile := "unixdict.txt"
	if len(os.Args) > 1 {
		dictFile = os.Args[1]
	}

	dict := make(map[string]string)
	f, err := os.Open(dictFile)
	if err!= nil {
		panic(err)
	}
	defer f.Close()

	r := bufio.NewReader(f)
	for {
		line, err := r.ReadString('\n')
		if err == io.EOF {
			break
		}
		if err!= nil {
			panic(err)
		}
		word := strings.TrimSpace(line)
		dict[word] = reverse(word)
	}

	semordnilaps := make([][2]string, 0)
	for key, _ := range dict {
		if dict[dict[key]]!= "" {
			rev := dict[key]
			if key < rev {
				semordnilaps = append(semordnilaps, [2]string{key, rev})
			}
		}
	}

	count := len(semordnilaps)
	fmt.Printf("There are %d semordnilaps in %s.  Here are 5:\n", count, dictFile)

	indices := make([]int, 5)
	for i := 0; i < count; i++ {
		if rand.Float64() < 1/float64(i/5+1) {
			indices[i%5] = i
		}
	}
	sort.Ints(indices)
	for i := 0; i < 5; i++ {
		fmt.Println(semordnilaps[indices[i]])
	}
}

func reverse(s string) string {
	runes := []rune(s)
	for i, j := 0, len(runes)-1; i < j; i, j = i+1, j-1 {
		runes[i], runes[j] = runes[j], runes[i]
	}
	return string(runes)
}

