type Color struct {
	Red   byte
	Blue  byte
	Green byte
}

type Bitmap struct {
	_imagemap [][]Color
	Width     int
	Height    int
}

func NewBitmap(width int, height int) *Bitmap {
	b := new(Bitmap)
	b.Width = width
	b.Height = height
	b._imagemap = make([][]Color, width)
	for i := 0; i < width; i++ {
		b._imagemap[i] = make([]Color, height)
	}
	return b
}

func (b *Bitmap) Fill(color Color) {
	for y := 0; y < b.Height; y++ {
		for x := 0; x < b.Width; x++ {
			b._imagemap[x][y] = color
		}
	}
}

func (b *Bitmap) GetPixel(x int, y int) Color {
	return b._imagemap[x][y]
}

func (b *Bitmap) SetPixel(x int, y int, color Color) {
	b._imagemap[x][y] = color
}

func main() {
	b := NewBitmap(10, 10)
	b.Fill(Color{Red: 255, Blue: 255, Green: 255})
	fmt.Println(b.GetPixel(0, 0))
	b.SetPixel(0, 0, Color{Red: 0, Blue: 0, Green: 0})
	fmt.Println(b.GetPixel(0, 0))
}

