code:
// Calculate the Digital Root and Additive Persistance of an Integer - Compiles with gcc4.7
//
//. July 23rd., 2012
//
package main

import (
	"fmt"
)

func IncFirst(src pair) pair {
	return pair{src.first + 1, src.second}
}

func DigitalRoot(digits uint64, base int) pair {
	x := SumDigits(digits, base)
	if x < base {
		return pair{1, x}
	} else {
		return IncFirst(DigitalRoot(x, base))
	}
}

func main() {
	ip := []uint64{961038, 923594037444, 670033, 448944221089}
	for _, i := range ip {
		res := DigitalRoot(i, 10)
		fmt.Printf("%d has digital root %d and additive persistance %d\n", i, res.second, res.first)
	}
	fmt.Printf("\n")
	hip := []uint64{0x7e0, 0x14e344, 0xd60141, 0x12343210}
	for _, i := range hip {
		res := DigitalRoot(i, 16)
		fmt.Printf("%x has digital root %d and additive persistance %d\n", i, res.second, res.first)
	}
}

type pair struct {
	first  int
	second int
}

func SumDigits(digits uint64, base int) int {
	var sum int
	for digits > 0 {
		sum += int(digits % uint64(base))
		digits /= uint64(base)
	}
	return sum
}

