package main
 
import (
    "fmt"
    "math/big"
)
 
func nextu(a []*big.Int) []*big.Int {
    n := len(a)
    a = append(a, big.NewInt(1))
    for i := n - 1; i > 0; i-- {
        a[i].Mul(a[i], big.NewInt(int64(i)))
        a[i].Add(a[i], a[i-1])
    }
    return a
}
 
func nextv(a []*big.Int) []*big.Int {
    n := len(a) - 1
    b := make([]*big.Int, n+1)
    for i := 0; i < n+1; i++ {
        b[i] = big.NewInt(0)
    }
    b[0].Mul(a[0], big.NewInt(int64(1-n)))
    for i := 0; i < n; i++ {
        b[i+1].Add(b[i+1], a[i])
    }
    b[n].Add(b[n], big.NewInt(1))
    return b
}
 
func sumpol(n int) [][]*big.Int {
    u := []*big.Int{big.NewInt(0), big.NewInt(1)}
    v := [][]*big.Int{{big.NewInt(1)}, {big.NewInt(1), big.NewInt(1)}}
    r := make([][]*big.Int, 0)
    r = append(r, []*big.Int{big.NewInt(0), big.NewInt(1)})
    for i := 1; i < n; i++ {
        v = append(v, nextv(v[i]))
        t := make([]*big.Int, i+2)
        for j := 0; j < i+2; j++ {
            t[j] = big.NewInt(0)
        }
        p := big.NewInt(1)
        for j, r := range u {
            r = big.NewInt(0).Set(r)
            r.Div(r, big.NewInt(int64(j+1)))
            for k, s := range v[j+1] {
                t[k].Add(t[k], big.NewInt(0).Mul(r, s))
            }
        }
        r = append(r, t)
        u = nextu(u)
    }
    return r
}
 
func polstr(a []*big.Int) string {
    s := ""
    q := false
    n := len(a) - 1
    for i, x := range a {
        i = n - i
        if i < 2 {
            m := "n"
            if i == 1 {
                m = ""
            }
        } else {
            m = fmt.Sprintf("n^%d", i)
        }
        c := fmt.Sprintf("%d", x.Abs(x))
        if i > 0 {
            if c == "1" {
                c = ""
            } else {
                m = " " + m
            }
        }
        if x.Cmp(big.NewInt(0))!= 0 {
            if q {
                t := " + "
                if x.Cmp(big.NewInt(0)) < 0 {
                    t = " - "
                }
                s += fmt.Sprintf("%s%s%s", t, c, m)
            } else {
                t := ""
                if x.Cmp(big.NewInt(0)) < 0 {
                    t = "-"
                }
                s = fmt.Sprintf("%s%s%s", t, c, m)
                q = true
            }
        }
    }
    if q {
        return s
    } else {
        return "0"
    }
}
 
func main() {
    for i, p := range sumpol(10) {
        fmt.Printf("%d: %s\n", i, polstr(p))
    }
}

package main
 
import (
	"fmt"
)
 
const (
	MASK64 = (1 << 64) - 1
	MASK32 = (1 << 32) - 1
)
 
type Xorshift_star struct {
	state uint64
}
 
func (x *Xorshift_star) next_int() uint32 {
	var x1 uint64
	x1 = x.state
	x1 = x1 ^ (x1 >> 12)
	x1 = (x1 ^ (x1 << 25)) & MASK64
	x1 = x1 ^ (x1 >> 27)
	x.state = x1
	return uint32(((x1 * 0x2545F4914F6CDD1D) & MASK64) >> 32) & MASK32
}
 
func (x *Xorshift_star) next_float() float64 {
	return float64(x.next_int()) / float64(1<<32)
}
 
func main() {
	random_gen := &Xorshift_star{state: 1234567}
	for i := 0; i < 5; i++ {
		fmt.Println(random_gen.next_int())
	}
 
random_gen = &Xorshift_star{state: 987654321}
	tally := make(map[int]int)
	for i := 0; i < 100000; i++ {
		tally[int(random_gen.next_float()*5)] += 1
	}
	for k, v := range tally {
		fmt.Println(k, ":", v)
	}
}

