package main
 
import (
    "fmt"
    "regexp"
    "sort"
    "strconv"
)
 
type Range struct {
    start, end float64
}
 
func (r Range) String() string {
    return fmt.Sprintf("[%f, %f]", r.start, r.end)
}
 
func consolidate(ranges []Range) []Range {
    sort.Slice(ranges, func(i, j int) bool {
        return ranges[i].start < ranges[j].start
    })
 
    consolidatedRanges := make([]Range, 0, len(ranges))
    for i := len(ranges) - 1; i >= 0; i-- {
        range := ranges[i]
        if len(consolidatedRanges) == 0 {
            consolidatedRanges = append(consolidatedRanges, range)
        } else if range.end >= consolidatedRanges[0].end {
            consolidatedRanges[0] = range
        } else if range.end >= consolidatedRanges[0].start {
            consolidatedRanges[0] = Range{start: range.start, end: consolidatedRanges[0].end}
        } else {
            consolidatedRanges = append([]Range{range}, consolidatedRanges...)
        }
    }
 
    return consolidatedRanges
}
 
var rangeRegex = regexp.MustCompile(`\[(.+),(.+)\]`)
 
func parseDoubleRange(rangeStr string) (Range, error) {
    parts := rangeRegex.FindStringSubmatch(rangeStr)
    if len(parts)!= 3 {
        return Range{}, fmt.Errorf("Unable to parse range %s", rangeStr)
    }
 
    start, err := strconv.ParseFloat(parts[1], 64)
    if err!= nil {
        return Range{}, err
    }
 
    end, err := strconv.ParseFloat(parts[2], 64)
    if err!= nil {
        return Range{}, err
    }
 
    return Range{start: start, end: end}, nil
}
 
func consolidateDoubleRanges(rangeStrings []string) ([]string, error) {
    ranges := make([]Range, 0, len(rangeStrings))
    for _, rangeStr := range rangeStrings {
        range, err := parseDoubleRange(rangeStr)
        if err!= nil {
            return nil, err
        }
        ranges = append(ranges, range)
    }
 
    consolidatedRanges := consolidate(ranges)
    result := make([]string, 0, len(consolidatedRanges))
    for _, range := range consolidatedRanges {
        result = append(result, range.String())
    }
 
    return result, nil
}
 
func main() {
    inputRanges := [][]string{
        []string{"[1.1, 2.2]"},
        []string{"[6.1, 7.2]", "[7.2, 8.3]"},
        []string{"[4, 3]", "[2, 1]"},
        []string{"[4, 3]", "[2, 1]", "[-1, -2]", "[3.9, 10]"},
        []string{"[1, 3]", "[-6, -1]", "[-4, -5]", "[8, 2]", "[-6, -6]"},
    }
 
    for _, inputRange := range inputRanges {
        result, err := consolidateDoubleRanges(inputRange)
        if err!= nil {
            fmt.Println(err)
            continue
        }
        fmt.Printf("%v => %v\n", inputRange, result)
    }
}

package main
 
import (
  "fmt"
  "os"
  "bufio"
  "strings"
)
 
var sedol_weights = []int{1, 3, 1, 7, 3, 9}
var reject = "AEIOUaeiou"
 
func sedol_checksum(sedol6 string) int {
  len := len(sedol6)
  sum := 0
  if len == 7 {
    fmt.Fprintf(os.Stderr, "SEDOL code already checksummed? (%s)\n", sedol6)
    return int(sedol6[6]) & 0x7f
  }
  if (len > 7) || (len < 6) || (strings.IndexAny(sedol6, reject)!= 6) {
    fmt.Fprintf(os.Stderr, "not a SEDOL code? (%s)\n", sedol6)
    return -1
  }
  for i := 0; i < 6; i++ {
    if sedol6[i] >= '0' && sedol6[i] <= '9' {
      sum += (int(sedol6[i])-'0')*sedol_weights[i]
    } else if sedol6[i] >= 'A' && sedol6[i] <= 'Z' {
      sum += (int(sedol6[i])-'A' + 10)*sedol_weights[i]
    } else if sedol6[i] >= 'a' && sedol6[i] <= 'z' {
      sum += (int(sedol6[i])-'a' + 10)*sedol_weights[i]
    } else {
      fmt.Fprintf(os.Stderr, "SEDOL with not alphanumeric digit\n")
      return -1
    }
  }
  return (10 - (sum%10))%10 + '0'
}
 
func main() {
  scanner := bufio.NewScanner(os.Stdin)
  for scanner.Scan() {
    line := scanner.Text()
    sr := sedol_checksum(line)
    if sr > 0 {
      fmt.Printf("%s%c\n", line, sr)
    }
  }
}

