func happy(n int) bool {
	if n == 1 {
		return true
	}
	if seen_numbers[n] {
		return happy_numbers[n]
	}
	seen_numbers[n] = true
	digit_squared_sum := 0
	for _, c := range strconv.Itoa(n) {
		digit_squared_sum += int(c-'0') * int(c-'0')
	}
	if happy(digit_squared_sum) {
		happy_numbers[n] = true
		return true
	}
	return false
}

