import (
    "fmt"
    "math/big"
)
 
func main() {
    fmt.Println(big.NewFloat(float64(big.MaxInt64)).Text('f', 0))
    fmt.Println("A sample of permutations from 1 to 12 with exact Integer arithmetic:")
    for n := 1; n <= 12; n++ {
        k := n / 2
        fmt.Printf("%d P %d = %s%n", n, k, permutation(n, k))
    }
 
    fmt.Println()
    fmt.Println("A sample of combinations from 10 to 60 with exact Integer arithmetic:")
    for n := 10; n <= 60; n += 5 {
        k := n / 2
        fmt.Printf("%d C %d = %s%n", n, k, combination(n, k))
    }
 
    fmt.Println()
    fmt.Println("A sample of permutations from 5 to 15000 displayed in floating point arithmetic:")
    fmt.Printf("%d P %d = %s%n", 5, 2, display(permutation(5, 2), 50))
    for n := 1000; n <= 15000; n += 1000 {
        k := n / 2
        fmt.Printf("%d P %d = %s%n", n, k, display(permutation(n, k), 50))
    }
 
    fmt.Println()
    fmt.Println("A sample of combinations from 100 to 1000 displayed in floating point arithmetic:")
    for n := 100; n <= 1000; n += 100 {
        k := n / 2
        fmt.Printf("%d C %d = %s%n", n, k, display(combination(n, k), 50))
    }
 
}
 
func display(val *big.Int, precision int) string {
    s := val.String()
    precision = min(precision, len(s))
    return fmt.Sprintf("%s.%s * 10^%d", s[0:1], s[1:precision], len(s)-1)
}
 
func combination(n, k int) *big.Int {
    //  Select value with smallest intermediate results
    //    combination(n, k) = combination(n, n-k) 
    if n-k < k {
        k = n - k
    }
    result := permutation(n, k)
    for k > 0 {
        result = result.Div(result, big.NewInt(int64(k)))
        k--
    }
    return result
}
 
func permutation(n, k int) *big.Int {
    result := big.NewInt(1)
    for i := n; i >= n-k+1; i-- {
        result = result.Mul(result, big.NewInt(int64(i)))
    }
    return result
}
 
func min(a, b int) int {
    if a < b {
        return a
    }
    return b
}

package main
 
import (
	"fmt"
	"math"
)
 
const pi = math.Pi
 
type vector struct {
	x, y float64
}
 
func initVector(r, theta float64) vector {
	return vector{r * math.Cos(theta), r * math.Sin(theta)}
}
 
func addVector(a, b vector) vector {
	return vector{a.x + b.x, a.y + b.y}
}
 
func subtractVector(a, b vector) vector {
	return vector{a.x - b.x, a.y - b.y}
}
 
func multiplyVector(a vector, b float64) vector {
	return vector{b * a.x, b * a.y}
}
 
func divideVector(a vector, b float64) vector {
	return vector{a.x / b, a.y / b}
}
 
func printVector(a vector) {
	fmt.Printf("%f %c %c %f %c", a.x, 140, (a.y >= 0)+'+', math.Abs(a.y), 150)
}
 
func main() {
	a := initVector(3, pi/6)
	b := initVector(5, 2*pi/3)
 
	fmt.Println("\nVector a : ")
	printVector(a)
 
	fmt.Println("\n\nVector b : ")
	printVector(b)
 
	fmt.Println("\n\nSum of vectors a and b : ")
	printVector(addVector(a, b))
 
	fmt.Println("\n\nDifference of vectors a and b : ")
	printVector(subtractVector(a, b))
 
	fmt.Println("\n\nMultiplying vector a by 3 : ")
	printVector(multiplyVector(a, 3))
 
	fmt.Println("\n\nDividing vector b by 2.5 : ")
	printVector(divideVector(b, 2.5))
}

package main
 
import (
    "bufio"
    "fmt"
    "io"
    "os"
    "sort"
    "strings"
)
 
// Get words from unix dictionary file
func getWords() ([]string, error) {
    var words []string
    // open file
    f, err := os.Open("data/unixdict.txt")
    if err!= nil {
        return nil, err
    }
    // read line by line
    reader := bufio.NewReader(f)
    for {
        line, err := reader.ReadString('\n')
        if err == io.EOF {
            break
        }
        if err!= nil {
            return nil, err
        }
        words = append(words, strings.TrimRight(line, "\n"))
    }
    return words, nil
}
 
// Get the longest deranged anagram in the given list of word if any
func longestDeranged(words []string) (string, string) {
    // sort by length descending then by alphabetical order
    sort.Slice(words, func(i, j int) bool {
        if len(words[i]) == len(words[j]) {
            return words[i] < words[j]
        }
        return len(words[i]) > len(words[j])
    })
    // keep all strings keyed by sorted characters (since anagrams have the same list of sorted characters)
    signatures := make(map[string][]string)
    // save on memory by only keeping in the map strings of the current processed length
    var previousLength int = 1000000
    for _, s := range words {
        // length change, clear the map
        if len(s) < previousLength {
            signatures = make(map[string][]string)
            previousLength = len(s)
        }
        // generate key as sorted characters
        sortedChars := strings.Split(s, "")
        sort.Strings(sortedChars)
        key := strings.Join(sortedChars, "")
        anagrams, ok := signatures[key]
        if!ok {
            anagrams = make([]string, 0)
        }
        // find if any anagram (string with the same sorted character vector) is deranged
        for _, a := range anagrams {
            if isDeranged(a, s) {
                return a, s
            }
        }
        signatures[key] = append(anagrams, s)
    }
    return "", ""
}
 
// check if two strings do NOT have the same character in the same position
func isDeranged(s1 string, s2 string) bool {
    // we zip the character iterators and check we find no position with the same two characters
    for i, _ := range s1 {
        if s1[i] == s2[i] {
            return false
        }
    }
    return true
}
 
// an example main method printing the results
func main() {
    words, err := getWords()
    if err!= nil {
        panic(err)
    }
    s1, s2 := longestDeranged(words)
    if s1 == "" {
        fmt.Println("No deranged anagrams found!")
    } else {
        fmt.Printf("%s %s\n", s1, s2)
    }
}

