package main
 
import "fmt"
 
// returns the highest power of i that is a factor of n,
// and n divided by that power of i
func factor_exponent(n, i int) (int, int) {
	if n%i == 0 {
		a, b := factor_exponent(n/i, i)
		return a + 1, b
	} else {
		return 0, n
	}
}
 
func tau(n int) int {
	for i := 2; i <= n; i++ {
		if n%i == 0 {
			count, next := factor_exponent(n, i)
			return (count + 1) * tau(next)
		}
	}
	return 1
}
 
func main() {
	for i := 1; i <= 100; i++ {
		fmt.Printf("%d ", tau(i))
	}
}

package main

import (
    "fmt"
    "math/rand"
)

const NMAX = 20
const TESTS = 1000000

func avg(n int) float64 {
    sum := 0
    for t := 0; t < TESTS; t++ {
        v := make([]bool, NMAX)
        x := 0
        for!v[x] {
            v[x] = true
            sum++
            x = rand.Intn(n)
        }
    }
    return float64(sum) / TESTS
}

func ana(n int) float64 {
    nn := float64(n)
    term := 1.0
    sum := 1.0
    for i := n - 1; i > 0; i-- {
        term *= float64(i) / nn
        sum += term
    }
    return sum
}

func main() {
    fmt.Println(" N    average    analytical    (error)")
    fmt.Println("===  =========  ============  =========")
    for n := 1; n <= NMAX; n++ {
        a := avg(n)
        b := ana(n)
        fmt.Printf("%3d   %6.4f   %10.4f      (%4.2f%%)\n", n, a, b, (a-b)/b*100.0)
    }
}

package main
 
import (
    "fmt"
    "math"
    "os"
    "strconv"
)
 
type bitsieve uint32
 
func sieve_check(b []bitsieve, v uint) bool {
    if (v!= 2 && (v & 1) == 0) || v < 2 {
        return false
    } else {
        return (b[v>>6] & (1 << (v >> 1 & 31))) == 0
    }
}
 
func sieve(v uint) []bitsieve {
    b := make([]bitsieve, (v>>6)+1)
 
    for i := uint(3); i <= uint(math.Sqrt(float64(v))); i += 2 {
        if (b[i>>6] & (1 << (i >> 1 & 31))) == 0 {
            for j := i * i; j < v; j += (i << 1) {
                b[j>>6] |= (1 << (j >> 1 & 31))
            }
        }
    }
 
    return b
}
 
func max(x, y int) int {
    if x > y {
        return x
    } else {
        return y
    }
}
 
func ulam_get_map(x, y, n int) int {
    x -= (n - 1) / 2
    y -= n / 2
 
    mx := int(math.Abs(float64(x)))
    my := int(math.Abs(float64(y)))
    l := 2 * max(mx, my)
    d := 0
 
    if y >= x {
        d = l*3 + x + y
    } else {
        d = l - x - y
    }
 
    return int(math.Pow(float64(l-1), 2)) + d
}
 
func output_ulam_spiral(n int, glyph rune) {
    /* An even side length does not make sense, use greatest odd value < n */
    n -= n % 2 == 0 ? 1 : 0
 
    mwidth := int(math.Log10(float64(n * n))) + 1
 
    b := sieve(uint(n * n + 1))
    var x, y int
 
    for x = 0; x < n; x++ {
        for y = 0; y < n; y++ {
            z := ulam_get_map(y, x, n)
 
            if glyph == 0 {
                if sieve_check(b, uint(z)) {
                    fmt.Printf("%*d ", mwidth, z)
                } else {
                    fmt.Printf("%*s ", mwidth, "")
                }
            } else {
                if sieve_check(b, uint(z)) {
                    fmt.Printf("%c", glyph)
                } else {
                    fmt.Printf("%c",'')
                }
            }
        }
        fmt.Printf("\n")
    }
}
 
func main() {
    n, _ := strconv.Atoi(os.Args[1])
 
    output_ulam_spiral(n, 0)
    fmt.Printf("\n")
 
    output_ulam_spiral(n, '#')
    fmt.Printf("\n")
}

package main

import (
	"fmt"
	"strings"
)

func collapse(str string) string {
	i := 0
	for j := 1; j < len(str); j++ {
		if str[j]!= str[i] {
			i++
			str[i] = str[j]
		}
	}
	return str[:i+1]
}

func test(str string) {
	fmt.Printf("original string: <<<%s>>>, length = %d\n", str, len(str))
	collapsed := collapse(str)
	fmt.Printf("result string: <<<%s>>>, length = %d\n", collapsed, len(collapsed))
	fmt.Println()
}

func main() {
	test("")
	test("\"If I were two-faced, would I be wearing this one?\" ---  ")
	test("..1111111111111111111111111111111111111111111111111111111111111117777888")
	test("I never give 'em hell, I just tell the truth, and they think it's hell. ")
	test("                                                    ---   ")
}

package main

import (
	"fmt"
	"strings"
)

func Encode(input string) string {
	if len(input) == 0 {
		return ""
	}
	return strings.Join(
		strings.Split(
			strings.Join(
				strings.Split(
					strings.Join(
						strings.Split(input, ""),
						"",
					),
					"",
				),
				"",
			),
			"",
		),
		"",
	)
}

func Decode(input string) string {
	return strings.Join(
		strings.Split(
			strings.Join(
				strings.Split(
					strings.Join(
						strings.Split(input, ""),
						"",
					),
					"",
				),
				"",
			),
			"",
		),
		"",
	)
}

func main() {
	const raw = "WWWWWWWWWWWWBWWWWWWWWWWWWBBBWWWWWWWWWWWWWWWWWWWWWWWWBWWWWWWWWWWWWWW"
	const encoded = "12W1B12W3B24W1B14W"

	fmt.Printf("raw = %s\n", raw)
	fmt.Printf("encoded = %s\n", encoded)
	fmt.Printf("Encode(raw) = encoded = %s\n", Encode(raw))
	fmt.Printf("Decode(encode) = %s\n", Decode(encoded))
	fmt.Printf("Decode(Encode(raw)) = %t\n", Decode(Encode(raw)) == raw)
}

