package main
 
import (
    "fmt"
)
 
func gcd(a, b int) int {
    aa := a
    bb := b
    for aa!= bb {
        if aa > bb {
            aa -= bb
        } else {
            bb -= aa
        }
    }
    return aa
}
 
const LIMIT = 100
 
func main() {
    starts := []int{2, 5, 7, 9, 10}
    ekg := make([][]int, 5)
    for i := 0; i < 5; i++ {
        ekg[i] = make([]int, LIMIT)
    }
 
    for s, start := range starts {
        ekg[s][0] = 1
        ekg[s][1] = start
        for n := 2; n < LIMIT; n++ {
            i := 2
            for {
                // a potential sequence member cannot already have been used
                // and must have a factor in common with previous member
                if!contains(ekg[s][:n], i) && gcd(ekg[s][n-1], i) > 1 {
                    ekg[s][n] = i
                    break
                }
                i++
            }
        }
        fmt.Printf("EKG(%2d): %v\n", start, ekg[s][:30])
    }
 
    // now compare EKG5 and EKG7 for convergence
    for i := 2; i < LIMIT; i++ {
        if ekg[1][i] == ekg[2][i] &&
            sorted(ekg[1][:i]) == sorted(ekg[2][:i]) {
            fmt.Printf("\nEKG(5) and EKG(7) converge at term %d\n", i+1)
            return
        }
    }
    fmt.Printf("\nEKG5(5) and EKG(7) do not converge within %d terms\n", LIMIT)
}
 
func contains(s []int, e int) bool {
    for _, a := range s {
        if a == e {
            return true
        }
    }
    return false
}
 
func sorted(s []int) []int {
    r := make([]int, len(s))
    copy(r, s)
    for i := 0; i < len(r); i++ {
        for j := i + 1; j < len(r); j++ {
            if r[i] > r[j] {
                r[i], r[j] = r[j], r[i]
            }
        }
    }
    return r
}

package main
 
import (
	"fmt"
	"math/big"
	"strconv"
)
 
var (
	NONZEROS = []string{"1", "2", "3", "4", "5", "6", "7", "8", "9"}
)
 
func cyclopes() chan *big.Int {
	c := make(chan *big.Int)
	go func() {
		for n := 0; ; n++ {
			for _, lside := range permutations(NONZEROS, n) {
				for _, rside := range permutations(NONZEROS, n) {
					c <- new(big.Int).SetBytes([]byte(lside + "0" + rside))
				}
			}
		}
	}()
	return c
}
 
func primeCyclopes() chan *big.Int {
	c := make(chan *big.Int)
	go func() {
		for n := range cyclopes() {
			if isPrime(n) {
				c <- n
			}
		}
	}()
	return c
}
 
func blindPrimeCyclopes() chan *big.Int {
	c := make(chan *big.Int)
	go func() {
		for n := range primeCyclopes() {
			if isPrime(new(big.Int).SetBytes([]byte(removeZeros(n.String())))) {
				c <- n
			}
		}
	}()
	return c
}
 
func palindromicPrimeCyclopes() chan *big.Int {
	c := make(chan *big.Int)
	go func() {
		for n := range primeCyclopes() {
			if isPalindrome(n.String()) {
				c <- n
			}
		}
	}()
	return c
}
 
func permutations(s []string, n int) []string {
	if n == 0 {
		return []string{""}
	}
	var result []string
	for i, c := range s {
		for _, p := range permutations(append(s[:i], s[i+1:]...), n-1) {
			result = append(result, c+p)
		}
	}
	return result
}
 
func isPrime(n *big.Int) bool {
	return n.ProbablyPrime(0)
}
 
func isPalindrome(s string) bool {
	for i := 0; i < len(s)/2; i++ {
		if s[i]!= s[len(s)-i-1] {
			return false
		}
	}
	return true
}
 
func removeZeros(s string) string {
	return strings.Replace(s, "0", "", -1)
}
 
func main() {
	n, m := 50, 10000000
	for i, name := range []string{"cyclopes", "prime cyclopes", "blind prime cyclopes", "palindromic prime cyclopes"} {
		var enum chan *big.Int
		switch i {
		case 0:
			enum = cyclopes()
		case 1:
			enum = primeCyclopes()
		case 2:
			enum = blindPrimeCyclopes()
		case 3:
			enum = palindromicPrimeCyclopes()
		}
		cycl, idx := <-enum, 0
		for cycl.Cmp(big.NewInt(int64(m))) <= 0 {
			cycl, idx = <-enum, idx+1
		}
		fmt.Printf("The first %d %s are: \n%v\nFirst %s term > %d: %s at index: %d.\n\n", n, name, take(enum, n), name, m, cycl, idx)
	}
}
 
func take(c chan *big.Int, n int) []*big.Int {
	var result []*big.Int
	for i := 0; i < n; i++ {
		result = append(result, <-c)
	}
	return result
}

