package main
 
import (
    "fmt"
    "math"
)
 
func mod(x, y int64) int64 {
    m := x % y
    if m < 0 {
        if y < 0 {
            return m - y
        }
        return m + y
    }
    return m
}
 
type RNG struct {
    // first generator
    a1 [3]int64
    m1 int64
    x1 [3]int64
 
    // second generator
    a2 [3]int64
    m2 int64
    x2 [3]int64
 
    d int64
}
 
func (rng *RNG) seed(state int64) {
    rng.x1 = [3]int64{state, 0, 0}
    rng.x2 = [3]int64{state, 0, 0}
}
 
func (rng *RNG) nextInt() int64 {
    x1i := mod(rng.a1[0]*rng.x1[0]+rng.a1[1]*rng.x1[1]+rng.a1[2]*rng.x1[2], rng.m1)
    x2i := mod(rng.a2[0]*rng.x2[0]+rng.a2[1]*rng.x2[1]+rng.a2[2]*rng.x2[2], rng.m2)
    z := mod(x1i-x2i, rng.m1)
 
    // keep last three values of the first generator
    rng.x1 = [3]int64{x1i, rng.x1[0], rng.x1[1]}
    // keep last three values of the second generator
    rng.x2 = [3]int64{x2i, rng.x2[0], rng.x2[1]}
 
    return z + 1
}
 
func (rng *RNG) nextFloat() float64 {
    return float64(rng.nextInt()) / float64(rng.d)
}
 
func main() {
    rng := RNG{
        // first generator
        a1: [3]int64{0, 1403580, -810728},
        m1: (1 << 32) - 209,
        x1: [3]int64{0, 0, 0},
 
        // second generator
        a2: [3]int64{527612, 0, -1370589},
        m2: (1 << 32) - 22853,
        x2: [3]int64{0, 0, 0},
 
        d: (1 << 32) - 209 + 1,
    }
 
    rng.seed(1234567)
    fmt.Println(rng.nextInt())
    fmt.Println(rng.nextInt())
    fmt.Println(rng.nextInt())
    fmt.Println(rng.nextInt())
    fmt.Println(rng.nextInt())
    fmt.Println()
 
    counts := [5]int{}
    rng.seed(987654321)
    for i := 0; i < 100_000; i++ {
        v := int(math.Floor(rng.nextFloat() * 5.0))
        counts[v]++
    }
    for iv, v := range counts {
        fmt.Printf("%d: %d\n", iv, v)
    }
}

