package main

import (
	"fmt"
	"math"
	"strconv"
	"strings"
)

var cvs, ctx, scale, p0, ord, clr, jc int
var clrs = []string{"blue", "navy", "green", "darkgreen", "red", "brown", "yellow", "cyan"}

func p5f() {
	cvs = document.getElementById("cvsid")
	ctx = cvs.getContext("2d")
	cvs.onclick = iter
	pInit() //init plot
}

func iter() {
	if ord > 5 {
		resetf(0)
	}
	ctx.clearRect(0, 0, cvs.width, cvs.height)
	p0.forEach(iter5)
	p0.forEach(pIter5)
	ord++
	document.getElementById("p1id").innerHTML = ord
}

func iter5(v, i, a) {
	if typeof(v[0][0]) == "object" {
		a[i].forEach(iter5)
	} else {
		a[i] = meta5(v)
	}
}

func pIter5(v, i, a) {
	if typeof(v[0][0]) == "object" {
		v.forEach(pIter5)
	} else {
		pPoly(v)
	}
}

func pInit() {
	p0 = [make5([.5,.5],.5)]
	pPoly(p0[0])
}

func meta5(h) {
	c := h[0]
	p1 := c
	p2 := h[1]
	z1 := p1[0] - p2[0]
	z2 := p1[1] - p2[1]
	dist := math.Sqrt(z1*z1 + z2*z2) / 2.65
	nP := []
	for k := 1; k < h.length; k++ {
		p1 := h[k]
		p2 := c
		a := math.Atan2(p2[1]-p1[1], p2[0]-p1[0])
		nP[k] = make5(ppad(a, dist, h[k]), dist)
	}
	nP[0] = make5(c, dist)
	return nP
}

func make5(c, r) {
	vs := []
	j := 1
	for i := 1 / 10; i < 2; i += 2 / 5 {
		vs[j] = ppad(i*math.Pi, r, c)
		j++
	}
	vs[0] = c
	return vs
}

func pPoly(s) {
	ctx.beginPath()
	ctx.moveTo(s[1][0]*scale, s[1][1]*-scale+scale)
	for i := 2; i < s.length; i++ {
		ctx.lineTo(s[i][0]*scale, s[i][1]*-scale+scale)
	}
	ctx.fillStyle = clr
	ctx.fill()
}

// a - angle, d - distance, p - point
func ppad(a, d, p) {
	x := p[0]
	y := p[1]
	x2 := d*math.Cos(a) + x
	y2 := d*math.Sin(a) + y
	return [x2, y2]
}

func resetf(rord) {
	ctx.clearRect(0, 0, cvs.width, cvs.height)
	ord = rord
	jc++
	if jc > 7 {
		jc = 0
	}
	clr = clrs[jc]
	document.getElementById("p1id").innerHTML = ord
	p5f()
}

