func bsd_rand(seed int) func() int {
	return func() int {
		seed = (1103515245*seed + 12345) & 0x7fffffff
		return seed
	}
}
 
func msvcrt_rand(seed int) func() int {
	return func() int {
		seed = (214013*seed + 2531011) & 0x7fffffff
		return seed >> 16
	}
}
 
