	"strings"
)

func block_reverse_C++11(first, last string, separator string) {
	sort.Sort(sort.Reverse(sort.StringSlice(first)))
	block_last := first
	for block_last!= last {
		block_first := strings.Index(block_last, separator)
		block_last = strings.Index(block_first, last, separator)
		sort.Sort(sort.Reverse(sort.StringSlice(block_first)))
	}
}

func block_reverse_C++03(first, last string, separator string) {
	sort.Sort(sort.Reverse(sort.StringSlice(first)))
	block_last := first
	for block_last!= last {
		block_first := strings.Index(block_last, separator)
		block_last = strings.Index(block_first, last, separator)
		sort.Sort(sort.Reverse(sort.StringSlice(block_first)))
	}
}

func main() {
	str1 := []string{
		"---------- Ice and Fire ------------",
		"",
		"fire, in end will world the say Some",
		"ice. in say Some",
		"desire of tasted I've what From",
		"fire. favor who those with hold I",
		"",
		"... elided paragraph last...",
		"",
		"Frost Robert -----------------------",
	}

	for _, s := range str1 {
		block_reverse_C++11(s, s, " ")
		fmt.Println(s)
	}

	for _, s := range str1 {
		block_reverse_C++03(s, s, " ")
		fmt.Println(s)
	}
}

