import (
	"fmt"
	"math/rand"
)

type SOfN struct {
	sample []int
	i      int
	n      int
}

func (s *SOfN) process(item int) []int {
	if s.i++; s.i <= s.n {
		s.sample = append(s.sample, item)
	} else if rand.Intn(s.i) < s.n {
		s.sample[rand.Intn(s.n)] = item
	}
	return s.sample
}

func main() {
	bin := make([]int, 10)
	for trial := 0; trial < 100000; trial++ {
		s_of_n := &SOfN{n: 3}
		for i := 0; i < 9; i++ {
			s_of_n.process(i)
		}
		for _, s := range s_of_n.process(9) {
			bin[s]++
		}
	}
	fmt.Println(bin)
}

