	LONGLAG  = 2000
)
 
func main() {
	var i, times, hour, min, sec, min1, min2 int
	var t time.Time
	var currentTime time.Time
	for {
		t = time.Now()
		currentTime = t.Local()
 
		hour = currentTime.Hour()
		min = currentTime.Minute()
		sec = currentTime.Second()
 
		hour = 12
		min = 0
		sec = 0
 
		if (min == 0 || min == 30) && sec == 0 {
			times = ((hour*60 + min) % 240) % 8
		}
		if times == 0 {
			times = 8
		}
 
		if min == 0 {
			min1 = 0
			min2 = 0
		} else {
			min1 = 3
			min2 = 0
		}
 
		if (min == 0 || min == 30) && sec == 0 {
			fmt.Printf("\nIt is now %d:%d%d %s. Sounding the bell %d times.", hour, min1, min2, (hour > 11)? "PM" : "AM", times)
 
			for i = 1; i <= times; i++ {
