package main
 
import (
	"fmt"
	"math"
)
 
func properDivs(n int) []int {
	var divs []int
	for i := 1; i <= int(math.Sqrt(float64(n))); i++ {
		if n%i == 0 {
			divs = append(divs, i)
			if i*i!= n {
				divs = append(divs, n/i)
			}
		}
	}
	return divs
}
 
func pdsum(n int) int {
	var sum int
	for _, v := range properDivs(n) {
		sum += v
	}
	return sum
}
 
func aliquot(n, maxlen, maxterm int) (string, []int) {
	if n == 0 {
		return "terminating", []int{0}
	}
	s, slen, new := []int{n}, 1, n
	for slen <= maxlen && new < maxterm {
		new = pdsum(s[len(s)-1])
		if new == 0 {
			return "terminating", append(s, 0)
		}
		for i, v := range s {
			if v == new {
				if i == 0 {
					if slen == 1 {
						return "perfect", s
					} else if slen == 2 {
						return "amicable", s
					} else {
						return fmt.Sprintf("sociable of length %d", slen), s
					}
				} else if i == len(s)-1 {
					return "aspiring", s
				} else {
					return fmt.Sprintf("cyclic back to %d", new), s
				}
			}
		}
		s = append(s, new)
		slen++
	}
	return "non-terminating", s
}
 
func main() {
	for n := 1; n <= 10; n++ {
		fmt.Println(aliquot(n, 16, 2<<47))
	}
	fmt.Println()
	for _, n := range []int{11, 12, 28, 496, 220, 1184, 12496, 1264460, 790, 909, 562, 1064, 1488, 15355717786080} {
		fmt.Println(aliquot(n, 16, 2<<47))
	}
}

