package main

import (
    "fmt"
)

type Point struct {
    x int
    y int
}

func d2pt(n int, d int) Point {
    x := 0
    y := 0
    t := d
    s := 1
    for s < n {
        rx := 1 & (t / 2)
        ry := 1 & (t ^ rx)
        p := Point{x, y}
        rot(s, &p, rx, ry)
        x = p.x + s * rx
        y = p.y + s * ry
        t /= 4
        s *= 2
    }
    return Point{x, y}
}

func rot(n int, p *Point, rx int, ry int) {
    if ry == 0 {
        if rx == 1 {
            p.x = n - 1 - p.x
            p.y = n - 1 - p.y
        }
        t := p.x
        p.x = p.y
        p.y = t
    }
}

func main() {
    n := 32
    k := 3
    pts := make([][]byte, n * k)
    for i := range pts {
        pts[i] = make([]byte, n * k)
    }
    prev := Point{0, 0}
    pts[0][0] = '.'
    for d := 1; d < n * n; d++ {
        curr := d2pt(n, d)
        cx := curr.x * k
        cy := curr.y * k
        px := prev.x * k
        py := prev.y * k
        pts[cx][cy] = '.'
        if cx == px {
            if py < cy {
                for y := py + 1; y < cy; y++ {
                    pts[cx][y] = '|'
                }
            } else {
                for y := cy + 1; y < py; y++ {
                    pts[cx][y] = '|'
                }
            }
        } else {
            if px < cx {
                for x := px + 1; x < cx; x++ {
                    pts[x][cy] = '_'
                }
            } else {
                for x := cx + 1; x < px; x++ {
                    pts[x][cy] = '_'
                }
            }
        }
        prev = curr
    }
    for i := 0; i < n * k; i++ {
        for j := 0; j < n * k; j++ {
            fmt.Printf("%c", pts[j][i])
        }
        fmt.Println()
    }
}

