package main

import (
	"fmt"
)

type Point struct {
	x float64
	y float64
}

type Shape struct {
	name   string
	bounds []Point
}

func contains(bounds []Point, lat float64, lng float64) bool {
	//https://rosettacode.org/wiki/Ray-casting_algorithm
	count := 0
	for b := 0; b < len(bounds); b++ {
		vertex1 := bounds[b]
		vertex2 := bounds[(b+1)%len(bounds)]
		if west(vertex1, vertex2, lng, lat) {
			count++
		}
	}
	return count%2 == 1
}

func west(A Point, B Point, x float64, y float64) bool {
	if A.y <= B.y {
		if y <= A.y || y > B.y ||
			x >= A.x && x >= B.x {
			return false
		} else if x < A.x && x < B.x {
			return true
		} else {
			return (y-A.y)/(x-A.x) > (B.y-A.y)/(B.x-A.x)
		}
	} else {
		return west(B, A, x, y)
	}
}

var square = Shape{name: "square", bounds: []Point{{x: 0, y: 0}, {x: 20, y: 0}, {x: 20, y: 20}, {x: 0, y: 20}}}
var squareHole = Shape{name: "squareHole", bounds: []Point{{x: 0, y: 0}, {x: 20, y: 0}, {x: 20, y: 20}, {x: 0, y: 20}, {x: 5, y: 5}, {x: 15, y: 5}, {x: 15, y: 15}, {x: 5, y: 15}}}
var strange = Shape{name: "strange", bounds: []Point{{x: 0, y: 0}, {x: 5, y: 5}, {x: 0, y: 20}, {x: 5, y: 15}, {x: 15, y: 15}, {x: 20, y: 20}, {x: 20, y: 0}}}
var hexagon = Shape{name: "hexagon", bounds: []Point{{x: 6, y: 0}, {x: 14, y: 0}, {x: 20, y: 10}, {x: 14, y: 20}, {x: 6, y: 20}, {x: 0, y: 10}}}

var shapes = []Shape{square, squareHole, strange, hexagon}
var testPoints = []Point{{lng: 10, lat: 10}, {lng: 10, lat: 16}, {lng: -20, lat: 10},
	{lng: 0, lat: 10}, {lng: 20, lat: 10}, {lng: 16, lat: 10}, {lng: 20, lat: 20}}

func main() {
	for s := 0; s < len(shapes); s++ {
		shape := shapes[s]
		for tp := 0; tp < len(testPoints); tp++ {
			testPoint := testPoints[tp]
			fmt.Printf("%v\tin %v\t%v\n", testPoint, shape.name, contains(shape.bounds, testPoint.lat, testPoint.lng))
		}
	}
}

package main
 
import (
	"fmt"
	"math"
)
 
var shades = []string{".", ":", "!", "*", "o", "e", "&", "#", "%", "@"}
 
func normalize(v [3]float64) [3]float64 {
	len := math.Sqrt(v[0]*v[0] + v[1]*v[1] + v[2]*v[2])
	return [3]float64{v[0] / len, v[1] / len, v[2] / len}
}
 
func dot(x, y [3]float64) float64 {
	d := x[0]*y[0] + x[1]*y[1] + x[2]*y[2]
	if d < 0 {
		return -d
	}
	return 0
}
 
func drawSphere(r, k, ambient float64, light [3]float64) {
	for i := int(math.Floor(-r)); i <= int(math.Ceil(r)); i++ {
		x := float64(i) + 0.5
		line := ""
 
		for j := int(math.Floor(-2 * r)); j <= int(math.Ceil(2*r)); j++ {
			y := float64(j)/2 + 0.5
			if x*x+y*y <= r*r {
				vec := normalize([3]float64{x, y, math.Sqrt(r*r - x*x - y*y)})
				b := math.Pow(dot(light, vec), k) + ambient
				intensity := int((1 - b) * (float64(len(shades)) - 1))
				if 0 <= intensity && intensity < len(shades) {
					line += shades[intensity]
				} else {
					line += shades[0]
				}
			} else {
				line += " "
			}
		}
		fmt.Println(line)
	}
}
 
func main() {
	light := normalize([3]float64{30, 30, -50})
	drawSphere(20, 4, 0.1, light)
	drawSphere(10, 2, 0.4, light)
}

