	fmt.Print("Enter the value of n:")
	fmt.Scan(&n)
	lcm := (n == m || n == 1)? m : (m == 1? n : 0)
	if lcm == 0 {
		mm := m
		nn := n
		for mm!= nn {
			for mm < nn {
				mm += m
			}
			for nn < mm {
				nn += n
			}
		}
		lcm = mm
	}
	fmt.Println("lcm(", m, ", ", n, ") = ", lcm)
}

