package main
 
import (
    "bufio"
    "fmt"
    "io"
    "os"
)
 
func main() {
    fileContents := readEntireFile("./foo.txt")
    fmt.Println(fileContents)
}
 
func readEntireFile(filename string) string {
    file, err := os.Open(filename)
    if err!= nil {
        panic(err)
    }
    defer file.Close()
    reader := bufio.NewReader(file)
    var contents string
    buffer := make([]byte, 4096)
    for {
        n, err := reader.Read(buffer)
        if err!= nil && err!= io.EOF {
            panic(err)
        }
        if n == 0 {
            break
        }
        contents += string(buffer[:n])
    }
    return contents
}

