package main

import (
	"fmt"
)

type Sequence []int

func (s Sequence) String() string {
	str := "["
	for _, e := range s {
		str += fmt.Sprintf("%d, ", e)
	}
	str += "]"
	return str
}

func nextInCycle(s Sequence, i int) int {
	return s[i%len(s)]
}

func genKolakoski(s Sequence, n int) Sequence {
	seq := make(Sequence, 0, n)
	for i := 0; len(seq) < n; i++ {
		next := nextInCycle(s, i)
		nv := make(Sequence, 0, 2)
		if i >= len(seq) {
			nv = append(nv, next)
		} else {
			nv = append(nv, seq[i])
		}
		nv = append(nv, next)
		seq = append(seq, nv...)
	}
	return seq[:n]
}

func isPossibleKolakoski(s Sequence) bool {
	r := make(Sequence, 0, len(s))
	for i := 0; i < len(s); {
		count := 1
		for j := i + 1; j < len(s); j++ {
			if s[j]!= s[i] {
				break
			}
			count++
		}
		r = append(r, count)
		i += count
	}
	for i := 0; i < len(r); i++ {
		if r[i]!= s[i] {
			return false
		}
	}
	return true
}

func main() {
	seqs := []Sequence{
		{1, 2},
		{2, 1},
		{1, 3, 1, 2},
		{1, 3, 2, 1},
	}
	for _, s := range seqs {
		kol := genKolakoski(s, 30)
		fmt.Printf("Starting with: %v: \nKolakoski sequence: %v\nPossibly kolakoski? %v\n", s, kol, isPossibleKolakoski(kol))
	}
}

