package main

import (
	"fmt"
	"math"
)

func thieleInterpolator(x, y []float64) func(float64) float64 {
	ρ := make([][]float64, len(y))
	for i, yi := range y {
		ρ[i] = make([]float64, len(y)-i)
		for j := range ρ[i] {
			ρ[i][j] = yi
		}
	}
	for i := range ρ {
		ρ[i][1] = (x[i] - x[i+1]) / (ρ[i][0] - ρ[i+1][0])
	}
	for i := 2; i < len(ρ); i++ {
		for j := range ρ {
			ρ[j][i] = (x[j]-x[j+i]) / (ρ[j][i-1]-ρ[j+1][i-1]) + ρ[j+1][i-2]
		}
	}
	ρ0 := ρ[0]
	return func(xin float64) float64 {
		a := 0.0
		for i := len(ρ0) - 1; i > 1; i-- {
			a = (xin - x[i-1]) / (ρ0[i] - ρ0[i-2] + a)
		}
		return y[0] + (xin-x[0])/(ρ0[1]+a)
	}
}

func main() {
	// task 1: build 32 row trig table
	xVal := make([]float64, 32)
	for i := range xVal {
		xVal[i] = float64(i) *.05
	}
	tSin := make([]float64, 32)
	tCos := make([]float64, 32)
	tTan := make([]float64, 32)
	for i, x := range xVal {
		tSin[i] = math.Sin(x)
		tCos[i] = math.Cos(x)
		tTan[i] = math.Tan(x)
	}
	// task 2: define inverses
	iSin := thieleInterpolator(tSin, xVal)
	iCos := thieleInterpolator(tCos, xVal)
	iTan := thieleInterpolator(tTan, xVal)
	// task 3: demonstrate identities
	fmt.Printf("%.14f\n", 6*iSin(.5))
	fmt.Printf("%.14f\n", 3*iCos(.5))
	fmt.Printf("%.14f\n", 4*iTan(1))
}

