package main
 
import (
    "bufio"
    "fmt"
    "io/ioutil"
    "os"
    "strings"
)
 
type ConfigData struct {
    FavouriteFruit   string
    NeedsPeeling     bool
    SeedsRemoved     bool
    NumberOfBananas  int
    NumberOfStrawberries int
}
 
func updateConfigFile(fileName string, cData ConfigData) {
    inp, err := os.Open(fileName)
    if err!= nil {
        fmt.Println(err)
        return
    }
    defer inp.Close()
 
    lines, err := ioutil.ReadAll(inp)
    if err!= nil {
        fmt.Println(err)
        return
    }
 
    tempFileName := "temp_" + fileName
    out, err := os.Create(tempFileName)
    if err!= nil {
        fmt.Println(err)
        return
    }
    defer out.Close()
 
    pw := bufio.NewWriter(out)
    hadFruit := false
    hadPeeling := false
    hadSeeds := false
    hadBananas := false
    hadStrawberries := false
 
    for _, line := range strings.Split(string(lines), "\n") {
        if len(line) == 0 || line[0] == '#' {
            pw.WriteString(line + "\n")
            continue
        }
        ln := strings.TrimLeft(strings.Trim(strings.ToUpper(line), " \t"), ";")
        if len(ln) == 0 {
            continue
        }
        if ln[:14] == "FAVOURITEFRUIT" {
            if hadFruit {
                continue
            }
            hadFruit = true
            pw.WriteString(fmt.Sprintf("FAVOURITEFRUIT %s\n", cData.FavouriteFruit))
        } else if ln[:12] == "NEEDSPEELING" {
            if hadPeeling {
                continue
            }
            hadPeeling = true
            if cData.NeedsPeeling {
                pw.WriteString("NEEDSPEELING\n")
            } else {
                pw.WriteString("; NEEDSPEELING\n")
            }
        } else if ln[:12] == "SEEDSREMOVED" {
            if hadSeeds {
                continue
            }
            hadSeeds = true
            if cData.SeedsRemoved {
                pw.WriteString("SEEDSREMOVED\n")
            } else {
                pw.WriteString("; SEEDSREMOVED\n")
            }
        } else if ln[:15] == "NUMBEROFBANANAS" {
            if hadBananas {
                continue
            }
            hadBananas = true
            pw.WriteString(fmt.Sprintf("NUMBEROFBANANAS %d\n", cData.NumberOfBananas))
        } else if ln[:20] == "NUMBEROFSTRAWBERRIES" {
            if hadStrawberries {
                continue
            }
            hadStrawberries = true
            pw.WriteString(fmt.Sprintf("NUMBEROFSTRAWBERRIES %d\n", cData.NumberOfStrawberries))
        }
    }
 
    if!hadFruit {
        pw.WriteString(fmt.Sprintf("FAVOURITEFRUIT %s\n", cData.FavouriteFruit))
    }
 
    if!hadPeeling {
        if cData.NeedsPeeling {
            pw.WriteString("NEEDSPEELING\n")
        } else {
            pw.WriteString("; NEEDSPEELING\n")
        }
    }
 
    if!hadSeeds {
        if cData.SeedsRemoved {
            pw.WriteString("SEEDSREMOVED\n")
        } else {
            pw.WriteString("; SEEDSREMOVED\n")
        }
    }
 
    if!hadBananas {
        pw.WriteString(fmt.Sprintf("NUMBEROFBANANAS %d\n", cData.NumberOfBananas))
    }
 
    if!hadStrawberries {
        pw.WriteString(fmt.Sprintf("NUMBEROFSTRAWBERRIES %d\n", cData.NumberOfStrawberries))
    }
 
    pw.Flush()
    inp.Close()
    out.Close()
    os.Remove(fileName)
    os.Rename(tempFileName, fileName)
}
 
func main() {
    fileName := "config.txt"
    cData := ConfigData{"banana", false, true, 1024, 62000}
    updateConfigFile(fileName, cData)
}

package main

import (
    "fmt"
    "math"
)

func main() {
    runTest(12, 1)
    runTest(12, 2)
    runTest(123, 45)
    runTest(123, 12345)
    runTest(123, 678910)
}

func runTest(l int, n int) {
    fmt.Printf("p(%d, %d) = %d\n", l, n, p(l, n))
}

func p(l int, n int) int {
    test := 0
    log := math.Log(2) / math.Log(10)
    factor := 1
    loop := l
    for loop > 10 {
        factor *= 10
        loop /= 10
    }
    for n > 0 {
        test++
        val := int(factor * math.Pow(10, float64(test*int(log)%1)))
        if val == l {
            n--
        }
    }
    return test
}

