func tm(d, s, e, i, b, t string, r...string) {
	fmt.Println(d)
	if i < 0 || i >= len(t) {
		return
	}
	var re = strings.NewReplacer(b, " ")
	write(s, i, t)
	var p = make(map[string]struct {
		w, n string
		m    int
	})
	for _, e := range r {
		var s, r, w, m, n string
		fmt.Sscanf(e, "%s.%s: %s, %s, %s", &s, &r, &w, &m, &n)
		p[s+"."+r] = struct {
			w, n string
			m    int
		}{w, n, [3]int{0, 1, -1}["RL"[strings.Index(m, "RL")]]}
	}
	for n := 1; s!= e; n++ {
		var v = p[s+"."+string(t[i])]
		t = t[:i] + v.w + t[i+1:]
		s, i = v.n, i+v.m
		if i == -1 {
			i, t = 0, b+t
		} else if i == len(t) {
			t += b
		}
		write(s, i, t)
	}
	fmt.Println()
}

func write(s string, i int, t string) {
	t = t[:i] + "<u>" + t[i:i+1] + "</u>" + t[i+1:]
	fmt.Printf("%3d: %s [%s]\n", i, s, re.Replace(t))
}

