package main
 
import (
    "fmt"
    "strings"
)
 
type LineComposer struct {
    words  []string
    width  int
    current string
}
 
func NewLineComposer(words []string, width int) *LineComposer {
    return &LineComposer{
        words:  words,
        width:  width,
        current: "",
    }
}
 
func (lc *LineComposer) Next() (string, bool) {
    if len(lc.words) == 0 {
        if lc.current == "" {
            return "", false
        }
        current := lc.current
        lc.current = ""
        return current, true
    }
 
    next := lc.words[0]
    lc.words = lc.words[1:]
 
    if lc.width <= len(lc.current)+len(next) {
        lc.words = append([]string{next}, lc.words...)
        if lc.current == "" {
            return lc.Next()
        }
        return lc.current, true
    }
 
    if lc.current!= "" {
        lc.current += " "
    }
    lc.current += next
    return lc.Next()
}
 
func main() {
    text := `
        In olden times when wishing still helped one, there lived a king whose
        daughters were all beautiful, but the youngest was so beautiful that the
        sun itself, which has seen so much, was astonished whenever it shone in
        her face. Close by the king's castle lay a great dark forest, and under
        an old lime tree in the forest was a well, and when the day was very
        warm, the king's child went out into the forest and sat down by the side
        of the cool fountain, and when she was bored she took a golden ball, and
        threw it up on high and caught it, and this ball was her favorite
        plaything.`
 
    lc := NewLineComposer(strings.Fields(text), 80)
    for {
        line, ok := lc.Next()
        if!ok {
            break
        }
        fmt.Println(line)
    }
}

func gnomeSort(a []int) {
	i := 1
	j := 2
	for i < len(a) {
		if a[i-1] > a[i] {
			a[i-1], a[i] = a[i], a[i-1]
			if i--; i == 0 {
				continue
			}
		}
		i = j
		j++
	}
}

