package main
 
import "fmt"
 
const (
    MAX_N = 300
    BRANCH = 4
)
 
var (
    ra = make([]int, MAX_N)
    unrooted = make([]int, MAX_N)
)
 
func tree(br, n, l, sum, cnt int) {
    for b := br + 1; b <= BRANCH; b++ {
        sum += n
        if sum >= MAX_N {
            return
        }
 
        // prevent unneeded long math
        if l*2 >= sum && b >= BRANCH {
            return
        }
 
        if b == br+1 {
            c := ra[n] * cnt
        } else {
            c := c * (ra[n] + (b - br - 1)) / (b - br)
        }
 
        if l*2 < sum {
            unrooted[sum] += c
        }
 
        if b < BRANCH {
            ra[sum] += c
            for m := 1; m < n; m++ {
                tree(b, m, l, sum, c)
            }
        }
    }
}
 
func bicenter(s int) {
    if s&1 == 0 {
        aux := ra[s/2]
        unrooted[s] += aux * (aux + 1) / 2
    }
}
 
func main() {
    ra[0], ra[1], unrooted[0], unrooted[1] = 1, 1, 1, 1
 
    for n := 1; n < MAX_N; n++ {
        tree(0, n, n)
        bicenter(n)
        fmt.Printf("%d: %d\n", n, unrooted[n])
    }
}

package main

import "fmt"

func equilibrium(a []int) []int {
	N := len(a)
	l := make([]int, N)
	r := make([]int, N)
	e := make([]int, 0)
	l[0] = a[0]
	r[N-1] = a[N-1]
	for i := 1; i < N; i++ {
		l[i] = l[i-1] + a[i]
		r[N-i-1] = r[N-i] + a[N-i-1]
	}
	for i := 0; i < N; i++ {
		if l[i] == r[i] {
			e = append(e, i)
		}
	}
	return e
}

func main() {
	fmt.Println(equilibrium([]int{-7, 1, 5, 2, -4, 3, 0}))
	fmt.Println(equilibrium([]int{2, 4, 6}))
	fmt.Println(equilibrium([]int{2, 9, 2}))
	fmt.Println(equilibrium([]int{1, -1, 1, -1, 1, -1, 1}))
	fmt.Println(equilibrium([]int{1}))
	fmt.Println(equilibrium([]int{}))
}

