)
 
const LIMIT = 42
 
func is_prime(n int64) bool {
    if n%2 == 0 {
        return n == 2
    }
    if n%3 == 0 {
        return n == 3
    }
    d := int64(5)
    for d*d <= n {
        if n%d == 0 {
            return false
        }
        d += 2
        if n%d == 0 {
            return false
        }
        d += 4
    }
    return true
}
 
func main() {
    var i int64
    var n int
    for i = LIMIT; n < LIMIT; i++ {
        if is_prime(i) {
            n++
            fmt.Printf("n = %-2d  %19d\n", n, i)
            i += i - 1
        }
    }
}

package main

import (
	"fmt"
	"math/rand"
	"time"
)

func main() {
	rand.Seed(time.Now().UnixNano())
	a := []int{1, 2, 3}
	p := make([][]int, 0)
	permute(a, 0, &p)
	fmt.Println(p)
}

func permute(a []int, i int, p *[][]int) {
	if i == len(a) {
		*p = append(*p, append([]int{}, a...))
	} else {
		for j := i; j < len(a); j++ {
			a[i], a[j] = a[j], a[i]
			permute(a, i+1, p)
			a[i], a[j] = a[j], a[i]
		}
	}
}

