package main
 
import (
	"fmt"
	"syscall"
	"unsafe"
)
 
const (
	PROT_EXEC = 0x4
	PROT_WRITE = 0x2
	MAP_PRIVATE = 0x2
	MAP_ANONYMOUS = 0x20
)
 
type f_int func() int
 
var (
	TAG = 0xdeadbeef
)
 
func _tmpl() int {
	var x int = TAG
	return x * x
}
 
func dupf(v int) f_int {
	len := unsafe.Sizeof(_tmpl)
	ret, _, _ := syscall.Syscall6(syscall.SYS_MMAP, 0, len, PROT_EXEC|PROT_WRITE, MAP_PRIVATE|MAP_ANONYMOUS, 0, 0)
	if ret == 0 {
		panic("mmap failed")
	}
	p := (*[1 << 30]byte)(unsafe.Pointer(ret))
	copy(p[:], (*[1 << 30]byte)(unsafe.Pointer(&_tmpl))[:])
	for i := 0; i < len-unsafe.Sizeof(TAG); i++ {
		if *(*int)(unsafe.Pointer(&p[i])) == TAG {
			*(*int)(unsafe.Pointer(&p[i])) = v
		}
	}
	return *(*f_int)(unsafe.Pointer(&ret))
}
 
func main() {
	funcs := make([]f_int, 10)
	for i := 0; i < 10; i++ {
		funcs[i] = dupf(i)
	}
 
	for i := 0; i < 9; i++ {
