package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

func deleteLines(filename string, start int, skip int) {
	file, err := os.Open(filename)
	if err!= nil {
		fmt.Println("Error! Could not find file ", filename)
		return
	}
	defer file.Close()
	scanner := bufio.NewScanner(file)
	var filelines []string
	for scanner.Scan() {
		filelines = append(filelines, scanner.Text())
	}
	if start > len(filelines) {
		fmt.Println("Error! Starting to delete lines past the end of the file!")
		return
	}
	if (start + skip) > len(filelines) {
		fmt.Println("Error! Trying to delete lines past the end of the file!")
		return
	}
	deletebegin := start - 1
	deleteend := deletebegin + skip
	filelines = append(filelines[:deletebegin], filelines[deleteend:]...)
	file, err = os.Create(filename)
	if err!= nil {
		fmt.Println("Error! Could not find file ", filename)
		return
	}
	defer file.Close()
	for _, line := range filelines {
		file.WriteString(line + "\n")
	}
}

func main() {
	if len(os.Args)!= 4 {
		fmt.Println("Error! Invoke with <deletelines filename startline skipnumber>!")
		return
	}
	filename := os.Args[1]
	start, _ := strconv.Atoi(os.Args[2])
	skip, _ := strconv.Atoi(os.Args[3])
	deleteLines(filename, start, skip)
}

