import "fmt"
 
func Y(f func(func()) func()) func() {
    g := f(func() {
        g := f(g)
        g()
    })
    return g
}
 
func fac() func(int) int {
    return func(n int) int {
        return n > 1? n*fac()(n-1) : 1
    }
}
 
func fib() func(int) int {
    return func(n int) int {
        return n > 1? fib()(n-1)+fib()(n-2) : n
    }
}
 
func main() {
    fmt.Println(Y(fac())(5))
    fmt.Println(Y(fib())(10))
}

