func randomNormal(mean, stdDev, min, max float64, maxTries int, histogram, histogram2 []float64) float64 {
	var v float64
	tries := 0
	for {
		v = randomNormal(mean, stdDev)
		tries++
		if v >= min && v <= max && tries < maxTries {
			break
		}
	}
	histogram[tries-1]++
	histogram2[tries-1] += v
	return v
}

package main
 
import (
	"fmt"
)
 
type L3 struct {
}
 
func (l3 *L3) Not(a bool) bool {
	if a == true {
		return false
	}
	if a == false {
		return true
	}
	return false
}
 
func (l3 *L3) And(a, b bool) bool {
	if a == true && b == true {
		return true
	}
	if a == true && b == false {
		return false
	}
	if a == false && b == true {
		return false
	}
	if a == false && b == false {
		return false
	}
	return false
}
 
func (l3 *L3) Or(a, b bool) bool {
	if a == true && b == true {
		return true
	}
	if a == true && b == false {
		return true
	}
	if a == false && b == true {
		return true
	}
	if a == false && b == false {
		return false
	}
	return false
}
 
func (l3 *L3) IfThen(a, b bool) bool {
	return l3.Or(l3.Not(a), b)
}
 
func (l3 *L3) Iff(a, b bool) bool {
	return l3.And(l3.IfThen(a, b), l3.IfThen(b, a))
}
 
func main() {
	l3 := new(L3)
	fmt.Println(l3.Not(true))
	fmt.Println(l3.Not(false))
	fmt.Println(l3.And(true, true))
	fmt.Println(l3.And(true, false))
	fmt.Println(l3.And(false, true))
	fmt.Println(l3.And(false, false))
	fmt.Println(l3.Or(true, true))
	fmt.Println(l3.Or(true, false))
	fmt.Println(l3.Or(false, true))
	fmt.Println(l3.Or(false, false))
	fmt.Println(l3.IfThen(true, true))
	fmt.Println(l3.IfThen(true, false))
	fmt.Println(l3.IfThen(false, true))
	fmt.Println(l3.IfThen(false, false))
	fmt.Println(l3.Iff(true, true))
	fmt.Println(l3.Iff(true, false))
	fmt.Println(l3.Iff(false, true))
	fmt.Println(l3.Iff(false, false))
}

package main
 
import (
    "fmt"
)
 
const SIZE = 8
const MOVES = [8][2]int{
    {2, 1},
    {1, 2},
    {-1, 2},
    {-2, 1},
    {-2, -1},
    {-1, -2},
    {1, -2},
    {2, -1},
}
 
type Point struct {
    x, y int
}
 
func (p Point) mov(dir [2]int) Point {
    return Point{p.x + dir[0], p.y + dir[1]}
}
 
type Board struct {
    field [SIZE][SIZE]int
}
 
func (b *Board) available(p Point) bool {
    return 0 <= p.x && p.x < SIZE && 0 <= p.y && p.y < SIZE && b.field[p.x][p.y] == 0
}
 
func (b *Board) countDegree(p Point) int {
    var count int
    for _, dir := range MOVES {
        next := p.mov(dir)
        if b.available(next) {
            count++
        }
    }
    return count
}
 
func (b *Board) String() string {
    var s string
    for _, row := range b.field {
        for _, x := range row {
            s += fmt.Sprintf("%3d ", x)
        }
        s += "\n"
    }
    return s
}
 
func knightsTour(x, y int) *Board {
    var board Board
    var p = Point{x, y}
    var step int = 1
    board.field[p.x][p.y] = step
    step++
 
    for step <= SIZE*SIZE {
        // choose next square by Warnsdorf's rule
        var candidates [][2]int
        for _, dir := range MOVES {
            adj := p.mov(dir)
            if board.available(adj) {
                degree := board.countDegree(adj)
                candidates = append(candidates, [2]int{degree, adj.x*SIZE + adj.y})
            }
        }
        if len(candidates) == 0 {
            return nil
        }
        // move to next square
        var min = candidates[0]
        for _, c := range candidates {
            if c[0] < min[0] {
                min = c
            }
        }
        p.x = min[1] / SIZE
        p.y = min[1] % SIZE
        board.field[p.x][p.y] = step
        step++
    }
    return &board
}
 
func main() {
    x, y := 3, 1
    fmt.Printf("Board size: %d\n", SIZE)
    fmt.Printf("Starting position: (%d, %d)\n", x, y)
    if b := knightsTour(x, y); b!= nil {
        fmt.Println(b)
    } else {
        fmt.Println("Fail!")
    }
}

