package main
 
import (
	"fmt"
	"math"
	"math/cmplx"
)
 
var PI float64
 
func fft(buf []complex128) {
	out := make([]complex128, len(buf))
	for i := 0; i < len(buf); i++ {
		out[i] = buf[i]
	}
 
	_fft(buf, out, len(buf), 1)
}
 
func _fft(buf, out []complex128, n, step int) {
	if step < n {
		_fft(out, buf, n, step*2)
		_fft(out[step:], buf[step:], n, step*2)
 
		for i := 0; i < n; i += 2 * step {
			t := cmplx.Exp(-1i * PI * float64(i) / float64(n)) * out[i+step]
			buf[i/2] = out[i] + t
			buf[(i+n)/2] = out[i] - t
		}
	}
}
 
func show(s string, buf []complex128) {
	fmt.Printf("%s", s)
	for i := 0; i < 8; i++ {
		if imag(buf[i]) == 0 {
			fmt.Printf("%g ", real(buf[i]))
		} else {
			fmt.Printf("(%g, %g) ", real(buf[i]), imag(buf[i]))
		}
	}
}
 
func main() {
	PI = math.Atan2(1, 1) * 4
	buf := []complex128{1, 1, 1, 1, 0, 0, 0, 0}
 
	show("Data: ", buf)
	fft(buf)
	show("\nFFT : ", buf)
}

