import (
    "fmt"
    "math"
)
 
func isPrime(n uint32) bool {
    if n < 2 {
        return false
    }
    if n%2 == 0 {
        return n == 2
    }
    if n%3 == 0 {
        return n == 3
    }
    if n%5 == 0 {
        return n == 5
    }
    p := uint32(7)
    const wheel = [8]uint32{4, 2, 4, 2, 4, 6, 2, 6}
    for {
        for _, w := range wheel {
            if p*p > n {
                return true
            }
            if n%p == 0 {
                return false
            }
            p += w
        }
    }
}
 
func nextPrimeDigitNumber(n uint32) uint32 {
    if n == 0 {
        return 2
    }
    switch n % 10 {
    case 2:
        return n + 1
    case 3, 5:
        return n + 2
    default:
        return 2 + nextPrimeDigitNumber(n/10)*10
    }
}
 
func smarandachePrimeDigitalSequence() func() uint32 {
    n := uint32(0)
    return func() uint32 {
        for {
            n = nextPrimeDigitNumber(n)
            if isPrime(n) {
                break
            }
        }
        return n
    }
}
 
func main() {
    limit := uint32(1000000000)
    seq := smarandachePrimeDigitalSequence()
    fmt.Println("First 25 SPDS primes:")
    for i := 0; i < 25; i++ {
        fmt.Printf("%d ", seq())
    }
    fmt.Println()
    if p := seq(); p < limit {
        fmt.Printf("100th SPDS prime: %d\n", p)
    }
    if p := seq(); p < limit {
        fmt.Printf("1000th SPDS prime: %d\n", p)
    }
    if p := seq(); p < limit {
        fmt.Printf("10,000th SPDS prime: %d\n", p)
    }
    for p := seq(); p < limit; p = seq() {
    }
    fmt.Printf("Largest SPDS prime less than %d: %d\n", limit, p)
}

