func Ordinalize(i int) string {
    i = int(math.Abs(float64(i)))

    if i%100 == 11 || i%100 == 12 || i%100 == 13 {
        return fmt.Sprintf("%dth", i)
    }

    switch i%10 {
    case 1:
        return fmt.Sprintf("%dst", i)
    case 2:
        return fmt.Sprintf("%dnd", i)
    case 3:
        return fmt.Sprintf("%drd", i)
    default:
        return fmt.Sprintf("%dth", i)
    }
}

func main() {
    for i := 0; i < 26; i++ {
        fmt.Printf("%s ", Ordinalize(i))
    }
    fmt.Println()

    for i := 250; i < 266; i++ {
        fmt.Printf("%s ", Ordinalize(i))
    }
    fmt.Println()

    for i := 1000; i < 1026; i++ {
        fmt.Printf("%s ", Ordinalize(i))
    }
    fmt.Println()
}

package main
 
import (
	"fmt"
	"math"
	"strconv"
	"strings"
)
 
type CantorSet struct {
	cells [][]bool
}
 
func numberToVec(n int) []int {
	// for the conversion we need the digits in reverse order
	// i.e the least significant digit in the first element of the vector
	s := strconv.Itoa(n)
	digits := make([]int, len(s))
	for i, c := range s {
		digits[len(s)-i-1], _ = strconv.Atoi(string(c))
	}
	return digits
}
 
func (cs *CantorSet) New(lines int) {
	// Convert from base 10- to base 3
	base := NewConvert(10, 3)
	cs.cells = make([][]bool, lines)
 
lineLoop:
	for line := 0; line < lines; line++ {
		// calculate how many repeating sequence will be in the given line
		segmentSize := int(math.Pow(3, float64(lines-line-1)))
		segment := make([]bool, int(math.Pow(3, float64(line))))
		for n := 0; n < len(segment); n++ {
			output := base.Convert(numberToVec(n))
			// return false in case the base 3 number contains at least one "1"
			// otherwise return true
			segment[n] =!strings.Contains(strings.Trim(fmt.Sprint(output), "[]"), "1")
		}
 
		// copy the segment "segment_size" time
		accum := make([]bool, len(segment)*segmentSize)
		for i, c := range segment {
			for j := 0; j < segmentSize; j++ {
				accum[i*segmentSize+j] = c
			}
		}
		cs.cells[line] = accum
	}
}
 
func (cs *CantorSet) String() string {
	var s string
	for _, line := range cs.cells {
		for _, c := range line {
			if c {
				s += "█"
			} else {
				s += " "
			}
		}
		s += "\n"
	}
	return s
}
 
func main() {
	var cs CantorSet
	cs.New(5)
	fmt.Println("Cantor set:")
	fmt.Println(cs)
}

