package main

import (
	"fmt"
	"math"
)

// Proper divisors
func properDivisors(n int) []int {
	if n < 2 {
		return []int{}
	} else {
		rRoot := math.Sqrt(float64(n))
		intRoot := int(math.Floor(rRoot))

		lows := range1(1, intRoot).filter(func(x int) bool {
			return (n % x) == 0
		})

		return lows.concat(lows.slice(1).map(func(x int) int {
			return n / x
		}).reverse().slice((rRoot == float64(intRoot))|0))
	}
}

// [m..n]
func range1(m, n int) []int {
	a := make([]int, n-m+1)
	i := n + 1
	for i > 0 {
		i--
		a[i-1] = i
	}
	return a
}

func (a []int) filter(f func(int) bool) []int {
	b := make([]int, 0, len(a))
	for _, v := range a {
		if f(v) {
			b = append(b, v)
		}
	}
	return b
}

func (a []int) concat(b []int) []int {
	return append(a, b...)
}

func (a []int) slice(n int) []int {
	return a[n:]
}

func (a []int) reverse() []int {
	for i, j := 0, len(a)-1; i < j; i, j = i+1, j-1 {
		a[i], a[j] = a[j], a[i]
	}
	return a
}

func (a []int) map1(f func(int) int) []int {
	b := make([]int, len(a))
	for i, v := range a {
		b[i] = f(v)
	}
	return b
}

type wikiTable struct {
	lstRows      [][]interface{}
	blnHeaderRow bool
	strStyle     string
}

func (t *wikiTable) String() string {
	return fmt.Sprintf("{%s%s%s}",
		"| class=\"wikitable\" ",
		(t.strStyle!= ""? "style=\""+t.strStyle+"\"" : ""),
		t.lstRows.map(func(lstRow []interface{}, iRow int) string {
			strDelim := ((t.blnHeaderRow &&!iRow)? '!' : '|')

			return "\n|-\n" + strDelim + " " + lstRow.map(func(v interface{}) string {
				return (typeof(v) == "undefined"? " " : v)
			}).join(" " + strDelim + strDelim + " ")
		}).join(""))
}

func main() {
	tblOneToTen := [][]interface{}{
		[]interface{}{"Number", "Proper Divisors", "Count"},
	}.concat(range1(1, 10).map(func(x int) []interface{} {
		ds := properDivisors(x)

		return []interface{}{x, ds.join(", "), len(ds)}
	}))

	dctMostBelow20k := range1(1, 20000).reduce(func(a map[string]interface{}, x int) map[string]interface{} {
		lng := len(properDivisors(x))

		return (lng > a["divisorCount"].(int)? map[string]interface{}{
			"n":           x,
			"divisorCount": lng,
		} : a)
	}, map[string]interface{}{
		"n":           0,
		"divisorCount": 0,
	})

	// [[a]] -> bool -> s -> s
	fmt.Println(wikiTable{
		lstRows:      tblOneToTen,
		blnHeaderRow: true,
	})
	fmt.Println("\nMost proper divisors below 20,000:\n\n  ", dctMostBelow20k)
}

