package main

import (
	"fmt"
)

func main() {
	coconuts := 11
	for ns := 2; ns <= 9; ns++ {
		hidden := make([]int, ns)
		coconuts = (coconuts/ns)*ns + 1
		for {
			nc := coconuts
			for s := 1; s <= ns; s++ {
				if nc%ns == 1 {
					hidden[s-1] = nc / ns
					nc -= hidden[s-1] + 1
					if s == ns && nc%ns == 0 {
						fmt.Printf("%d sailors require a minimum of %d coconuts\n", ns, coconuts)
						for t := 1; t <= ns; t++ {
							fmt.Printf("\tSailor %d hides %d\n", t, hidden[t-1])
						}
						fmt.Printf("\tThe monkey gets %d\n", ns)
						fmt.Printf("\tFinally, each sailor takes %d\n\n", nc/ns)
						break
					}
				} else {
					break
				}
			}
			coconuts += ns
		}
	}
}

