package main
 
import "fmt"
 
func isPrime(n uint32) bool {
    if n < 2 {
        return false
    }
    if n%2 == 0 {
        return n == 2
    }
    if n%3 == 0 {
        return n == 3
    }
    p := uint32(5)
    for p*p <= n {
        if n%p == 0 {
            return false
        }
        p += 2
        if n%p == 0 {
            return false
        }
        p += 4
    }
    return true
}
 
func isLeftTruncatable(p uint32) bool {
    n := uint32(10)
    q := p
    for p > n {
        if!isPrime(p%n) || q == p%n {
            return false
        }
        q = p % n
        n *= 10
    }
    return true
}
 
func isRightTruncatable(p uint32) bool {
    q := p / 10
    for q > 0 {
        if!isPrime(q) {
            return false
        }
        q /= 10
    }
    return true
}
 
func main() {
    limit := uint32(1000000)
    largestLeft := uint32(0)
    largestRight := uint32(0)
    p := limit
    for p >= 2 {
        if isPrime(p) && isLeftTruncatable(p) {
            largestLeft = p
            break
        }
        p -= 1
    }
    fmt.Printf("Largest left truncatable prime is %d\n", largestLeft)
    p = limit
    for p >= 2 {
        if isPrime(p) && isRightTruncatable(p) {
            largestRight = p
            break
        }
        p -= 1
    }
    fmt.Printf("Largest right truncatable prime is %d\n", largestRight)
}

