package main

import (
	"fmt"
)

type xint uint64

func is_palin2(n xint) bool {
	var x xint
	if (n & 1) == 0 {
		return n == 0
	}
	for x < n {
		x = x<<1 | (n & 1)
		n >>= 1
	}
	return n == x || n == x>>1
}

func reverse3(n xint) xint {
	var x xint
	for n > 0 {
		x = x*3 + (n % 3)
		n /= 3
	}
	return x
}

func print(n xint, base xint) {
	fmt.Printf(" ")
	for n > 0 {
		fmt.Printf("%d", n%base)
		n /= base
	}
	fmt.Printf("(%d)", base)
}

func show(n xint) {
	fmt.Printf("%d", n)
	print(n, 2)
	print(n, 3)
	fmt.Printf("\n")
}

func min(a xint, b xint) xint {
	if a < b {
		return a
	}
	return b
}

func max(a xint, b xint) xint {
	if a > b {
		return a
	}
	return b
}

func main() {
	var lo, hi, lo2, hi2, lo3, hi3, pow2, pow3, i, n xint
	var cnt int

	show(0)
	cnt = 1

	lo = 0
	hi = pow2 = pow3 = 1

	for {
		for i = lo; i < hi; i++ {
			n = (i*3 + 1) * pow3 + reverse3(i)
			if!is_palin2(n) {
				continue
			}
			show(n)
			if cnt++; cnt >= 7 {
				return
			}
		}

		if i == pow3 {
			pow3 *= 3
		} else {
			pow2 *= 4
		}

		for {
			for pow2 <= pow3 {
				pow2 *= 4
			}

			lo2 = (pow2 / pow3 - 1) / 3
			hi2 = (pow2*2/pow3 - 1) / 3 + 1
			lo3 = pow3 / 3
			hi3 = pow3

			if lo2 >= hi3 {
				pow3 *= 3
			} else if lo3 >= hi2 {
				pow2 *= 4
			} else {
				lo = max(lo2, lo3)
				hi = min(hi2, hi3)
				break
			}
		}
	}
}

package main
 
import (
	"fmt"
	"os"
	"path/filepath"
	"regexp"
)
 
const (
	WALK_OK = iota
	WALK_BADPATTERN
	WALK_NAMETOOLONG
	WALK_BADIO
)
 
const (
	WS_NONE = 1 << iota
	WS_RECURSIVE
	WS_DEFAULT = WS_RECURSIVE
	WS_FOLLOWLINK
	WS_DOTFILES
	WS_MATCHDIRS
)
 
func walkRecur(dname string, reg *regexp.Regexp, spec int) int {
	var res int = WALK_OK
	var len int = len(dname)
	if len >= filepath.MaxLen {
		return WALK_NAMETOOLONG
	}
 
	fn := dname + "/"
	files, err := filepath.Glob(fn + "*")
	if err!= nil {
		fmt.Fprintf(os.Stderr, "Can't open %s\n", dname)
		return WALK_BADIO
	}
 
	for _, file := range files {
		if!(spec&WS_DOTFILES) && file[0] == '.' {
			continue
		}
		if file == "." || file == ".." {
			continue
		}
 
		if stat, err := os.Stat(file); err == nil {
			if stat.IsDir() {
				if spec&WS_RECURSIVE!= 0 {
					walkRecur(file, reg, spec)
				}
				if spec&WS_MATCHDIRS == 0 {
					continue
				}
			}
			if reg.MatchString(file) {
				fmt.Println(file)
			}
		} else {
			fmt.Fprintf(os.Stderr, "Can't stat %s\n", file)
			res = WALK_BADIO
		}
	}
	return res
}
 
func walkDir(dname string, pattern string, spec int) int {
	reg, err := regexp.Compile(pattern)
	if err!= nil {
		return WALK_BADPATTERN
	}
	res := walkRecur(dname, reg, spec)
	return res
}
 
func main() {
	r := walkDir(".", ".\\.c$", WS_DEFAULT|WS_MATCHDIRS)
	switch r {
	case WALK_OK:
		break
	case WALK_BADIO:
		fmt.Fprintf(os.Stderr, "IO error\n")
	case WALK_BADPATTERN:
		fmt.Fprintf(os.Stderr, "Bad pattern\n")
	case WALK_NAMETOOLONG:
		fmt.Fprintf(os.Stderr, "Filename too long\n")
	default:
		fmt.Fprintf(os.Stderr, "Unknown error?\n")
	}
}

package main

import (
    "fmt"
)

func unique(s []string) []string {
    keys := make(map[string]bool)
    list := []string{}
    for _, entry := range s {
        if _, value := keys[entry];!value {
            keys[entry] = true
            list = append(list, entry)
        }
    }
    return list
}

func relative_complement(A, B []string) []string {
    return filter(A, func(elem string) bool {
        return!contains(B, elem)
    })
}

func symmetric_difference(A, B []string) []string {
    return append(relative_complement(A, B), relative_complement(B, A)...)
}

func filter(vs []string, f func(string) bool) []string {
    vsf := make([]string, 0)
    for _, v := range vs {
        if f(v) {
            vsf = append(vsf, v)
        }
    }
    return vsf
}

func contains(vs []string, t string) bool {
    for _, v := range vs {
        if v == t {
            return true
        }
    }
    return false
}

func main() {
    a := []string{"John", "Serena", "Bob", "Mary", "Serena"}
    b := []string{"Jim", "Mary", "John", "Jim", "Bob"}
    fmt.Println(unique(a))
    fmt.Println(unique(b))
    fmt.Println(symmetric_difference(a, b))
}

