This task has been clarified. Its programming examples are in need of review to ensure that they still fit the requirements of the task.
This task is inverse to the task Call foreign language function. Consider the following C program:

#include <stdio.h>
 
extern int Query (char * Data, size_t * Length);
 
int main (int argc, char * argv [])
{
   char     Buffer [1024];
   size_t   Size = sizeof (Buffer);
 
   if (0 == Query (Buffer, &Size))
   {
      printf ("failed to call Query\n");
   }
   else
   {
      char * Ptr = Buffer;
      while (Size-- > 0) putchar (*Ptr++);
      putchar ('\n');
   }
}
Implement the missing Query function in your language, and let this C program call it. The function should place the string Here am I into the buffer which is passed to it as the parameter Data. The buffer size in bytes is passed as the parameter Length. When there is no room in the buffer, Query shall return 0. Otherwise it overwrites the beginning of Buffer, sets the number of overwritten bytes into Length and returns 1.

code:
package main
 
/*
#include <string>
using std::string;
 
extern "C" int
Query (char *Data, size_t *Length)
{
   const string Message = "Here am I";
 
   // Check that Message fits in Data.
   if (*Length < Message.length())
      return false;  // C++ converts bool to int.
 
   *Length = Message.length();
   Message.copy(Data, *Length);
   return true;
}
*/
import "C"
 
import (
   "fmt"
   "unsafe"
)
 
func main() {
   var buf [100]byte
   var length C.size_t = C.size_t(len(buf))
   if C.Query((*C.char)(unsafe.Pointer(&buf[0])), &length)!= 0 {
      fmt.Printf("Query returned %d bytes: %s\n", length, buf[:length])
   }
}

package main

import (
	"fmt"
	"strings"
)

type Stack struct {
	dataStore []string
	top       int
}

func (s *Stack) push(element string) {
	s.dataStore = append(s.dataStore, element)
	s.top++
}

func (s *Stack) pop() string {
	s.top--
	return s.dataStore[s.top]
}

func (s *Stack) peek() string {
	return s.dataStore[s.top-1]
}

func (s *Stack) length() int {
	return s.top
}

func main() {
	infix := "3 + 4 * 2 / ( 1 - 5 ) ^ 2 ^ 3"
	infix = strings.Replace(infix, " ", "", -1) // remove spaces, so infix[i]!=" "

	s := &Stack{}
	ops := "-+/*^"
	precedence := map[string]int{"^": 4, "*": 3, "/": 3, "+": 2, "-": 2}
	associativity := map[string]string{"^": "Right", "*": "Left", "/": "Left", "+": "Left", "-": "Left"}
	token := ""
	postfix := ""
	o1, o2 := "", ""

	for i := 0; i < len(infix); i++ {
		token = string(infix[i])
		if token >= "0" && token <= "9" { // if token is operand (here limited to 0 <= x <= 9)
			postfix += token + " "
		} else if strings.Index(ops, token)!= -1 { // if token is an operator
			o1 = token
			o2 = s.peek()
			for strings.Index(ops, o2)!= -1 && ( // while operator token, o2, on top of the stack
				// and o1 is left-associative and its precedence is less than or equal to that of o2
				(associativity[o1] == "Left" && precedence[o1] <= precedence[o2]) ||
					// the algorithm on wikipedia says: or o1 precedence < o2 precedence, but I think it should be
					// or o1 is right-associative and its precedence is less than that of o2
					(associativity[o1] == "Right" && precedence[o1] < precedence[o2])) {
				postfix += o2 + " " // add o2 to output queue
				s.pop()             // pop o2 of the stack
				o2 = s.peek()       // next round
			}
			s.push(o1) // push o1 onto the stack
		} else if token == "(" { // if token is left parenthesis
			s.push(token) // then push it onto the stack
		} else if token == ")" { // if token is right parenthesis
			for s.peek()!= "(" { // until token at top is (
				postfix += s.pop() + " "
			}
			s.pop() // pop (, but not onto the output queue
		}
	}
	postfix += strings.Join(s.dataStore, " ")
	fmt.Println(postfix)
}

