)

func main() {
	fmt.Print("Player 1 - Enter your name : ")
	name1 := readLine()
	if name1 == "" {
		name1 = "PLAYER 1"
	}
	fmt.Print("Player 2 - Enter your name : ")
	name2 := readLine()
	if name2 == "" {
		name2 = "PLAYER 2"
	}
	names := []string{name1, name2}
	totals := []int{0, 0}
	player := 0
	for {
		fmt.Printf("\n%s\n", names[player])
		fmt.Printf("  Your total score is currently %d\n", totals[player])
		score := 0
		for {
			fmt.Print("  Roll or Hold r/h : ")
			rh := readLine()
			if rh == "h" {
				totals[player] += score
				fmt.Printf("  Your total score is now %d\n", totals[player])
				if totals[player] >= 100 {
					fmt.Printf("  So, %s, YOU'VE WON!\n", names[player])
					return
				}
				player = 1 - player
				break
			}
			if rh!= "r" {
				fmt.Println("    Must be 'r'or 'h', try again")
				continue
			}
			dice := 1 + rand.Intn(6)
			fmt.Printf("    You have thrown a %d\n", dice)
			if dice == 1 {
				fmt.Println("    Sorry, your score for this round is now 0")
				fmt.Printf("  Your total score remains at %d\n", totals[player])
				player = 1 - player
				break
			}
			score += dice
			fmt.Printf("    Your score for the round is now %d\n", score)
		}
	}
}

