package main

import (
	"fmt"
	"math/rand"
	"strings"
	"time"
)

var randSource = rand.NewSource(time.Now().UnixNano())
var randGen = rand.New(randSource)

func main() {
	fmt.Println(createFen())
}

func createFen() string {
	grid := make([][]rune, 8)
	for i := range grid {
		grid[i] = make([]rune, 8)
	}

	placeKings(grid)
	placePieces(grid, "PPPPPPPP", true)
	placePieces(grid, "pppppppp", true)
	placePieces(grid, "RNBQBNR", false)
	placePieces(grid, "rnbqbnr", false)

	return toFen(grid)
}

func placeKings(grid [][]rune) {
	r1, c1, r2, c2 := 0, 0, 0, 0
	for {
		r1 = randGen.Intn(8)
		c1 = randGen.Intn(8)
		r2 = randGen.Intn(8)
		c2 = randGen.Intn(8)
		if r1!= r2 && abs(r1-r2) > 1 && abs(c1-c2) > 1 {
			break
		}
	}
	grid[r1][c1] = 'K'
	grid[r2][c2] = 'k'
}

func placePieces(grid [][]rune, pieces string, isPawn bool) {
	numToPlace := randGen.Intn(len(pieces))
	for n := 0; n < numToPlace; n++ {
		r, c := 0, 0
		for {
			r = randGen.Intn(8)
			c = randGen.Intn(8)
			if grid[r][c] == 0 && (isPawn && (r!= 7 && r!= 0)) {
				break
			}
		}
		grid[r][c] = rune(pieces[n])
	}
}

func toFen(grid [][]rune) string {
	fen := strings.Builder{}
	countEmpty := 0
	for r := 0; r < 8; r++ {
		for c := 0; c < 8; c++ {
			ch := grid[r][c]
			fmt.Printf("%2c ", ch)
			if ch == 0 {
				countEmpty++
			} else {
				if countEmpty > 0 {
					fen.WriteString(fmt.Sprintf("%d", countEmpty))
					countEmpty = 0
				}
				fen.WriteRune(ch)
			}
		}
		if countEmpty > 0 {
			fen.WriteString(fmt.Sprintf("%d", countEmpty))
			countEmpty = 0
		}
		fen.WriteString("/")
		fmt.Println()
	}
	return fen.String() + " w - - 0 1"
}

