)

func isPalindrome(str string) bool {
	return str == strings.Join(reverse(strings.Split(str, "")), "")
}

func reverse(s []string) []string {
	for i, j := 0, len(s)-1; i < j; i, j = i+1, j-1 {
		s[i], s[j] = s[j], s[i]
	}
	return s
}

func main() {
	fmt.Println(isPalindrome("level"))
	fmt.Println(isPalindrome("levels"))
	fmt.Println(isPalindrome("A man, a plan, a canal. Panama"))
	fmt.Println(isPalindrome("race car"))
}

package main
 
import "fmt"
 
func circleSort(a []int) {
    len := len(a)
    for {
        if circleSortInner(a, 0, len-1, 0) == 0 {
            break
        }
    }
}
 
func circleSortInner(a []int, low, high, swaps int) int {
    if low == high {
        return swaps
    }
    lo := low
    hi := high
    mid := (hi - lo) / 2
    s := swaps
    for lo < hi {
        if a[lo] > a[hi] {
            a[lo], a[hi] = a[hi], a[lo]
            s++
        }
        lo++
        hi--
    }
    if lo == hi {
        if a[lo] > a[hi+1] {
            a[lo], a[hi+1] = a[hi+1], a[lo]
            s++
        }
    }
    s = circleSortInner(a, low, low+mid, s)
    s = circleSortInner(a, low+mid+1, high, s)
    return s
}
 
func main() {
    v := []int{10, 8, 4, 3, 1, 9, 0, 2, 7, 5, 6}
    fmt.Println("before:", v)
    circleSort(v)
    fmt.Println("after:", v)
}

