import (
	"fmt"
)

type factorion_t struct {
	f [12]uint
}

func (this *factorion_t) operator(i uint, b uint) bool {
	var sum uint = 0
	for j := i; j > 0; j /= b {
		sum += this.f[j%b]
	}
	return sum == i
}

func main() {
	var factorion factorion_t
	factorion.f[0] = 1
	for n := uint(1); n < 12; n++ {
		factorion.f[n] = factorion.f[n-1] * n
	}
	for b := uint(9); b <= 12; b++ {
		fmt.Printf("factorions for base %d:", b)
		for i := uint(1); i < 1500000; i++ {
			if factorion.operator(i, b) {
				fmt.Printf(" %d", i)
			}
		}
		fmt.Println()
	}
}

