import (
	"fmt"
)

func circle(x int, y int, c int, r int) bool {
	return (r * r) >= ((x = x / 2) * x) + ((y = y - c) * y)
}

func pixel(x int, y int, r int) string {
	if circle(x, y, -r / 2, r / 6) {
		return "#"
	}
	if circle(x, y, r / 2, r / 6) {
		return "."
	}
	if circle(x, y, -r / 2, r / 2) {
		return "."
	}
	if circle(x, y, r / 2, r / 2) {
		return "#"
	}
	if circle(x, y, 0, r) {
		if x < 0 {
			return "."
		} else {
			return "#"
		}
	}
	return " "
}

func yinYang(r int) {
	for y := -r; y <= r; y++ {
		for x := -2 * r; x <= 2 * r; x++ {
			fmt.Print(pixel(x, y, r))
		}
		fmt.Println()
	}
}

func main() {
	yinYang(18)
}

package main

import (
	"fmt"
	"math"
)

type StdDevAccumulator struct {
	n, sum, sumofsquares float64
}

func (sd *StdDevAccumulator) Add(num float64) {
	sd.n++
	sd.sum += num
	sd.sumofsquares += num * num
}

func (sd *StdDevAccumulator) StdDev() float64 {
	return math.Sqrt((sd.sumofsquares / sd.n) - math.Pow(sd.sum/sd.n, 2))
}

func main() {
	sd := &StdDevAccumulator{}
	i := 0
	for _, n := range []float64{2, 4, 4, 4, 5, 5, 7, 9} {
		sd.Add(n)
		fmt.Printf("adding %v: stddev of %v samples is %v\n", n, i+1, sd.StdDev())
		i++
	}
}

package main
 
import "fmt"
 
type Complex struct {
    real float64
    imag float64
}
 
func (c Complex) String() string {
    if c.imag >= 0.0 {
        return fmt.Sprintf("%g + %gi", c.real, c.imag)
    } else {
        return fmt.Sprintf("%g - %gi", c.real, -c.imag)
    }
}
 
func (c Complex) plus(other Complex) Complex {
    return Complex{c.real + other.real, c.imag + other.imag}
}
 
func (c Complex) times(other Complex) Complex {
    return Complex{
        c.real*other.real - c.imag*other.imag,
        c.real*other.imag + c.imag*other.real,
    }
}
 
func (c Complex) inv() Complex {
    denom := c.real*c.real + c.imag*c.imag
    return Complex{c.real / denom, -c.imag / denom}
}
 
func (c Complex) minus(other Complex) Complex {
    return c.plus(other.times(Complex{-1, 0}))
}
 
func (c Complex) div(other Complex) Complex {
    return c.times(other.inv())
}
 
func (c Complex) conj() Complex {
    return Complex{c.real, -c.imag}
}
 
func main() {
    x := Complex{1.0, 3.0}
    y := Complex{5.0, 2.0}
    fmt.Printf("x     =  %v\n", x)
    fmt.Printf("y     =  %v\n", y)
    fmt.Printf("x + y =  %v\n", x.plus(y))
    fmt.Printf("x - y =  %v\n", x.minus(y))
    fmt.Printf("x * y =  %v\n", x.times(y))
    fmt.Printf("x / y =  %v\n", x.div(y))
    fmt.Printf("-x    =  %v\n", x.times(Complex{-1, 0}))
    fmt.Printf("1 / x =  %v\n", x.inv())
    fmt.Printf("x*    =  %v\n", x.conj())
}

