	"Michigan", "Minnesota", "Mississippi", "Missouri", "Montana",
	"Nebraska", "Nevada", "New Hampshire", "New Jersey", "New Mexico",
	"New York", "North Carolina ", "North Dakota", "Ohio", "Oklahoma",
	"Oregon", "Pennsylvania", "Rhode Island", "South Carolina",
	"South Dakota", "Tennessee", "Texas", "Utah", "Vermont", "Virginia",
	"Washington", "West Virginia", "Wisconsin", "Wyoming",
	"New Kory", "Wen Kory", "York New", "Kory New", "New Kory",}

func main() {
	solve(states)
}

func solve(input []string) {
	orig := make(map[string]string)
	for _, s := range input {
		s = strings.ReplaceAll(s, " ", "")
		s = strings.ToLower(s)
		orig[s] = s
	}

	input = make([]string, 0, len(orig))
	for k := range orig {
		input = append(input, k)
	}

	map1 := make(map[string][][2]string)
	for i := 0; i < len(input)-1; i++ {
		pair0 := input[i]
		for j := i + 1; j < len(input); j++ {
			pair := [2]string{pair0, input[j]}
			s := pair0 + pair[1]
			key := sortString(s)

			val, ok := map1[key]
			if!ok {
				val = make([][2]string, 0)
			}
			val = append(val, pair)
			map1[key] = val
		}
	}

	for key, list := range map1 {
		for i := 0; i < len(list)-1; i++ {
			a := list[i]
			for j := i + 1; j < len(list); j++ {
				b := list[j]

				if len(unique(a[0], a[1], b[0], b[1])) < 4 {
					continue
				}

				fmt.Printf("%s + %s = %s + %s\n", orig[a[0]],
					orig[a[1]], orig[b[0]], orig[b[1]])
			}
		}
	}
}

func sortString(s string) string {
	r := []rune(s)
	sort.Slice(r, func(i, j int) bool {
		return r[i] < r[j]
	})
	return string(r)
}

func unique(strs...string) []string {
	keys := make(map[string]bool)
	list := []string{}
	for _, entry := range strs {
		if _, value := keys[entry];!value {
			keys[entry] = true
			list = append(list, entry)
		}
	}
	return list
}

package main

import (
	"fmt"
	"math/big"
)

func is_prime(n uint64) bool {
	if n < 2 {
		return false
	}
	if n%2 == 0 {
		return n == 2
	}
	if n%3 == 0 {
		return n == 3
	}
	for p := uint64(5); p*p <= n; p += 4 {
		if n%p == 0 {
			return false
		}
		p += 2
		if n%p == 0 {
			return false
		}
	}
	return true
}

type motzkin_generator struct {
	n  uint64
	m0 uint64
	m1 uint64
}

func (m *motzkin_generator) next() uint64 {
	var m_big *big.Int
	if m.n > 1 {
		m_big = new(big.Int)
		m_big.Mul(big.NewInt(int64(m.m1)), big.NewInt(int64(2*m.n+1)))
		m_big.Add(m_big, big.NewInt(int64(m.m0*3*m.n-3)))
		m_big.Div(m_big, big.NewInt(int64(m.n+2)))
	} else {
		m_big = big.NewInt(1)
	}
	m.n++
	m.m0 = m.m1
	m.m1 = m_big.Uint64()
	return m.m1
}

func main() {
	fmt.Println(" n          M(n)             Prime?")
	fmt.Println("-----------------------------------")
	mgen := new(motzkin_generator)
	for i := 0; i < 42; i++ {
		n := mgen.next()
		fmt.Printf("%2d %25d  %t\n", i, n, is_prime(n))
	}
}

package main
 
import (
	"fmt"
	"regexp"
	"strconv"
)
 
type Fractran struct {
	num []int
	den []int
	limit int
}
 
func main() {
	f := Fractran{"17/91 78/85 19/51 23/38 29/33 77/29 95/23 77/19 1/17 11/13 13/11 15/14 15/2 55/1", 2}
	f.compile()
	f.dump()
	f.exec(2)
}
 
func (f *Fractran) compile() {
	re := regexp.MustCompile(`\s*(\d*)\s*\/\s*(\d*)\s*(.*)`)
	m := re.FindStringSubmatch(f.num)
	for len(m) > 0 {
		n, _ := strconv.Atoi(m[1])
		d, _ := strconv.Atoi(m[2])
		f.num = append(f.num, n)
		f.den = append(f.den, d)
		m = re.FindStringSubmatch(m[3])
	}
}
 
func (f *Fractran) exec(val int) {
	n := 0
	for val!= 0 && n < f.limit {
		fmt.Println(n, ":", val)
		val = f.step(val)
		n++
	}
}
 
func (f *Fractran) step(val int) int {
	i := 0
	for i < len(f.den) && val%f.den[i]!= 0 {
		i++
	}
	if i < len(f.den) {
		return f.num[i] * val / f.den[i]
	}
	return 0
}
 
func (f *Fractran) dump() {
	for i := 0; i < len(f.den); i++ {
		fmt.Print(f.num[i], "/", f.den[i], " ")
	}
	fmt.Println()
}

