func millis() int64 {
	return time.Now().UnixNano() / 1000000
}

func benchmark(n int, func_ func(args...interface{}), args...interface{}) []int64 {
	times := make([]int64, n)
	for i := 0; i < n; i++ {
		m := millis()
		func_(args...)
		times[i] = millis() - m
	}
	return times
}

func main() {
	fmt.Println(benchmark(10, func(args...interface{}) {
		fmt.Println("Hello World")
	}))
}

