import (
    "fmt"
    "time"
)
 
func day_of_week(x int) string {
    switch x {
    case 1:
        return "Sweetmorn"
    case 2:
        return "Boomtime"
    case 3:
        return "Pungenday"
    case 4:
        return "Prickle-Prickle"
    default:
        return "Setting Orange"
    }
}
 
func season(x int) string {
    switch x {
    case 0:
        return "Chaos"
    case 1:
        return "Discord"
    case 2:
        return "Confusion"
    case 3:
        return "Bureaucracy"
    default:
        return "The Aftermath"
    }
}
 
func date(x int) int {
    if x%73 == 0 {
        return 73
    }
    return x % 73
}
 
func leap_year(x int) bool {
    return x%400 == 0 || (x%4 == 0 && x%100!= 0)
}
 
func ddate(y, d int) string {
    dyear := 1166 + y
    if leap_year(y) {
        if d == 60 {
            return fmt.Sprintf("St. Tib's Day, YOLD %d", dyear)
        } else if d >= 60 {
            d--
        }
    }
    return fmt.Sprintf("%s, %s %d, YOLD %d",
        day_of_week(d%5), season((d%73==0?d-1:d)/73), date(d), dyear)
}
 
func day_of_year(y, m, d int) int {
    month_lengths := []int{31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31}
    for m > 1 {
        d += month_lengths[m-2]
        if m == 3 && leap_year(y) {
            d++
        }
        m--
    }
    return d
}
 
func main() {
    now := time.Now()
    year, doy := now.Year(), now.YearDay()
    fmt.Println(ddate(year, doy))
}

