func handleClient(conn net.Conn) {
    defer conn.Close()
    input := bufio.NewReader(conn)
    output := bufio.NewWriter(conn)
    for {
        line, err := input.ReadString('\n')
        if err!= nil {
            return
        }
        output.WriteString(line)
        output.Flush()
    }
}
 
func main() {
