    }
    defer listener.Close()
    for {
        conn, err := listener.Accept()
        if err!= nil {
            fmt.Println(err)
            return
        }
        go handleClient(conn)
    }
}

package main

import (
	"fmt"
	"math/bits"
)

// Generates a lookup table for the checksums of all 8-bit values.
func generate_crc_lookup_table() []uint32 {
	reversed_polynomial := uint32(0xEDB88320)

	// This is a function object that calculates the checksum for a value,
	// then increments the value, starting from zero.
	type byte_checksum struct {
		n uint
	}

	func (b *byte_checksum) operator()() uint32 {
		checksum := uint32(b.n)
		b.n++

		for i := 0; i < 8; i++ {
			checksum = (checksum >> 1) ^ ((checksum & 0x1) * reversed_polynomial)
		}

		return checksum
	}

	table := make([]uint32, 256)
	for i := 0; i < 256; i++ {
		table[i] = byte_checksum{n: i}.operator()()
	}

	return table
}

// Calculates the CRC for any sequence of values. (You could use type traits and a
// static assert to ensure the values can be converted to 8 bits.)
func crc(values []byte) uint32 {
	// Generate lookup table only on first use then cache it - this is thread-safe.
	table := generate_crc_lookup_table()

	// Calculate the checksum - make sure to clip to 32 bits, for systems that don't
	// have a true (fast) 32-bit type.
	checksum := uint32(0xFFFFFFFF)
	for _, value := range values {
		checksum = table[(checksum^uint32(value))&0xFF] ^ (checksum >> 8)
	}
	return checksum & 0xFFFFFFFF
}

func main() {
	s := "The quick brown fox jumps over the lazy dog"
	fmt.Printf("%08x\n", crc([]byte(s)))
}

