import (
	"fmt"
)

type BinaryTreeNode struct {
	Value int
	Left  *BinaryTreeNode
	Right *BinaryTreeNode
}

func (node *BinaryTreeNode) FromArray(array []interface{}) *BinaryTreeNode {
	if len(array) == 0 {
		return nil
	}
	node.Value = array[0].(int)
	if len(array) > 1 {
		node.Left = &BinaryTreeNode{}
		node.Left.FromArray(array[1].([]interface{}))
	}
	if len(array) > 2 {
		node.Right = &BinaryTreeNode{}
		node.Right.FromArray(array[2].([]interface{}))
	}
	return node
}

func main() {
	root := &BinaryTreeNode{}
	root.FromArray([]interface{}{1, []interface{}{2, []interface{}{4, 7}, []interface{}{5}}, []interface{}{3, []interface{}{6, []interface{}{8}, []interface{}{9}}}})
	fmt.Println(root)
}

