import (
	"fmt"
	"math"
)

// Functions as values of a variable
var cube = func(x float64) float64 {
	return math.Pow(x, 3)
}
var cuberoot = func(x float64) float64 {
	return math.Pow(x, 1/3)
}

// Higher order function
var compose = func(f, g func(float64) float64) func(float64) float64 {
	return func(x float64) float64 {
		return f(g(x))
	}
}

// Storing functions in a array
var fun = []func(float64) float64{math.Sin, math.Cos, cube}
var inv = []func(float64) float64{math.Asin, math.Acos, cuberoot}

func main() {
	for i := 0; i < 3; i++ {
		// Applying the composition to 0.5
		fmt.Println(compose(inv[i], fun[i])(0.5))
	}
}

