import (
	"fmt"
	"math/big"
)

func gcd(a, b *big.Int) *big.Int {
	if a.Cmp(b) == 0 {
		return a
	}
	if a.Cmp(b) == -1 {
		return gcd(b, a)
	}
	return gcd(b, new(big.Int).Mod(a, b))
}

