	b := big.NewInt(20)
	fmt.Println(gcd(a, b))
}

package main
 
import (
	"fmt"
	"math/rand"
	"os"
	"strconv"
	"time"
)
 
const (
	BALLS = 1024
	h     = 45
)
 
var (
	n, w, cnt int
	x, y      []int
	b         []byte
)
 
func B(y, x int) byte { return b[y*w+x] }
func C(y, x int) bool { return B(y, x) =='' }
func V(i int) byte    { return B(y[i], x[i]) }
func rnd(a int) int   { return rand.Intn(a) }
 
func show_board() {
	for i := 0; i < h; i++ {
		for j := 0; j < w; j++ {
			if B(i, j) == '*' {
				if C(i-1, j) {
					fmt.Printf("\033[32m%c\033[m", B(i, j))
				} else {
					fmt.Printf("\033[31m%c\033[m", B(i, j))
				}
			} else {
				fmt.Printf("%c", B(i, j))
			}
		}
		fmt.Println()
	}
}
 
func init() {
	b = make([]byte, w*h)
	for i := range b {
		b[i] =''
	}
	x = make([]int, BALLS*2)
	y = x[BALLS:]
	for i := 0; i < n; i++ {
		for j := -i; j <= i; j += 2 {
			B(2*i+2, j+w/2) = '*'
		}
	}
	rand.Seed(time.Now().Unix())
}
 
func move(idx int) {
	xx := x[idx]
	yy := y[idx]
	c := byte(0)
	kill := false
	sl := 3
	o := 0
	if yy < 0 {
		return
	}
	if yy == h-1 {
		y[idx] = -1
		return
	}
	switch c = B(yy+1, xx); c {
	case'':
		yy++
	case '*':
		sl = 1
	default:
		if xx < w-1 && C(yy, xx+1) && C(yy+1, xx+1) {
			if rnd(sl) == 0 {
				o = 1
			}
		}
		if xx > 0 && C(yy, xx-1) && C(yy+1, xx-1) {
			if rnd(sl) == 0 {
				o = -1
			}
		}
		if o == 0 {
			kill = true
		}
		xx += o
	}
	c = V(idx)
	V(idx) =''
	y[idx] = yy
	x[idx] = xx
	B(yy, xx) = c
	if kill {
		y[idx] = -1
	}
}
 
func run() bool {
	var step = 0
	for i := 0; i < cnt; i++ {
		move(i)
	}
	if step == 2 && cnt < BALLS {
		step = 0
		x[cnt] = w / 2
		y[cnt] = 0
		if V(cnt)!='' {
			return false
		}
		V(cnt) = byte(rnd(80) + 43)
		cnt++
	}
	return true
}
 
func main() {
	if len(os.Args) < 2 || (n, _ = strconv.Atoi(os.Args[1]); n <= 3) {
		n = 5
	}
	if n >= 20 {
		n = 20
	}
	w = n*2 + 1
	init()
	for run() {
		show_board()
		time.Sleep(60 * time.Millisecond)
	}
}

