    "os"
)
 
func longer(a, b string) bool {
    if len(a) > len(b) {
        return true
    }
    return false
}
 
func main() {
    scanner := bufio.NewScanner(os.Stdin)
    var longest, lines string
    for scanner.Scan() {
        line := scanner.Text()
        if longer(line, longest) {
            lines, longest = line, line
        } else if!longer(longest, line) {
            lines += line
        }
    }
    fmt.Println(lines)
}

