package main

import (
	"fmt"
	"math/rand"
	"sync"
	"time"
)

type Latch struct {
	semafor int
}

func (l *Latch) wait() {
	l.semafor--
	for l.semafor > 0 {
		time.Sleep(1 * time.Nanosecond)
	}
}

type Worker struct {
}

func (w *Worker) do_work(how_long int, barrier *Latch, name string) {
	time.Sleep(time.Duration(how_long) * time.Millisecond)
	fmt.Println("Worker ", name, " finished work")
	barrier.wait()
	fmt.Println("Worker ", name, " finished assembly")
}

func main() {
	latch := Latch{5}
	var wg sync.WaitGroup
	wg.Add(5)
	for i := 0; i < 5; i++ {
		go func(i int) {
			defer wg.Done()
			w := Worker{}
			w.do_work(rand.Intn(3000-300)+300, &latch, fmt.Sprintf("%d", i))
		}(i)
	}
	wg.Wait()
	fmt.Println("Assembly is finished")
}

