// Version 1.2.60
 
const STX = "\u0002"
const ETX = "\u0003"
 
func bwt(s string) string {
    if strings.Contains(s, STX) || strings.Contains(s, ETX) {
        panic("String can't contain STX or ETX")
    }
    ss := STX + s + ETX
    table := make([]string, len(ss))
    for i := range table {
        table[i] = ss[i:] + ss[:i]
    }
    sort.Strings(table)
    r := ""
    for _, s := range table {
        r += string(s[len(s)-1])
    }
    return r
}
 
func ibwt(r string) string {
    len := len(r)
    table := make([]string, len)
    for i := range table {
        for j := 0; j < len; j++ {
            table[j] = string(r[j]) + table[j]
        }
        sort.Strings(table)
    }
    for _, row := range table {
        if strings.HasSuffix(row, ETX) {
            return row[1 : len-1]
        }
    }
    return ""
}
 
func makePrintable(s string) string {
    // substitute ^ for STX and | for ETX to print results
    return strings.Replace(strings.Replace(s, STX, "^", -1), ETX, "|", -1)
}
 
func main() {
    tests := []string{
        "banana",
        "appellee",
        "dogwood",
        "TO BE OR NOT TO BE OR WANT TO BE OR NOT?",
        "SIX.MIXED.PIXIES.SIFT.SIXTY.PIXIE.DUST.BOXES",
        "\u0002ABC\u0003",
    }
    for _, test := range tests {
        fmt.Println(makePrintable(test))
        var t string
        var err error
        if t, err = bwt(test); err!= nil {
            fmt.Println("ERROR: " + err.Error())
        } else {
            fmt.Println(" --> " + makePrintable(t))
        }
        r := ibwt(t)
        fmt.Println(" --> " + r + "\n")
    }
}

