	}
	defer window.Destroy()
 
renderer, err := sdl.CreateRenderer(window, -1, sdl.RENDERER_ACCELERATED)
	if err!= nil {
		panic(err)
	}
	defer renderer.Destroy()
 
var incr float64
 
running := true
 
for running {
	for event := sdl.PollEvent(); event!= nil; event = sdl.PollEvent() {
		switch event.(type) {
		case *sdl.QuitEvent:
			running = false
		}
	}
 
incr = (incr + 0.05) % 360
x1 := float64(window.GetSize().W / 2)
y1 := float64(window.GetSize().H / 2)
length := 5.0
angle := incr
 
renderer.SetDrawColor(255, 255, 255, 255)
renderer.Clear()
 
for i := 1; i < 151; i++ {
		x2 := x1 + math.Cos(angle)*length
		y2 := y1 + math.Sin(angle)*length
		renderer.SetDrawColor(255, 0, 0, 255)
		renderer.DrawLine(int32(x1), int32(y1), int32(x2), int32(y2))
		x1, y1 = x2, y2
		length += 3
		angle = (angle + incr) % 360
	}
 
renderer.Present()
time.Sleep(16 * time.Millisecond)
}
 
os.Exit(0)
}

package main
 
import (
    "fmt"
    "math"
)
 
// Use a struct as the monad
type LoggingMonad struct {
    Value float64
    Log   string
}
 
// Use the >> operator as the bind function
func (monad LoggingMonad) Bind(f func(float64) LoggingMonad) LoggingMonad {
    result := f(monad.Value)
    return LoggingMonad{result.Value, monad.Log + "\n" + result.Log}
}
 
// Define the three simple functions
func Root(x float64) float64 { return math.Sqrt(x) }
func AddOne(x float64) float64 { return x + 1 }
func Half(x float64) float64   { return x / 2.0 }
 
// Define a function to create writer monads from the simple functions
func MakeWriter(f func(float64) float64, message string) func(float64) LoggingMonad {
    return func(x float64) LoggingMonad { return LoggingMonad{f(x), message} }
}
 
// Derive writer versions of the simple functions
var writerRoot = MakeWriter(Root, "Taking square root")
var writerAddOne = MakeWriter(AddOne, "Adding 1")
var writerHalf = MakeWriter(Half, "Dividing by 2")
 
func main() {
    // Compose the writers to compute the golden ratio
    result := LoggingMonad{5, "Starting with 5"}.Bind(writerRoot).Bind(writerAddOne).Bind(writerHalf)
    fmt.Println(result.Log)
    fmt.Println("Result:", result.Value)
}

