import (
	"fmt"
	"os"
	"sort"
	"strconv"
	"strings"
)

func demoCompare[T any](a, b T, semantically string) {
	fmt.Printf("%v and %v are %v exactly %v equal.\n", a, b, if_(a == b, "", "not"), semantically)
	fmt.Printf("%v and %v are %v %v inequal.\n", a, b, if_(a!= b, "", "not"), semantically)
	fmt.Printf("%v is %v %v ordered before %v.\n", a, if_(a < b, "", "not"), semantically, b)
	fmt.Printf("%v is %v %v ordered after %v.\n", a, if_(a > b, "", "not"), semantically, b)
}

func main() {
	// Case-sensitive comparisons.
	a := os.Args[1]
	b := os.Args[2]
	demoCompare(a, b, "lexically")

	// Case-insensitive comparisons by folding both strings to a common case.
	a = strings.ToLower(a)
	b = strings.ToLower(b)
	demoCompare(a, b, "lexically")

	// Numeric comparisons; here 'double' could be any type for which the
	// relevant >> operator is defined, eg int, long, etc.
	numA, _ := strconv.ParseFloat(a, 64)
	numB, _ := strconv.ParseFloat(b, 64)
	demoCompare(numA, numB, "numerically")
}

func if_[T any](condition bool, a, b T) T {
	if condition {
		return a
	}
	return b
}

