package main

import (
	"fmt"
	"math"
)

func farey(n int) {
	type frac struct {
		d, n int
	}
	f1 := frac{0, 1}
	f2 := frac{1, n}
	t := frac{}
	k := 0
	fmt.Printf("%d/%d %d/%d", 0, 1, 1, n)
	for f2.n > 1 {
		k = (n + f1.n) / f2.n
		t = f1
		f1 = f2
		f2 = frac{f2.d*k - t.d, f2.n*k - t.n}
		fmt.Printf(" %d/%d", f2.d, f2.n)
	}
	fmt.Println()
}

var cache []uint64
var ccap int

func fareyLen(n int) uint64 {
	if n >= ccap {
		old := ccap
		if ccap == 0 {
			ccap = 16
		}
		for ccap <= n {
			ccap *= 2
		}
		cache = make([]uint64, ccap)
		for i := old; i < ccap; i++ {
			cache[i] = 0
		}
	} else if cache[n]!= 0 {
		return cache[n]
	}
	len := uint64(n) * (uint64(n) + 3) / 2
	p, q := 2, 0
	for p <= n {
		q = n/(n/p) + 1
		len -= fareyLen(n/p) * uint64(q-p)
		p = q
	}
	cache[n] = len
	return len
}

func main() {
	for n := 1; n <= 11; n++ {
		fmt.Printf("%d: ", n)
		farey(n)
	}
	for n := 100; n <= 1000; n += 100 {
		fmt.Printf("%d: %d items\n", n, fareyLen(n))
	}
	n := 10000000
	fmt.Printf("\n%d: %d items\n", n, fareyLen(n))
}

