import "fmt"
 
func insertionSort(array []int) {
    for index := 1; index < len(array); index++ {
        value := array[index]
        subIndex := index - 1
        for subIndex >= 0 && array[subIndex] > value {
            array[subIndex+1] = array[subIndex]
            subIndex--
        }
        array[subIndex+1] = value
    }
}
 
func main() {
    numbers := []int{5, 2, 3, 17, 12, 1, 8, 3, 4, 9, 7}
 
    func printArray(message string, array []int) {
        fmt.Printf("%s [", message)
        for index, number := range array {
            if index == len(array)-1 {
                fmt.Printf("%d", number)
            } else {
                fmt.Printf("%d, ", number)
            }
        }
        fmt.Println("]")
    }
 
    printArray("Unsorted:", numbers)
    insertionSort(numbers)
    printArray("Sorted:", numbers)
}

