func one_of_n(n int) int {
	currentChoice := 1
	for i := 2; i <= n; i++ {
		outerLimit := 1.0 / float64(i)
		if rand.Float64() < outerLimit {
			currentChoice = i
		}
	}
	return currentChoice
}

func main() {
	results := make(map[int]int)
	for i := 1; i < 11; i++ {
		results[i] = 0
	}

	for i := 0; i < 1000000; i++ {
		result := one_of_n(10)
		results[result] = results[result] + 1
	}

	for i := 1; i < 11; i++ {
		fmt.Printf("%d\t%d\n", i, results[i])
	}
}

