package main

import (
	"bufio"
	"fmt"
	"log"
	"os"
	"strconv"
	"strings"
)

func main() {
	filename := "readings.txt"
	total := map[string]int{"num_readings": 0, "num_good_readings": 0, "sum_readings": 0}
	invalid_count := 0
	max_invalid_count := 0
	invalid_run_end := ""

	file, err := os.Open(filename)
	if err!= nil {
		log.Fatal(err)
	}
	defer file.Close()

	scanner := bufio.NewScanner(file)
	for scanner.Scan() {
		num_readings := 0
		num_good_readings := 0
		sum_readings := 0.0

		fields := strings.Split(scanner.Text(), " ")
		for i := 1; i < len(fields); i += 2 {
			num_readings += 1
			flag, _ := strconv.Atoi(fields[i+1])
			if flag > 0 {
				num_good_readings += 1
				reading, _ := strconv.ParseFloat(fields[i], 64)
				sum_readings += reading
				invalid_count = 0
			} else {
				invalid_count += 1
				if invalid_count > max_invalid_count {
					max_invalid_count = invalid_count
					invalid_run_end = fields[0]
				}
			}
		}

		fmt.Printf("Line: %11s  Reject: %2d  Accept: %2d  Line_tot: %10.3f  Line_avg: %10.3f\n",
			fields[0], num_readings-num_good_readings, num_good_readings, sum_readings,
			float64(num_good_readings)/sum_readings)

		total["num_readings"] += num_readings
		total["num_good_readings"] += num_good_readings
		total["sum_readings"] += int(sum_readings)
	}

	if err := scanner.Err(); err!= nil {
		log.Fatal(err)
	}

	fmt.Println("")
	fmt.Println("File(s)  =", filename)
	fmt.Printf("Total    = %.3f\n", float64(total["sum_readings"]))
	fmt.Println("Readings =", total["num_good_readings"])
	fmt.Printf("Average  = %.3f\n", float64(total["sum_readings"])/float64(total["num_good_readings"]))
	fmt.Println("")
	fmt.Println("Maximum run(s) of", max_invalid_count, "consecutive false readings ends at", invalid_run_end)
}

