package main

import (
	"fmt"
	"math/big"
)

type unsignedStirling1 struct {
	cache map[[2]int]*big.Int
}

func (s *unsignedStirling1) get(n, k int) *big.Int {
	if k == 0 {
		if n == 0 {
			return big.NewInt(1)
		}
		return big.NewInt(0)
	}
	if k > n {
		return big.NewInt(0)
	}
	p := [2]int{n, k}
	if v, ok := s.cache[p]; ok {
		return v
	}
	s1 := new(big.Int)
	s1.Add(s.get(n-1, k-1), new(big.Int).Mul(big.NewInt(int64(n-1)), s.get(n-1, k)))
	s.cache[p] = s1
	return s1
}

func printStirlingNumbers(s *unsignedStirling1, n int) {
	fmt.Println("Unsigned Stirling numbers of the first kind:")
	fmt.Print("n/k")
	for j := 0; j <= n; j++ {
		if j == 0 {
			fmt.Printf("%2d", j)
		} else {
			fmt.Printf("%10d", j)
		}
	}
	fmt.Println()
	for i := 0; i <= n; i++ {
		fmt.Printf("%2d ", i)
		for j := 0; j <= i; j++ {
			if j == 0 {
				fmt.Printf("%2d", s.get(i, j))
			} else {
				fmt.Printf("%10d", s.get(i, j))
			}
		}
		fmt.Println()
	}
}

func main() {
	s1 := &unsignedStirling1{cache: make(map[[2]int]*big.Int)}
	printStirlingNumbers(s1, 12)
	fmt.Println("Maximum value of S1(n,k) where n == 100:")
	max := big.NewInt(0)
	for k := 0; k <= 100; k++ {
		max.Set(s1.get(100, k))
	}
	fmt.Println(max)
}

