package main
 
import (
    "fmt"
    "math/big"
)
 
var p = map[int]int{1: 0}
var lvl = [][]int{[]int{1}}
 
func path(n int) []int {
    if n == 0 {
        return []int{}
    }
    for n!= 0 && n!= p[n] {
        q := []int{}
        for _, x := range lvl[0] {
            for _, y := range path(x) {
                if x+y == n {
                    p[n] = x
                    q = append(q, n)
                    break
                }
            }
        }
        lvl[0] = q
    }
    return append(path(p[n]), n)
}
 
func treePow(x float64, n int) *big.Float {
    r := map[int]*big.Float{0: big.NewFloat(1), 1: big.NewFloat(x)}
    p := 0
    for _, i := range path(n) {
        r[i] = new(big.Float).Mul(r[i-p], r[p])
        p = i
    }
    return r[n]
}
 
func showPow(x float64, n int, isIntegral bool) {
    fmt.Println(n, ":", path(n))
    f := "%.0f"
    if!isIntegral {
        f = "%f"
    }
    fmt.Printf("%s ^ %d = %s\n\n", f, x, f, treePow(x, n))
}
 
func main() {
    for n := 0; n <= 17; n++ {
        showPow(2.0, n, true)
    }
    showPow(1.1, 81, false)
    showPow(3.0, 191, true)
}

func parseConfig(config string) map[string]interface{} {
    // this expression matches a line starting with an all capital word, 
    // and anything after it
    regex := regexp.MustCompile(`^([A-Z]+)(.*)$`)
    configObject := make(map[string]interface{})

    // loop until regex.exec returns null
    for _, match := range regex.FindAllStringSubmatch(config, -1) {
        // values will typically be an array with one element
        // unless we want an array
        // match[0] is the whole match, match[1] is the first group (all caps word), 
        // and match[2] is the second (everything through the end of line)
        key := match[1]
        values := strings.Split(match[2], ",")
        if len(values) == 1 {
            configObject[key] = values[0]
        } else {
            configObject[key] = values
        }
    }

    return configObject
}

package main

import (
	"fmt"
	"strings"
)

// asciiTable :: String
func asciiTable() string {
	return strings.Join(
		transpose(
			chunksOf(16)(
				enumFromTo(32)(127),
			),
		),
		"\n",
	)
}

// asciiEntry :: Int -> String
func asciiEntry(n int) string {
	k := asciiName(n)

	if "" == k {
		return ""
	}

	return fmt.Sprintf("%s : %s", justifyRight(4)(" ")(n.toString()), k)
}

// asciiName :: Int -> String
func asciiName(n int) string {
	if 32 > n || 127 < n {
		return ""
	}

	if 32 == n {
		return "Spc"
	}

	if 127 == n {
		return "Del"
	}

	return chr(n)
}

// chr :: Int -> Char
func chr(x int) string {
	// The character at unix code-point x.
	return string(x)
}

// chunksOf :: Int -> [a] -> [[a]]
func chunksOf(n int) func([]a) [][]a {
	return func(xs []a) [][]a {
		chunk := xs[:n]

		if 0 < len(chunk) {
			return append([][]a{chunk}, go(xs[n:]))
		}

		return [][]a{}
	}
}

// enumFromTo :: Int -> Int -> [Int]
func enumFromTo(m int) func(int) []int {
	return func(n int) []int {
		return make([]int, 1+n-m)
	}
}

// justifyLeft :: Int -> Char -> String -> String
func justifyLeft(n int) func(char) func(string) string {
	return func(c char) func(string) string {
		return func(s string) string {
			if n > len(s) {
				return s.padEnd(n, c)
			}

			return s
		}
	}
}

// justifyRight :: Int -> Char -> String -> String
func justifyRight(n int) func(char) func(string) string {
	return func(c char) func(string) string {
		return func(s string) string {
			if ""!= s {
				return s.padStart(n, c)
			}

			return ""
		}
	}
}

// transpose :: [[a]] -> [[a]]
func transpose(rows [][]a) [][]a {
	// The columns of the input transposed
	// into new rows.
	// This version assumes input rows of even length.
	if 0 < len(rows) {
		return rows[0].map(func(x a, i int) []a {
			return rows.flatMap(func(v []a) []a {
				return v[i]
			})
		})
	}

	return [][]a{}
}

// MAIN ---
func main() {
	fmt.Println(asciiTable())
}

task_description:
Jensen's Device

You are encouraged to solve this task according to the task description, using any language you may know.
This task is an exercise in call by name.

Jensen's Device is a computer programming technique devised by Danish computer scientist Jørn Jensen after studying the ALGOL 60 Report.

The following program was proposed to illustrate the technique. It computes the 100th harmonic number:

begin
   integer i;
   real procedure sum (i, lo, hi, term);
      value lo, hi;
      integer i, lo, hi;
      real term;
      comment term is passed by-name, and so is i;
   begin
      real temp;
      temp := 0;
      for i := lo step 1 until hi do
         temp := temp + term;
      sum := temp
   end;
   comment note the correspondence between the mathematical notation and the call to sum;
   print (sum (i, 1, 100, 1/i))
end

The above exploits call by name to produce the correct answer (5.187...). It depends on the assumption that an expression passed as an actual parameter to a procedure would be re-evaluated in the caller's context every time the corresponding formal parameter's value was required. If the last parameter to sum had been passed by value, and assuming the initial value of i were 1, the result would have been 100 × 1/1 = 100.

Moreover, the first parameter to sum, representing the "bound" variable of the summation, must also be passed by name (or at least by reference), otherwise changes to it (made within sum) would not be visible in the caller's context when computing each of the values to be added.
(On the other hand, the global variable does not have to use the same identifier, in this case i, as the formal parameter.)

Donald Knuth later proposed the Man or Boy Test as a more rigorous exercise.

code:
package main
 
import "fmt"
 
type Ref struct {
    value int
}
 
func harmonicSum(i *Ref, lo, hi int, term func() int) int {
    temp := 0
    i.value = lo
    for i.value <= hi {
        temp += term()
        i.value += 1
    }
    return temp
}
 
func main() {
    i := &Ref{}
    fmt.Println(harmonicSum(i, 1, 100, func() int { return 1 / i.value }))
}

package main
 
import (
	"fmt"
	"math"
)
 
type DerivF func(float64, float64) float64
 
func ivpEuler(f DerivF, y float64, step, endT int) {
	t := 0
	fmt.Printf(" Step %2d: ", step)
	for t <= endT {
		if t%10 == 0 {
			fmt.Printf("%7.3f", y)
		}
		y += float64(step) * f(float64(t), y)
		t += step
	}
	fmt.Println()
}
 
func analytic() {
	var t float64
	fmt.Printf("    Time: ")
	for t = 0; t <= 100; t += 10 {
		fmt.Printf("%7g", t)
	}
	fmt.Println("\nAnalytic: ")
	for t = 0; t <= 100; t += 10 {
		fmt.Printf("%7.3f", 20+80*math.Exp(-0.07*t))
	}
	fmt.Println()
}
 
func cooling(t, temp float64) float64 {
	return -0.07 * (temp - 20)
}
 
func main() {
	analytic()
	ivpEuler(cooling, 100, 2, 100)
	ivpEuler(cooling, 100, 5, 100)
	ivpEuler(cooling, 100, 10, 100)
}

