package main

import (
	"fmt"
	"github.com/mjibson/mpfr"
)

func h(n int) {
	a := mpfr.New(200)
	b := mpfr.New(200)

	a.Fac_ui(n) // a = n!

	b.Set_ui(2) // b = 2
	b.Log(b)    // b = log(b)
	b.Pow_ui(b, n+1) // b = b^(n+1)

	a.Div(a, b) // a = a / b
	a.Div_ui(a, 2) // a = a / 2

	b.Frac(a) // b = a - [a]
	if b.Cmp_d(.1) * b.Cmp_d(.9) > 0 {
		fmt.Printf("%2d: %23.4Rf  Y\n", n, a)
	} else {
		fmt.Printf("%2d: %23.4Rf  N\n", n, a)
	}
}

func main() {
	for n := 1; n <= 17; n++ {
		h(n)
	}
}

