import "fmt"

func main() {
	numbers := []int{1, 2, 3}
	total := sum(numbers)
	fmt.Println(total)

	product := 1
	for _, i := range numbers {
		product *= i
	}
	fmt.Println(product)
}

func sum(numbers []int) int {
	total := 0
	for _, i := range numbers {
		total += i
	}
	return total
}

package main
 
import (
    "bufio"
    "fmt"
    "os"
    "strconv"
    "strings"
)
 
func main() {
    if len(os.Args)!= 2 {
        fmt.Println("must supply file name")
        os.Exit(1)
    }
    fname := os.Args[1]
    f, err := os.Open(fname)
    if err!= nil {
        fmt.Println(err)
        os.Exit(1)
    }
    defer f.Close()
    scanner := bufio.NewScanner(f)
    for scanner.Scan() {
        line := scanner.Text()
        fields := strings.Fields(line)
        if len(fields) == 0 {
            continue
        }
        lastField := fields[len(fields)-1]
        if i, err := strconv.Atoi(lastField); err == nil && i > 6 {
            fmt.Println(line)
        }
    }
}

package main

import (
	"fmt"
	"math/rand"
	"time"
)

func main() {
	my_extended_string := make([]byte, 40)
	rand.Seed(time.Now().UnixNano())
	for i := 0; i < 40; i++ {
		my_extended_string[i] = byte(rand.Intn(256))
	}
	no_controls := deleteControls(my_extended_string)
	no_extended := deleteExtended(my_extended_string)
	fmt.Printf("string with all characters: %s\n", my_extended_string)
	fmt.Printf("string without control characters: %s\n", no_controls)
	fmt.Printf("string without extended characters: %s\n", no_extended)
}

func deleteControls(startstring []byte) []byte {
	noControls := make([]byte, 40)
	for i := 0; i < 40; i++ {
		if startstring[i] >= 32 && startstring[i]!= 127 {
			noControls[i] = startstring[i]
		}
	}
	return noControls
}

func deleteExtended(startstring []byte) []byte {
	noExtended := make([]byte, 40)
	for i := 0; i < 40; i++ {
		if startstring[i] <= 127 && startstring[i] >= 32 {
			noExtended[i] = startstring[i]
		}
	}
	return noExtended
}

