package main
 
import "fmt"
 
func egcd(a, b int) (int, int, int) {
    if a == 0 {
        return b, 0, 1
    }
    g, x, y := egcd(b%a, a)
    return g, y - (b/a)*x, x
}
 
func modInv(x, n int) int {
    g, x, _ := egcd(x, n)
    if g == 1 {
        return (x%n + n) % n
    }
    return -1
}
 
func chineseRemainder(residues, modulii []int) int {
    prod := 1
    for _, modulus := range modulii {
        prod *= modulus
    }
 
    sum := 0
    for i, modulus := range modulii {
        p := prod / modulus
        sum += residues[i] * modInv(p, modulus) * p
    }
 
    return sum % prod
}
 
func main() {
    modulii := []int{3, 5, 7}
    residues := []int{2, 3, 2}
 
    sol := chineseRemainder(residues, modulii)
    fmt.Println(sol)
}

package main
 
import (
    "fmt"
    "math/big"
)
 
func gcd(a, b *big.Int) *big.Int {
    for b.Cmp(big.NewInt(0))!= 0 {
        a, b = b, new(big.Int).Mod(a, b)
    }
    return a
}
 
func lcm(a, b *big.Int) *big.Int {
    return new(big.Int).Div(new(big.Int).Mul(a, b), gcd(a, b))
}
 
func isPrime(p *big.Int) bool {
    return p.Cmp(big.NewInt(1)) > 0 && all(f.Cmp(p) == 0 for f, e := factored(p))
}
 
var primeList = []*big.Int{big.NewInt(2), big.NewInt(3), big.NewInt(5), big.NewInt(7)}
 
func primes() chan *big.Int {
    ch := make(chan *big.Int)
    go func() {
        for _, p := range primeList {
            ch <- p
        }
        for p := big.NewInt(11); ; p.Add(p, big.NewInt(2)) {
            for!isPrime(p) {
                p.Add(p, big.NewInt(2))
            }
            primeList = append(primeList, new(big.Int).Set(p))
            ch <- p
        }
    }()
    return ch
}
 
func factored(a *big.Int) chan [2]*big.Int {
    ch := make(chan [2]*big.Int)
    go func() {
        for p := range primes() {
            j := big.NewInt(0)
            for a.Mod(a, p).Cmp(big.NewInt(0)) == 0 {
                a.Div(a, p)
                j.Add(j, big.NewInt(1))
            }
            if j.Cmp(big.NewInt(0)) > 0 {
                ch <- [2]*big.Int{p, j}
            }
            if a.Cmp(new(big.Int).Mul(p, p)) < 0 {
                break
            }
        }
        if a.Cmp(big.NewInt(1)) > 0 {
            ch <- [2]*big.Int{a, big.NewInt(1)}
        }
        close(ch)
    }()
    return ch
}
 
func multOrdr1(a, r [2]*big.Int) *big.Int {
    m := new(big.Int).Exp(r[0], r[1], nil)
    t := new(big.Int).Mul(new(big.Int).Sub(r[0], big.NewInt(1)), new(big.Int).Exp(r[0], new(big.Int).Sub(r[1], big.NewInt(1)), nil))
    qs := []*big.Int{big.NewInt(1)}
    for f := range factored(t) {
        qs = append(qs, new(big.Int).Mul(qs[len(qs)-1], new(big.Int).Exp(f[0], f[1], nil)))
    }
    for _, q := range qs {
        if new(big.Int).Exp(a, q, m).Cmp(big.NewInt(1)) == 0 {
            return q
        }
    }
    return nil
}
 
func multOrder(a, m *big.Int) *big.Int {
    if gcd(a, m).Cmp(big.NewInt(1))!= 0 {
        panic("gcd(a,m)!= 1")
    }
    mofs := make(chan *big.Int)
    go func() {
        for r := range factored(m) {
            mofs <- multOrdr1(a, r)
        }
        close(mofs)
    }()
    return reduce(lcm, mofs, big.NewInt(1))
}
 
func all(ch chan bool) bool {
    for b := range ch {
        if!b {
            return false
        }
    }
    return true
}
 
func reduce(f func(*big.Int, *big.Int) *big.Int, ch chan *big.Int, init *big.Int) *big.Int {
    acc := init
    for x := range ch {
        acc = f(acc, x)
    }
    return acc
}
 
func main() {
    fmt.Println(multOrder(big.NewInt(37), big.NewInt(1000)))
    b := new(big.Int).Sub(new(big.Int).Exp(big.NewInt(10), big.NewInt(20), nil), big.NewInt(1))
    fmt.Println(multOrder(big.NewInt(2), b))
    fmt.Println(multOrder(big.NewInt(17), b))
    b = new(big.Int).Add(big.NewInt(100000), big.NewInt(1))
    fmt.Println(multOrder(big.NewInt(54), b))
    fmt.Println(new(big.Int).Exp(big.NewInt(54), multOrder(big.NewInt(54), b), b))
    if any(func(r *big.Int) bool {
        return new(big.Int).Exp(big.NewInt(54), r, b).Cmp(big.NewInt(1)) == 0
    } for r := big.NewInt(1); r.Cmp(multOrder(big.NewInt(54), b)) < 0; r.Add(r, big.NewInt(1))) {
        fmt.Println("Exists a power r < 9090 where pow(54,r,b)==1")
    } else {
        fmt.Println("Everything checks.")
    }
}
 
func any(ch chan bool) bool {
    for b := range ch {
        if b {
            return true
        }
    }
    return false
}

package main

import (
	"fmt"
)

type Heap struct {
	data []int
}

func (h *Heap) Insert(val int) {
	h.data = append(h.data, val)
	h.heapifyUp()
}

func (h *Heap) heapifyUp() {
	index := len(h.data) - 1
	for h.data[index] > h.data[(index-1)/2] {
		h.data[index], h.data[(index-1)/2] = h.data[(index-1)/2], h.data[index]
		index = (index - 1) / 2
	}
}

func (h *Heap) heapifyDown() {
	index := 0
	for {
		left := 2*index + 1
		right := 2*index + 2
		largest := index
		if left < len(h.data) && h.data[left] > h.data[largest] {
			largest = left
		}
		if right < len(h.data) && h.data[right] > h.data[largest] {
			largest = right
		}
		if largest == index {
			break
		}
		h.data[index], h.data[largest] = h.data[largest], h.data[index]
		index = largest
	}
}

func (h *Heap) Delete() int {
	if len(h.data) == 0 {
		return -1
	}
	val := h.data[0]
	h.data[0] = h.data[len(h.data)-1]
	h.data = h.data[:len(h.data)-1]
	h.heapifyDown()
	return val
}

func (h *Heap) Print() {
	fmt.Println(h.data)
}

func main() {
	h := &Heap{}
	h.Insert(10)
	h.Insert(15)
	h.Insert(20)
	h.Insert(25)
	h.Insert(30)
	h.Insert(35)
	h.Insert(40)
	h.Insert(45)
	h.Insert(50)
	h.Insert(55)
	h.Insert(60)
	h.Insert(65)
	h.Insert(70)
	h.Insert(75)
	h.Insert(80)
	h.Insert(85)
	h.Insert(90)
	h.Insert(95)
	h.Insert(100)
	h.Print()
	h.Delete()
	h.Print()
}

