    "time"
)
 
// A collection of buckets, filled with random non-negative integers.
// There are atomic operations to look at the bucket contents, and
// to move amounts between buckets.
type BucketStore struct {
    // Creates a BucketStore with +nbuckets+ buckets. Fills each bucket
    // with a random non-negative integer.
    buckets []int
 
    // Mutex used to make operations atomic
    mutex sync.Mutex
}
 
// Returns an array with the contents of all buckets.
func (bs *BucketStore) Buckets() []int {
    bs.mutex.Lock()
    defer bs.mutex.Unlock()
 
    buckets := make([]int, len(bs.buckets))
    copy(buckets, bs.buckets)
    return buckets
}
 
// Transfers _amount_ to bucket at array index _destination_,
// from bucket at array index _source_.
func (bs *BucketStore) Transfer(destination, source, amount int) {
    // Do nothing if both buckets are same
    if destination == source {
        return
    }
 
    bs.mutex.Lock()
    defer bs.mutex.Unlock()
 
    // Clamp amount to prevent negative value in bucket
    amount = min(amount, bs.buckets[source])
 
    bs.buckets[source] -= amount
    bs.buckets[destination] += amount
}
 
// Create bucket store
var bucketStore = BucketStore{
    buckets: make([]int, 8),
}
 
// Get total amount in the store
const TOTAL = 8192
 
// Start a thread to equalize buckets
func equalize() {
    for {
        // Pick 2 buckets
        buckets := bucketStore.Buckets()
        first := rand.Intn(len(buckets))
        second := rand.Intn(len(buckets))
 
        // Swap buckets so that _first_ has not more than _second_
        if buckets[first] > buckets[second] {
            first, second = second, first
        }
 
        // Transfer half of the difference, rounded down
        bucketStore.Transfer(first, second, (buckets[second]-buckets[first])/2)
    }
}
 
// Start a thread to distribute values among buckets
func distribute() {
    for {
        // Pick 2 buckets
        buckets := bucketStore.Buckets()
        first := rand.Intn(len(buckets))
        second := rand.Intn(len(buckets))
 
        // Transfer random amount to _first_ from _second_
        bucketStore.Transfer(first, second, rand.Intn(buckets[second]))
    }
}
 
// Loop to display buckets
func display() {
    for {
        time.Sleep(time.Second)
 
        buckets := bucketStore.Buckets()
 
        // Compute the total value in all buckets.
        // We calculate this outside BucketStore so BucketStore can't cheat by
        // always reporting the same value.
        n := 0
        for _, v := range buckets {
            n += v
        }
 
        // Display buckets and total
        fmt.Printf("%v, total %d\n", buckets, n)
 
        if n!= TOTAL {
            // This should never happen
            fmt.Printf("ERROR: Total changed from %d to %d\n", TOTAL, n)
            return
        }
    }
}
 
func min(a, b int) int {
    if a < b {
        return a
    }
    return b
}
 
func main() {
    // Initialize buckets
    for i := range bucketStore.buckets {
        bucketStore.buckets[i] = rand.Intn(1024)
    }
 
    // Start threads
    go equalize()
    go distribute()
    display()
}

package main

import (
	"fmt"
	"strings"
)

func main() {
	compressed := Compress("TOBEORNOTTOBEORTOBEORNOT")
	fmt.Println(strings.Join(compressed, ", "))
	decompressed := Decompress(compressed)
	fmt.Println(decompressed)
}

func Compress(uncompressed string) []string {
	// build the dictionary
	dictionary := make(map[string]int)
	for i := 0; i < 256; i++ {
		dictionary[string(i)] = i
	}

	w := ""
	compressed := make([]string, 0)

	for _, c := range uncompressed {
		wc := w + string(c)
		if _, ok := dictionary[wc]; ok {
			w = wc
		} else {
			// write w to output
			compressed = append(compressed, fmt.Sprintf("%d", dictionary[w]))
			// wc is a new sequence; add it to the dictionary
			dictionary[wc] = len(dictionary)
			w = string(c)
		}
	}

	// write remaining output if necessary
	if w!= "" {
		compressed = append(compressed, fmt.Sprintf("%d", dictionary[w]))
	}

	return compressed
}

func Decompress(compressed []string) string {
	// build the dictionary
	dictionary := make(map[int]string)
	for i := 0; i < 256; i++ {
		dictionary[i] = string(i)
	}

	w := dictionary[toInt(compressed[0])]
	compressed = compressed[1:]
	decompressed := strings.Builder{}
	decompressed.WriteString(w)

	for _, k := range compressed {
		var entry string
		if _, ok := dictionary[toInt(k)]; ok {
			entry = dictionary[toInt(k)]
		} else if toInt(k) == len(dictionary) {
			entry = w + string(w[0])
		}

		decompressed.WriteString(entry)

		// new sequence; add it to the dictionary
		dictionary[len(dictionary)] = w + string(entry[0])

		w = entry
	}

	return decompressed.String()
}

func toInt(s string) int {
	i, _ := fmt.Sscanf(s, "%d", &i)
	return i
}

package main
 
import (
	"fmt"
	"strconv"
)
 
// Function to construct a new integer from the first and last digits of another
func gapfulness_divisor(number int) int {
	digit_string := strconv.Itoa(number)
	digit_count := len(digit_string)
	first_digit := digit_string[0:1]
	last_digit := digit_string[digit_count-1 : digit_count]
	return strconv.Atoi(first_digit + last_digit)
}
 
// Divisibility test to determine gapfulness
func is_gapful(number int) bool {
	return number%gapfulness_divisor(number) == 0
}
 
// Function to search for the least gapful number greater than a given integer
func next_gapful(number int) int {
	for!is_gapful(number) {
		number++
	}
	return number
}
 
// Constructor for a list of gapful numbers starting from given lower bound
func gapful_numbers(start int, amount int) []int {
	list := make([]int, 0, amount)
	number := start
	if amount > 0 && is_gapful(start) {
		list = append(list, start)
	}
	for len(list) < amount {
		number = next_gapful(number)
		list = append(list, number)
	}
	return list
}
 
// Formatter for a comma-separated list of gapful numbers
func single_line_gapfuls(start int, amount int) string {
	list := gapful_numbers(start, amount)
	return fmt.Sprint(list)
}
 
// Main algorithm
func main() {
	fmt.Println("First 100 gapful numbers starting at 30")
	fmt.Println(single_line_gapfuls(100, 30))
	fmt.Println("First 1000000 gapful numbers starting at 15")
	fmt.Println(single_line_gapfuls(1000000, 15))
	fmt.Println("First 1000000000 gapful numbers starting at 10")
	fmt.Println(single_line_gapfuls(1000000000, 10))
}

