package main
 
import (
    "fmt"
    "strconv"
)
 
func swap(str []byte, i, j int) {
    str[i], str[j] = str[j], str[i]
}
 
func reverse(str []byte, i, j int) {
    for ; i < j; i, j = i+1, j-1 {
        swap(str, i, j)
    }
}
 
func nextPermutation(str []byte) bool {
    len := len(str)
    if len < 2 {
        return false
    }
    for i := len - 1; i > 0; {
        j := i
        if str[i-1] < str[j] {
            k := len
            for str[i-1] >= str[k-1] {
                k--
            }
            swap(str, i-1, k-1)
            reverse(str, j, len-1)
            return true
        }
        i--
    }
    return false
}
 
func nextHighestInt(n uint32) uint32 {
    str := []byte(strconv.FormatUint(uint64(n), 10))
    if!nextPermutation(str) {
        return 0
    }
    n, _ = strconv.ParseUint(string(str), 10, 32)
    return uint32(n)
}
 
func main() {
    numbers := []uint32{0, 9, 12, 21, 12453, 738440, 45072010, 95322020}
    for _, n := range numbers {
        fmt.Printf("%d -> %d\n", n, nextHighestInt(n))
    }
    // Last one is too large to convert to an integer
    big := "9589776899767587796600"
    next := []byte(big)
    nextPermutation(next)
    fmt.Printf("%s -> %s\n", big, string(next))
}

package main
 
import (
    "fmt"
)
 
func waterCollected(tower []int) int {
    N := len(tower)
    highestLeft := make([]int, N)
    highestRight := make([]int, N)
    waterLevel := make([]int, N)
    for n := 1; n < N; n++ {
        highestLeft[n] = max(tower[:n])
    }
    for n := N - 2; n >= 0; n-- {
        highestRight[n] = max(tower[n:N])
    }
    for n := 0; n < N; n++ {
        waterLevel[n] = max(min(highestLeft[n], highestRight[n])-tower[n], 0)
    }
    fmt.Println("highest_left:  ", highestLeft)
    fmt.Println("highest_right: ", highestRight)
    fmt.Println("water_level:   ", waterLevel)
    fmt.Println("tower_level:   ", tower)
    fmt.Println("total_water:   ", sum(waterLevel))
    fmt.Println("")
    return sum(waterLevel)
}
 
func max(a []int) int {
    max := a[0]
    for _, v := range a {
        if v > max {
            max = v
        }
    }
    return max
}
 
func min(a, b int) int {
    if a < b {
        return a
    }
    return b
}
 
func sum(a []int) int {
    sum := 0
    for _, v := range a {
        sum += v
    }
    return sum
}
 
func main() {
    towers := [][]int{
        {1, 5, 3, 7, 2},
        {5, 3, 7, 2, 6, 4, 5, 9, 1, 2},
        {2, 6, 3, 5, 2, 8, 1, 4, 2, 2, 5, 3, 5, 7, 4, 1},
        {5, 5, 5, 5},
        {5, 6, 7, 8},
        {8, 7, 7, 6},
        {6, 7, 10, 7, 6},
    }
    for _, tower := range towers {
        waterCollected(tower)
    }
}

