package main

import (
	"fmt"
)

func lgen(even bool, nmax int) chan int {
	ch := make(chan int)
	go func() {
		start := 2
		if even {
			start = 1
		}
		n, lst := 1, make([]int, 0, nmax)
		for i := start; i <= nmax; i += 2 {
			lst = append(lst, i)
		}
		lenlst := len(lst)
		ch <- lst[0]
		for n < lenlst && lst[n] < lenlst {
			ch <- lst[n]
			n++
			for i, j := range lst[1:] {
				if (i+1)%lst[n]!= 0 {
					lst = append(lst, j)
				}
			}
			lenlst = len(lst)
		}
		for _, i := range lst[n:] {
			ch <- i
		}
		close(ch)
	}()
	return ch
}

func main() {
	for i := range lgen(false, 1000000) {
		fmt.Println(i)
	}
}

