package main
 
import (
    "fmt"
    "math"
)
 
func meanAngle(angles []float64) float64 {
    sinSum := 0.0
    cosSum := 0.0
    for _, angle := range angles {
        sinSum += math.Sin(angle * math.Pi / 180.0)
        cosSum += math.Cos(angle * math.Pi / 180.0)
    }
    return math.Atan2(sinSum/float64(len(angles)), cosSum/float64(len(angles))) * 180.0 / math.Pi
}
 
/* time string assumed to be in format "hh:mm:ss" */
func timeToSecs(t string) int {
    var hours, mins, secs int
    fmt.Sscanf(t, "%d:%d:%d", &hours, &mins, &secs)
    return 3600*hours + 60*mins + secs
}
 
/* 1 second of time = 360/(24 * 3600) = 1/240th degree */
func timeToDegrees(t string) float64 {
    return float64(timeToSecs(t)) / 240.0
}
 
func degreesToTime(d float64) string {
    var dd = d
    if dd < 0.0 {
        dd += 360.0
    }
    secs := int(dd * 240.0)
    hours := secs / 3600
    mins := secs % 3600
    secs = mins % 60
    mins /= 60
    return fmt.Sprintf("%2d:%2d:%2d", hours, mins, secs)
}
 
func main() {
    tm := []string{"23:00:17", "23:40:20", "00:12:45", "00:17:19"}
    angles := make([]float64, len(tm))
    for i, t := range tm {
        angles[i] = timeToDegrees(t)
    }
    mean := meanAngle(angles)
    fmt.Printf("Average time is : %s\n", degreesToTime(mean))
}

// helpers
// helper
func ordA(a string) int {
	return int(a[0]) - 65
}

// vigenere
func vigenere(text string, key string, decode bool) string {
	i := 0
	b := ""
	key = strings.ToUpper(key)
	key = strings.Replace(key, "[^A-Z]", "", -1)
	text = strings.ToUpper(text)
	text = strings.Replace(text, "[^A-Z]", "", -1)
	text = strings.Replace(text, "[A-Z]", func(a string) string {
		b = string(key[i%len(key)])
		i++
		if decode {
			return string(ordA(a) + (26 - ordA(b))%26 + 65)
		} else {
			return string(ordA(a) + ordA(b)%26 + 65)
		}
	}, -1)
	return text
}

// example
