package main
 
import (
    "fmt"
    "math/rand"
    "time"
)
 
func isPrime(n int) bool {
    if n == 0 || n == 1 || n == 4 || n == 6 || n == 8 || n == 9 {
        return false
    }
    if n == 2 || n == 3 || n == 5 || n == 7 {
        return true
    }
    s := 0
    d := n - 1
    for d%2 == 0 {
        d /= 2
        s++
    }
    if (1<<s)*d!= n-1 {
        panic("Assertion failed")
    }
 
    trialComposite := func(a int) bool {
        if pow(a, d, n) == 1 {
            return false
        }
        for i := 0; i < s; i++ {
            if pow(a, 1<<uint(i)*uint(d), n) == n-1 {
                return false
            }
        }
        return true
    }
 
    for i := 0; i < 8; i++ { // number of trials
        a := rand.Intn(n-2) + 2
        if trialComposite(a) {
            return false
        }
    }
    return true
}
 
func pow(a, b, n int) int {
    p := 1
    for b > 0 {
        if b&1!= 0 {
            p = (p * a) % n
        }
        b >>= 1
        a = (a * a) % n
    }
    return p
}
 
func pierpont(ulim, vlim int, first bool) []int {
    p := 0
    p2 := 1
    p3 := 1
    pp := []int{}
    for v := 0; v < vlim; v++ {
        for u := 0; u < ulim; u++ {
            p = p2 * p3
            if first {
                p++
            } else {
                p--
            }
            if isPrime(p) {
                pp = append(pp, p)
            }
            p2 *= 2
        }
        p3 *= 3
        p2 = 1
    }
    return pp
}
 
func main() {
    rand.Seed(time.Now().UnixNano())
    fmt.Println("First 50 Pierpont primes of the first kind:")
    pp := pierpont(120, 80, true)
    for i := 0; i < 50; i++ {
        fmt.Printf("%8d ", pp[i])
        if (i-9)%10 == 0 {
            fmt.Println()
        }
    }
    fmt.Println("First 50 Pierpont primes of the second kind:")
    pp2 := pierpont(120, 80, false)
    for i := 0; i < 50; i++ {
        fmt.Printf("%8d ", pp2[i])
        if (i-9)%10 == 0 {
            fmt.Println()
        }
    }
    fmt.Println("250th Pierpont prime of the first kind:", pp[249])
    fmt.Println("250th Pierpont prime of the second kind:", pp2[249])
}

package main
 
import (
    "fmt"
    "sort"
)
 
type replaceInfo struct {
    n    int
    text string
}
 
type byN []replaceInfo
 
func (a byN) Len() int           { return len(a) }
func (a byN) Swap(i, j int)      { a[i], a[j] = a[j], a[i] }
func (a byN) Less(i, j int) bool { return a[i].n < a[j].n }
 
func genericFizzBuzz(max int, info []replaceInfo) {
    for i := 1; i < max; i++ {
        foundWord := false
 
        for _, v := range info {
            if i%v.n == 0 {
                fmt.Print(v.text)
                foundWord = true
            }
        }
 
        if!foundWord {
            fmt.Print(i)
        }
 
        fmt.Println()
    }
}
 
func main() {
    info := []replaceInfo{
        {5, "Buzz"},
        {7, "Baxx"},
        {3, "Fizz"},
    }
 
    sort.Sort(byN(info))
 
    genericFizzBuzz(20, info)
}

package main
 
import (
    "fmt"
)
 
type Dir int
 
const (
    UP Dir = iota
    RIGHT
    DOWN
    LEFT
)
 
type Color int
 
const (
    WHITE Color = iota
    BLACK
)
 
func invertColor(grid [][]Color, x, y int) {
    if grid[y][x] == BLACK {
        grid[y][x] = WHITE
    } else {
        grid[y][x] = BLACK
    }
}
 
func nextDirection(grid [][]Color, x, y int, direction Dir) Dir {
    var turnRight bool
    if grid[y][x] == BLACK {
        turnRight = false
    } else {
        turnRight = true
    }
    directionIndex := int(direction)
    if turnRight {
        directionIndex = (directionIndex + 1) % 4
    } else {
        directionIndex = (directionIndex - 1) % 4
    }
    directions := []Dir{UP, RIGHT, DOWN, LEFT}
    direction = directions[directionIndex]
    return direction
}
 
func nextPosition(x, y int, direction Dir) (int, int) {
    switch direction {
    case UP:
        y--
    case RIGHT:
        x--
    case DOWN:
        y++
    case LEFT:
        x++
    }
    return x, y
}
 
func printGrid(grid [][]Color) {
    fmt.Println(80 * "#")
    for _, row := range grid {
        for _, v := range row {
            if v == WHITE {
                fmt.Print(" ")
            } else {
                fmt.Print("#")
            }
        }
        fmt.Println()
    }
}
 
func ant(width, height, maxNbSteps int) {
    grid := make([][]Color, height)
    for i := range grid {
        grid[i] = make([]Color, width)
    }
    x := width / 2
    y := height / 2
    direction := UP
 
    i := 0
    for i < maxNbSteps && 0 <= x && x < width && 0 <= y && y < height {
        invertColor(grid, x, y)
        direction = nextDirection(grid, x, y, direction)
        x, y = nextPosition(x, y, direction)
        printGrid(grid)
        i++
    }
}
 
func main() {
    ant(75, 52, 12000)
}

