package main

import (
	"fmt"
	"math/big"
	"strconv"
)

func main() {
	magnanimouses := make(chan int)
	go func() {
		for n := 0; ; n++ {
			if isMagnanimous(n) {
				magnanimouses <- n
			}
		}
	}()

	fmt.Println("First 45 magnanimous numbers:")
	for i := 0; i < 45; i++ {
		fmt.Printf("%d ", <-magnanimouses)
	}
	fmt.Println()

	fmt.Println("\n241st through 250th magnanimous numbers:")
	for i := 0; i < 10; i++ {
		fmt.Printf("%d ", <-magnanimouses)
	}
	fmt.Println()

	fmt.Println("\n391st through 400th magnanimous numbers:")
	for i := 0; i < 10; i++ {
		fmt.Printf("%d ", <-magnanimouses)
	}
	fmt.Println()
}

func isMagnanimous(n int) bool {
	s := strconv.Itoa(n)
	for i := 1; i < len(s); i++ {
		a, _ := new(big.Int).SetString(s[:i], 10)
		b, _ := new(big.Int).SetString(s[i:], 10)
		if!isPrime(a.Add(a, b)) {
			return false
		}
	}
	return true
}

func isPrime(n *big.Int) bool {
	if n.Cmp(big.NewInt(2)) < 0 {
		return false
	}
	if n.Cmp(big.NewInt(3)) < 0 {
		return true
	}
	if n.Mod(n, big.NewInt(2)).Cmp(big.NewInt(0)) == 0 {
		return false
	}
	if n.Mod(n, big.NewInt(3)).Cmp(big.NewInt(0)) == 0 {
		return false
	}
	i := big.NewInt(5)
	w := big.NewInt(2)
	for i.Mul(i, i).Cmp(n) <= 0 {
		if n.Mod(n, i).Cmp(big.NewInt(0)) == 0 {
			return false
		}
		i.Add(i, w)
		w.Sub(big.NewInt(6), w)
	}
	return true
}

