package main
 
import (
    "github.com/go-gl/gl/v2.1/gl"
    "github.com/go-gl/glfw/v3.1/glfw"
    "github.com/go-gl/mathgl/mgl32"
    "image"
    "image/color"
    "image/draw"
    "log"
)
 
func main() {
    err := glfw.Init()
    if err!= nil {
        log.Fatalln("failed to initialize glfw:", err)
    }
    defer glfw.Terminate()
 
    glfw.WindowHint(glfw.Resizable, glfw.False)
    glfw.WindowHint(glfw.ContextVersionMajor, 2)
    glfw.WindowHint(glfw.ContextVersionMinor, 1)
    window, err := glfw.CreateWindow(320, 240, "Red Pixel", nil, nil)
    if err!= nil {
        panic(err)
    }
    window.MakeContextCurrent()
 
    if err := gl.Init(); err!= nil {
        panic(err)
    }
 
    // Since we cant manipulate pixels directly, we need to manipulate the pixels on a canvas.
    // Only issue is that sub-pixels exist (which is probably why the red pixel looks like a smear on the output image)
    canvas := image.NewRGBA(image.Rect(0, 0, 320, 240))
    canvas.Set(100, 100, color.RGBA{0xff, 0, 0, 0xff})
 
    // Transform into a texture so piston can use it.
    texture, err := newTexture(canvas)
    if err!= nil {
        panic(err)
    }
 
    for!window.ShouldClose() {
        gl.Clear(gl.COLOR_BUFFER_BIT | gl.DEPTH_BUFFER_BIT)
        gl.ClearColor(1, 1, 1, 1)
 
        texture.draw()
 
        window.SwapBuffers()
        glfw.PollEvents()
    }
}
 
type texture struct {
    texture uint32
    width   int32
    height  int32
}
 
func newTexture(img image.Image) (*texture, error) {
    rgba := image.NewRGBA(img.Bounds())
    if rgba.Stride!= rgba.Rect.Size().X*4 {
        return nil, &image.NonUniformStrideError{
            Stride: rgba.Stride,
            Width:  rgba.Rect.Size().X * 4,
        }
    }
    draw.Draw(rgba, rgba.Bounds(), img, image.Point{0, 0}, draw.Src)
 
    var texture uint32
    gl.GenTextures(1, &texture)
    gl.BindTexture(gl.TEXTURE_2D, texture)
    gl.TexParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR)
    gl.TexParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR)
    gl.TexParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE)
    gl.TexParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE)
    gl.TexImage2D(
        gl.TEXTURE_2D,
        0,
        gl.RGBA,
        int32(rgba.Rect.Size().X),
        int32(rgba.Rect.Size().Y),
        0,
        gl.RGBA,
        gl.UNSIGNED_BYTE,
        gl.Ptr(rgba.Pix))
 
    return &texture{texture, int32(rgba.Rect.Size().X), int32(rgba.Rect.Size().Y)}, nil
}
 
func (t *texture) draw() {
    gl.BindTexture(gl.TEXTURE_2D, t.texture)
    gl.Begin(gl.QUADS)
    gl.TexCoord2f(0, 0)
    gl.Vertex2f(0, 0)
    gl.TexCoord2f(1, 0)
    gl.Vertex2f(float32(t.width), 0)
    gl.TexCoord2f(1, 1)
    gl.Vertex2f(float32(t.width), float32(t.height))
    gl.TexCoord2f(0, 1)
    gl.Vertex2f(0, float32(t.height))
    gl.End()
}
 
func (t *texture) delete() {
    gl.DeleteTextures(1, &t.texture)
}

