package main
 
import (
    "fmt"
    "math"
)
 
func doCalcs(weights [][]int, nVertices int) {
    dist := make([][]float64, nVertices)
    for i := range dist {
        dist[i] = make([]float64, nVertices)
        for j := range dist[i] {
            dist[i][j] = math.Inf(1)
        }
    }
    next := make([][]int, nVertices)
    for i := range next {
        next[i] = make([]int, nVertices)
        for j := range next[i] {
            if i!= j {
                next[i][j] = j + 1
            }
        }
    }
    for _, w := range weights {
        dist[w[0]-1][w[1]-1] = float64(w[2])
    }
    for k := 0; k < nVertices; k++ {
        for i := 0; i < nVertices; i++ {
            for j := 0; j < nVertices; j++ {
                if dist[i][k]+dist[k][j] < dist[i][j] {
                    dist[i][j] = dist[i][k] + dist[k][j]
                    next[i][j] = next[i][k]
                }
            }
        }
    }
    printResult(dist, next)
}
 
func printResult(dist [][]float64, next [][]int) {
    var u, v int
    var path string
    fmt.Println("pair     dist    path")
    for i := 0; i < len(next); i++ {
        for j := 0; j < len(next); j++ {
            if i!= j {
                u = i + 1
                v = j + 1
                path = fmt.Sprintf("%d -> %d    %2d     %s", u, v, int(dist[i][j]), u)
                for u!= v {
                    u = next[u-1][v-1]
                    path += " -> " + fmt.Sprint(u)
                }
                fmt.Println(path)
            }
        }
    }
}
 
func main() {
    weights := [][]int{
        {1, 3, -2},
        {2, 1, 4},
        {2, 3, 3},
        {3, 4, 2},
        {4, 2, -1},
    }
    nVertices := 4
    doCalcs(weights, nVertices)
}

package main

import (
	"fmt"
)

const (
	L_ALPHABET = "HXUCZVAMDSLKPEFJRIGTWOBNYQ"
	R_ALPHABET = "PTLNBQDEOYSFAVZKGJRIHWXUMC"
)

type Mode int

const (
	ENCRYPT Mode = iota
	DECRYPT
)

func Exec(text string, mode Mode, showSteps bool) string {
	left := []rune(L_ALPHABET)
	right := []rune(R_ALPHABET)
	eText := make([]rune, len(text))
	temp := make([]rune, 26)

	for i := 0; i < len(text); i++ {
		if showSteps {
			fmt.Printf("%s %s\n", string(left), string(right))
		}
		index := 0
		if mode == ENCRYPT {
			index = indexOf(right, text[i])
			eText[i] = left[index]
		} else {
			index = indexOf(left, text[i])
			eText[i] = right[index]
		}
		if i == len(text)-1 {
			break
		}

		// permute left

		for j := index; j < 26; j++ {
			temp[j-index] = left[j]
		}
		for j := 0; j < index; j++ {
			temp[26-index+j] = left[j]
		}
		store := temp[1]
		for j := 2; j < 14; j++ {
			temp[j-1] = temp[j]
		}
		temp[13] = store
		copy(left, temp)

		// permute right

		for j := index; j < 26; j++ {
			temp[j-index] = right[j]
		}
		for j := 0; j < index; j++ {
			temp[26-index+j] = right[j]
		}
		store = temp[0]
		for j := 1; j < 26; j++ {
			temp[j-1] = temp[j]
		}
		temp[25] = store
		store = temp[2]
		for j := 3; j < 14; j++ {
			temp[j-1] = temp[j]
		}
		temp[13] = store
		copy(right, temp)
	}

	return string(eText)
}

func indexOf(arr []rune, val rune) int {
	for i, v := range arr {
		if v == val {
			return i
		}
	}
	return -1
}

func main() {
	plainText := "WELLDONEISBETTERTHANWELLSAID"
	fmt.Printf("The original plaintext is : %s\n", plainText)
	fmt.Println("\nThe left and right alphabets after each permutation during encryption are :\n")
	cipherText := Exec(plainText, ENCRYPT, true)
	fmt.Printf("\nThe ciphertext is : %s\n", cipherText)
	plainText2 := Exec(cipherText, DECRYPT, false)
	fmt.Printf("\nThe recovered plaintext is : %s\n", plainText2)
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"
)

type wordMap map[int][]string

// Returns true if strings s1 and s2 differ by one character.
func oneAway(s1, s2 string) bool {
	if len(s1)!= len(s2) {
		return false
	}
	result := false
	for i := 0; i < len(s1); i++ {
		if s1[i]!= s2[i] {
			if result {
				return false
			}
			result = true
		}
	}
	return result
}

// Join a sequence of strings into a single string using the given separator.
func join(strs []string, separator string) string {
	result := ""
	if len(strs) > 0 {
		result += strs[0]
		for i := 1; i < len(strs); i++ {
			result += separator
			result += strs[i]
		}
	}
	return result
}

// If possible, print the shortest chain of single-character modifications that
// leads from "from" to "to", with each intermediate step being a valid word.
// This is an application of breadth-first search.
func wordLadder(words wordMap, from, to string) bool {
	poss, ok := words[len(from)]
	if!ok {
		fmt.Printf("%s into %s cannot be done.\n", from, to)
		return false
	}
	queue := [][]string{{from}}
	for len(queue) > 0 {
		curr := queue[0]
		queue = queue[1:]
		for i := 0; i < len(poss); {
			if!oneAway(poss[i], curr[len(curr)-1]) {
				i++
				continue
			}
			if to == poss[i] {
				curr = append(curr, to)
				fmt.Printf("%s\n", join(curr, " -> "))
				return true
			}
			temp := make([]string, len(curr))
			copy(temp, curr)
			temp = append(temp, poss[i])
			queue = append(queue, temp)
			poss = append(poss[:i], poss[i+1:]...)
		}
	}
	fmt.Printf("%s into %s cannot be done.\n", from, to)
	return false
}

func main() {
	words := make(wordMap)
	file, err := os.Open("unixdict.txt")
	if err!= nil {
		fmt.Printf("Cannot open file unixdict.txt.\n")
		os.Exit(1)
	}
	defer file.Close()
	scanner := bufio.NewScanner(file)
	for scanner.Scan() {
		word := scanner.Text()
		words[len(word)] = append(words[len(word)], word)
	}
	wordLadder(words, "boy", "man")
	wordLadder(words, "girl", "lady")
	wordLadder(words, "john", "jane")
	wordLadder(words, "child", "adult")
	wordLadder(words, "cat", "dog")
	wordLadder(words, "lead", "gold")
	wordLadder(words, "white", "black")
	wordLadder(words, "bubble", "tickle")
}

package main

import (
	"fmt"
	"container/heap"
)

func main() {
	// generic array
	ga := [3]int{1, 2, 3}
	fmt.Printf("[%d, %d, %d]\n", ga[0], ga[1], ga[2])

	// specialized array (one for each primitive type)
	da := [3]float64{4.0, 5.0, 6.0}
	fmt.Printf("[%f, %f, %f]\n", da[0], da[1], da[2])

	// immutable list
	li := []byte{7, 8, 9}
	fmt.Printf("%v\n", li)

	// mutable list
	ml := []int16{}
	ml = append(ml, 10)
	ml = append(ml, 11)
	ml = append(ml, 12)
	fmt.Printf("%v\n", ml)

	// immutable map
	hm := map[rune]int{'a': 97, 'b': 98, 'c': 99}
	fmt.Printf("%v\n", hm)

	// mutable map
	mm := map[rune]int{}
	mm['d'] = 100
	mm['e'] = 101
	mm['f'] = 102
	fmt.Printf("%v\n", mm)

	// immutable set (duplicates not allowed)
	se := map[int]bool{1: true, 2: true, 3: true}
	fmt.Printf("%v\n", se)

	// mutable set (duplicates not allowed)
	ms := map[int64]bool{}
	ms[4] = true
	ms[5] = true
	ms[6] = true
	fmt.Printf("%v\n", ms)

	// priority queue (imported from Java)
	pq := make(PriorityQueue, 0)
	heap.Push(&pq, "First")
	heap.Push(&pq, "Second")
	heap.Push(&pq, "Third")
	fmt.Printf("%v\n", pq)
}

type PriorityQueue []string

func (pq PriorityQueue) Len() int { return len(pq) }

func (pq PriorityQueue) Less(i, j int) bool {
	return pq[i] < pq[j]
}

func (pq PriorityQueue) Swap(i, j int) {
	pq[i], pq[j] = pq[j], pq[i]
}

func (pq *PriorityQueue) Push(x interface{}) {
	*pq = append(*pq, x.(string))
}

func (pq *PriorityQueue) Pop() interface{} {
	old := *pq
	n := len(old)
	x := old[n-1]
	*pq = old[0 : n-1]
	return x
}

