func main() {
	balls := make([]DutchColors, 12)
	values := []DutchColors{RED, WHITE, BLUE}
	rand.Seed(time.Now().UnixNano())

	for i := 0; i < len(balls); i++ {
		balls[i] = values[rand.Intn(len(values))]
	}
	fmt.Println("Before: ", balls)

	sort.Slice(balls, func(i, j int) bool {
		return balls[i] < balls[j]
	})
	fmt.Println("After:  ", balls)

	sorted := true
	for i := 1; i < len(balls); i++ {
		if balls[i-1] > balls[i] {
			sorted = false
			break
		}
	}
	fmt.Println("Correctly sorted: ", sorted)
}

// version 1.1.2
 
const MAXSUM = 99
 
func getPrimes(max int) []int {
    if max < 2 {
        return []int{}
    }
    lprimes := []int{2}
    for x := 3; x <= max; x += 2 {
        for _, p := range lprimes {
            if x%p == 0 {
                continue
            }
        }
        lprimes = append(lprimes, x)
    }
    return lprimes
}
 
func main() {
    descendants := make([][]int, MAXSUM+1)
    ancestors := make([][]int, MAXSUM+1)
    primes := getPrimes(MAXSUM)
 
    for _, p := range primes {
        descendants[p] = []int{p}
        for s := 1; s <= MAXSUM-p; s++ {
            temp := make([]int, len(descendants[s+p])+len(descendants[s]))
            copy(temp, descendants[s+p])
            for _, d := range descendants[s] {
                temp = append(temp, p*d)
            }
            descendants[s+p] = temp
        }
    }
 
    for _, p := range append(primes, 4) {
        descendants[p] = descendants[p][:len(descendants[p])-1]
    }
    total := 0
 
    for s := 1; s <= MAXSUM; s++ {
        sort.Ints(descendants[s])
        total += len(descendants[s])
        for _, d := range descendants[s] {
            if d > MAXSUM {
                break
            }
            ancestors[d] = append(ancestors[d], s)
        }
        if s < 21 || s > 45 && s < 47 || s > 73 && s < 75 {
            continue
        }
        fmt.Printf("%2d: %d Ancestor(s): %v\n", s, len(ancestors[s]), ancestors[s])
        fmt.Printf("%5d Descendant(s): %v\n", len(descendants[s]), descendants[s])
    }
 
    fmt.Printf("\nTotal descendants %d\n", total)
}

