	"math"
	"strconv"
	"strings"
)

func main() {
	fmt.Println()
	fmt.Println(" ***************************************************")
	fmt.Println(" *                                                 *")
	fmt.Println(" *              Integerness test                   *")
	fmt.Println(" *                                                 *")
	fmt.Println(" ***************************************************")
	fmt.Println()

	key := 'Y'

	for key == 'Y' {
		// Get number value from keyboard
		fmt.Print(" Enter number value : ")

		var LINE string
		fmt.Scanln(&LINE)

		// Get tolerance value from keyboard
		fmt.Print(" Enter tolerance value : ")

		var TOLERANCE float64
		fmt.Scanln(&TOLERANCE)

		// Resolve entered number format and set NUMBER value
		var NUMBER float64 = 0

		var N []string

		// Real number value
		if _, err := strconv.ParseFloat(LINE, 64); err == nil {
			NUMBER, _ = strconv.ParseFloat(LINE, 64)
		} else {
			// Rational number value
			if strings.Contains(LINE, "/") {
				N = strings.Split(LINE, "/")

				NUMBER = float64(N[0]) / float64(N[1])
			}
			// Inf value
			if strings.Contains(LINE, "INF") {
				NUMBER = math.Inf(1)
			}
			// Complex value
			if strings.Contains(LINE, "I") {
				// Delete letter i
				LINE = strings.ToUpper(LINE)
				LINE = strings.Replace(LINE, "I", "", -1)

				var r string = "" // real part
				var i string = "" // imaginary part

				var s int = 1 // sign offset

				// Get sign
				if LINE[0] == '+' || LINE[0] == '-' {
					r += string(LINE[0])
					LINE = LINE[1:]
					s--
				}
				// Get real part
				for _, element := range LINE {
					if element!= '+' && element!= '-' {
						r += string(element)
					} else {
						break
					}
				}
				// get imaginary part
				i = LINE[len(LINE)-(len(r)+s):]

				NUMBER, _ = strconv.ParseFloat(i, 64)
				if NUMBER == 0 {
					NUMBER, _ = strconv.ParseFloat(r, 64)
				} else {
					NUMBER = math.NaN()
				}

			}
			// NaN value
			NUMBER = math.NaN()
		}

		// Test
		var IS_INTEGER bool = false
		var IS_INTEGER_T bool = false

		if math.IsNaN(NUMBER) {
			IS_INTEGER = false
		} else if math.Round(NUMBER) == NUMBER {
			IS_INTEGER = true
		} else if TOLERANCE >= math.Abs(math.Round(NUMBER)-NUMBER) {
			IS_INTEGER_T = true
		}

		if IS_INTEGER {
			fmt.Println(" Is exact integer " + strconv.FormatBool(IS_INTEGER))
		} else {
			fmt.Println(" Is exact integer " + strconv.FormatBool(IS_INTEGER))
			fmt.Println(" Is integer with tolerance " + strconv.FormatBool(IS_INTEGER_T))
		}

		fmt.Println()
		fmt.Print(" Another test < Y /N >... ")
		fmt.Scanf("%c", &key)
		fmt.Println()
		fmt.Println()
	}

}

func fib(n int) int {
  if n < 0 {
    panic("fib of negative")
  }
  fib2 := func(m int) int {
    if m < 2 {
      return m
    } else {
      return fib2(m - 1) + fib2(m - 2)
    }
  }
  return fib2(n)
}

