type Vector3D struct {
    x, y, z float64
}
 
func (v Vector3D) plus(w Vector3D) Vector3D {
    return Vector3D{v.x + w.x, v.y + w.y, v.z + w.z}
}
 
func (v Vector3D) minus(w Vector3D) Vector3D {
    return Vector3D{v.x - w.x, v.y - w.y, v.z - w.z}
}
 
func (v Vector3D) times(s float64) Vector3D {
    return Vector3D{s * v.x, s * v.y, s * v.z}
}
 
func (v Vector3D) dot(w Vector3D) float64 {
    return v.x*w.x + v.y*w.y + v.z*w.z
}
 
func (v Vector3D) String() string {
    return fmt.Sprintf("(%g, %g, %g)", v.x, v.y, v.z)
}
 
func intersectPoint(
    rayVector Vector3D,
    rayPoint Vector3D,
    planeNormal Vector3D,
    planePoint Vector3D,
) Vector3D {
    diff := rayPoint.minus(planePoint)
    prod1 := diff.dot(planeNormal)
    prod2 := rayVector.dot(planeNormal)
    prod3 := prod1 / prod2
    return rayPoint.minus(rayVector.times(prod3))
}
 
func main() {
    rv := Vector3D{0.0, -1.0, -1.0}
    rp := Vector3D{0.0,  0.0, 10.0}
    pn := Vector3D{0.0,  0.0,  1.0}
    pp := Vector3D{0.0,  0.0,  5.0}
    ip := intersectPoint(rv, rp, pn, pp)
    fmt.Printf("The ray intersects the plane at %v\n", ip)
}

