)

func is_curzon(n, k int) bool {
	p := new(big.Int)
	p.Exp(big.NewInt(int64(k)), big.NewInt(int64(n)), nil)
	return p.Add(p, big.NewInt(1)).Mod(p.Add(p, big.NewInt(1)), big.NewInt(int64(k*n+1))).Cmp(big.NewInt(0)) == 0
}

func main() {
	for k := 2; k <= 10; k += 2 {
		fmt.Printf("Curzon numbers with base %d:\n", k)
		count := 0
		n := 1
		for count < 50 {
			if is_curzon(n, k) {
				fmt.Printf("%4d", n)
				count++
				if count%10 == 0 {
					fmt.Println()
				}
			}
			n++
		}
		for {
			if is_curzon(n, k) {
				count++
			}
			if count == 1000 {
				break
			}
			n++
		}
		fmt.Printf("1000th Curzon number with base %d: %d\n\n", k, n)
	}
}

