func coef(n int) {
	var i, j int
	if n < 0 || n > 63 {
		panic("n out of range")
	}
	c[i] = 1
	for i = 0; i < n; i++ {
		c[0] = -c[0]
		for j = i; j > 0; j-- {
			c[1+j] = c[j] - c[j-1]
		}
	}
}

func is_prime(n int) bool {
	var i int
	coef(n)
	c[0] += 1
	c[n] -= 1
	for i = n; i > 0 && c[i]%int64(n) == 0; i-- {
	}
	return i < 0
}

func show(n int) {
	for n > 0 {
		fmt.Printf("+%d x^%d", c[n], n)
		n--
	}
}

