                countInYear++
                monthsWithFive = append(monthsWithFive, fmt.Sprintf("%02d-%d", month, year))
            }
            calendar = calendar.AddDate(0, 1, 0)
        }
        if countInYear == 0 {
            yearsWithNone = append(yearsWithNone, year)
        }
    }
    fmt.Printf("There are %d months with 5 weekends\n", len(monthsWithFive))
