import (
	"fmt"
	"math"
)

func main() {
	generateTriples(13)
	generateTriples60(10000)
}

func generateTriples(max int) {
	for _, coeff := range []int{0, -1, 1} {
		count := 0
		fmt.Printf("Max side length %d, formula:  a*a + b*b %s= c*c\n", max, coeff == 0? "" : (coeff < 0? "-" : "+")+" a*b ")
		for a := 1; a <= max; a++ {
			for b := 1; b <= a; b++ {
				val := a*a + b*b + coeff*a*b
				c := int(math.Sqrt(float64(val)) +.5)
				if c > max {
					break
				}
				if c*c == val {
					fmt.Printf("  (%d, %d, %d)\n", a, b, c)
					count++
				}
			}
		}
		fmt.Printf("%d triangles\n", count)
	}
}

func generateTriples60(max int) {
	count := 0
	fmt.Printf("\nExtra Credit.\nMax side length %d, sides different length, formula:  a*a + b*b - a*b = c*c\n", max)
	for a := 1; a <= max; a++ {
		for b := 1; b < a; b++ {
			val := a*a + b*b - a*b
			c := int(math.Sqrt(float64(val)) +.5)
			if c*c == val {
				count++
			}
		}
	}
	fmt.Printf("%d triangles\n", count)
}

package main

import (
	"github.com/faiface/pixel"
	"github.com/faiface/pixel/pixelgl"
	"golang.org/x/image/colornames"
)

const (
	sections = 4
)

func main() {
	cfg := pixelgl.WindowConfig{
		Title:  "Pixel Rainbow",
		Bounds: pixel.R(0, 0, 1024, 768),
		VSync:  true,
	}
	win, err := pixelgl.NewWindow(cfg)
	if err!= nil {
		panic(err)
	}
	maxX := win.Bounds().Max.X
	maxY := win.Bounds().Max.Y
	colour := 0
	increment := 1
	for y := 0; y < maxY; y += maxY / sections {
		for x := 0; x < maxX; x += increment {
			colour = (colour + 1) % 16
			win.Set(x, y, colornames.Names[colour])
		}
		increment++
		colour = 0
	}
	win.Update()
	for!win.Closed() {
		win.Update()
	}
}

