import (
	"fmt"
	"strings"
)

func mult(strNum1, strNum2 string) string {
	a1 := strings.Split(strNum1, "")
	a2 := strings.Split(strNum2, "")
	aResult := make([]int, len(a1)+len(a2))

	for iterNum1 := 0; iterNum1 < len(a1); iterNum1++ {
		for iterNum2 := 0; iterNum2 < len(a2); iterNum2++ {
			idxIter := iterNum1 + iterNum2
			aResult[idxIter] = a1[iterNum1] * a2[iterNum2] + (idxIter >= len(aResult)? 0 : aResult[idxIter])

			if aResult[idxIter] > 9 {
				aResult[idxIter+1] = aResult[idxIter] / 10 + (idxIter+1 >= len(aResult)? 0 : aResult[idxIter+1])
				aResult[idxIter] %= 10
			}
		}
	}
	return strings.Join(aResult, "")
}

func main() {
	fmt.Println(mult("18446744073709551616", "18446744073709551616"))
}

