)
 
func main() {
	err := glfw.Init()
	if err!= nil {
		log.Fatalln("failed to initialize glfw:", err)
	}
	defer glfw.Terminate()
 
	window, err := glfw.CreateWindow(640, 480, "Hello OpenGL", nil, nil)
	if err!= nil {
		log.Fatalln("failed to open glfw window:", err)
	}
	window.MakeContextCurrent()
 
	if err := gl.Init(); err!= nil {
		log.Fatalln("failed to initialize gl:", err)
	}
 
	window.SetKeyCallback(func(w *glfw.Window, key glfw.Key, scancode int, action glfw.Action, mods glfw.ModifierKey) {
		if key == glfw.KeyEscape && action == glfw.Press {
			w.SetShouldClose(true)
		}
	})
 
	gl.MatrixMode(gl.PROJECTION)
	gl.LoadIdentity()
	gl.Ortho(-30, 30, -30, 30, -30, 30)
	gl.MatrixMode(gl.MODELVIEW)
 
	for!window.ShouldClose() {
		render()
		window.SwapBuffers()
		glfw.PollEvents()
	}
}
 
func render() {
	gl.ClearColor(0.3, 0.3, 0.3, 0.0)
	gl.Clear(gl.COLOR_BUFFER_BIT | gl.DEPTH_BUFFER_BIT)
	gl.ShadeModel(gl.SMOOTH)
	gl.LoadIdentity()
	gl.Translatef(-15.0, -15.0, 0.0)
	gl.Begin(gl.TRIANGLES)
	gl.Color3f(1.0, 0.0, 0.0)
	gl.Vertex2f(0.0, 0.0)
	gl.Color3f(0.0, 1.0, 0.0)
	gl.Vertex2f(30.0, 0.0)
	gl.Color3f(0.0, 0.0, 1.0)
	gl.Vertex2f(0.0, 30.0)
	gl.End()
}

type Card struct {
    pip string
    suit string
}

func (c *Card) String() string {
    return c.pip + " " + c.suit
}

type Deck struct {
    deck []Card
}

func (d *Deck) String() string {
    var s string
    for _, card := range d.deck {
        s += card.String() + ", "
    }
    return "[" + s + "]"
}

func (d *Deck) Shuffle() {
    for i := 0; i < len(d.deck); i++ {
        j := int(rand.Float64() * float64(len(d.deck)))
        d.deck[i], d.deck[j] = d.deck[j], d.deck[i]
    }
}

func (d *Deck) Deal() Card {
    return d.deck[0]
}

func NewDeck() *Deck {
    pips := []string{"2", "3", "4", "5", "6", "7", "8", "9", "10", "Jack", "Queen", "King", "Ace"}
    suits := []string{"Clubs", "Hearts", "Spades", "Diamonds"}
    deck := make([]Card, 0)
    for _, suit := range suits {
        for _, pip := range pips {
            deck = append(deck, Card{pip, suit})
        }
    }
    return &Deck{deck}
}

