import (
	"fmt"
)

func hailstone(n int) []int {
	seq := []int{n}
	for n!= 1 {
		if n%2 == 0 {
			n = n / 2
		} else {
			n = 3*n + 1
		}
		seq = append(seq, n)
	}
	return seq
}

func main() {
	fmt.Println("for n = 27, show sequence length and first and last 4 elements")
	hs27 := hailstone(27)
	fmt.Println(len(hs27), hs27[0:4], hs27[len(hs27)-4:])

	// find the longest sequence among n less than 100,000
	n := 0
	max := 0
	for i := 1; i < 100000; i++ {
		hs := hailstone(i)
		if len(hs) > max {
			max = len(hs)
			n = i
		}
	}
	fmt.Println(n, "has a hailstone sequence length of", max)
	fmt.Println("the largest number in that sequence is", hailstone(n)[max-1])
}

