import "fmt"

func isPrime(n int) int {
	if n%2 == 0 {
		return n == 2
	}
	if n%3 == 0 {
		return n == 3
	}
	d := 5
	for d*d <= n {
		if n%d == 0 {
			return 0
		}
		d += 2
		if n%d == 0 {
			return 0
		}
		d += 4
	}
	return 1
}

func main() {
	var i, d, p, r, q int = 929, 929, 929, 929, 929
	if!isPrime(q) {
		return
	}
	r = q
	for r > 0 {
		r <<= 1
	}
	d = 2*q + 1
	for {
		for p = r; p > 0; p <<= 1 {
			i = (i * i) % d
			if p < 0 {
				i *= 2
			}
			if i > d {
				i -= d
			}
		}
		if i!= 1 {
			d += 2 * q
		} else {
			break
		}
	}
	fmt.Printf("2^%d - 1 = 0 (mod %d)\n", q, d)
}

