package main
 
import (
    "crypto/sha256"
    "encoding/hex"
    "fmt"
    "strings"
)
 
func stringHashToByteHash(hash string) []byte {
    ba := make([]byte, 32)
    for i := 0; i < 64; i += 2 {
        ba[i/2], _ = hex.DecodeString(hash[i : i+2])
    }
    return ba
}
 
func matches(a, b []byte) bool {
    for i := 0; i < 32; i++ {
        if a[i]!= b[i] {
            return false
        }
    }
    return true
}
 
func main() {
    stringHashes := []string{
        "1115dd800feaacefdf481f1f9070374a2a81e27880f187396db67958b207cbad",
        "3a7bd3e2360a3d29eea436fcfb7e44c735d117c42d1c1835420b6b9942dd4f1b",
        "74e1bb62f8dabb8125a58852b63bdf6eaef667cb56ac7f7cdba6d7305c50a22f",
    }
    byteHashes := make([][]byte, 3)
    for i := 0; i < 3; i++ {
        byteHashes[i] = stringHashToByteHash(stringHashes[i])
    }
    letters := make([]byte, 26)
    for i := 0; i < 26; i++ {
        letters[i] = byte(97 + i)
    }
 
    for _, l := range letters {
        pwd := make([]byte, 5)
        pwd[0] = l
        for i1 := 97; i1 <= 122; i1++ {
            pwd[1] = byte(i1)
            for i2 := 97; i2 <= 122; i2++ {
                pwd[2] = byte(i2)
                for i3 := 97; i3 <= 122; i3++ {
                    pwd[3] = byte(i3)
                    for i4 := 97; i4 <= 122; i4++ {
                        pwd[4] = byte(i4)
                        ba := sha256.Sum256(pwd)
                        for j := 0; j < 3; j++ {
                            if matches(ba[:], byteHashes[j]) {
                                password := string(pwd)
                                fmt.Printf("%s => %s\n", password, stringHashes[j])
                                break
                            }
                        }
                    }
                }
            }
        }
    }
}

