import (
  "fmt"
  "os"
)
 
type FIFOList struct {
  TAILQ_ENTRY *FIFOList
}
 
func m_enqueue(i int, head *FIFOList) {
  var new_node *FIFOList = new(FIFOList)
  new_node.TAILQ_ENTRY = head.TAILQ_ENTRY
  head.TAILQ_ENTRY = new_node
}
 
func m_dequeue(i *int, head *FIFOList) bool {
  if head.TAILQ_ENTRY == nil {
    return false
  }
  *i = head.TAILQ_ENTRY.i
  head.TAILQ_ENTRY = head.TAILQ_ENTRY.TAILQ_ENTRY
  return true
}
 
func main() {
  var i int
  var head FIFOList
 
  head.TAILQ_ENTRY = nil
 
  /* insert 20 integer values */
  for i = 0; i < 20; i++ {
    m_enqueue(i, &head)
  }
 
  /* dequeue and print */
  for m_dequeue(&i, &head) {
    fmt.Printf("%d\n", i)
  }
 
  fmt.Fprintf(os.Stderr, "FIFO list %s\n",
    if m_dequeue(&i, &head) {
      "had still an element"
    } else {
      "is void!"
    })
 
  os.Exit(0)
}

