package main
 
import (
    "fmt"
    "math/rand"
    "time"
)
 
func main() {
    target := "METHINKS IT IS LIKE A WEASEL"
    copies := 100
    mutationRate := 20 // 1/20 = 0.05 = 5%
 
    // Generate first sentence, mutating each character
    start := mutate(target, 1) // 1/1 = 1 = 100%
 
    fmt.Println(target)
    fmt.Println(start)
 
    evolve(target, start, copies, mutationRate)
}
 
// Evolution algorithm
//
// Evolves `parent` to match `target`.  Returns the number of evolutions performed.
func evolve(target, parent string, copies, mutationRate int) int {
    counter := 0
    parentFitness := len(target) + 1
 
    for {
        counter++
 
        bestFitness, bestSentence := 0, ""
        for i := 0; i < copies; i++ {
            // Copy and mutate a new sentence.
            sentence := mutate(parent, mutationRate)
            // Find the fitness of the new mutation
            fitness := fitness(target, sentence)
            if fitness < bestFitness {
                bestFitness = fitness
                bestSentence = sentence
            }
        }
 
        // If the best mutation of this generation is better than `parent` then "the fittest
        // survives" and the next parent becomes the best of this generation.
        if bestFitness < parentFitness {
            parent = bestSentence
            parentFitness = bestFitness
            fmt.Printf("%s : generation %d with fitness %d\n", parent, counter, bestFitness)
 
            if bestFitness == 0 {
                return counter
            }
        }
    }
}
 
// Computes the fitness of a sentence against a target string, returning the number of
// incorrect characters.
func fitness(target, sentence string) int {
    fitness := 0
    for i := 0; i < len(target); i++ {
        if target[i]!= sentence[i] {
            fitness++
        }
    }
    return fitness
}
 
// Mutation algorithm.
//
// It mutates each character of a string, according to a `mutation_rate`.
func mutate(sentence string, mutationRate int) string {
    rand.Seed(time.Now().UnixNano())
    maybeMutate := func(c byte) byte {
        if rand.Intn(mutationRate) == 0 {
            return randomChar()
        }
        return c
    }
    mutated := make([]byte, len(sentence))
    for i := 0; i < len(sentence); i++ {
        mutated[i] = maybeMutate(sentence[i])
    }
    return string(mutated)
}
 
// Generates a random letter or space.
func randomChar() byte {
    // Returns a value in the range [A, Z] + an extra slot for the space character.  (The `u8`
    // values could be cast to larger integers for a better chance of the RNG hitting the proper
    // range).
    c := rand.Intn(int('Z'-'A') + 2)
    if c == int('Z'-'A')+1 {
        return''
    }
    return byte(c + 'A')
}

package main
 
import (
    "bufio"
    "fmt"
    "math/rand"
    "os"
    "strings"
    "time"
)
 
type Choice int
 
const (
    Rock Choice = iota
    Paper
    Scissors
)
 
func (c Choice) String() string {
    switch c {
    case Rock:
        return "Rock"
    case Paper:
        return "Paper"
    case Scissors:
        return "Scissors"
    }
    return "Unknown"
}
 
func beats(c1, c2 Choice) bool {
    return (c1 == Rock && c2 == Scissors) || (c1 == Scissors && c2 == Paper) || (c1 == Paper && c2 == Rock)
}
 
func aiMove(v [3]int) Choice {
    // weighted random choice
    rand.Seed(time.Now().UnixNano())
    rand := rand.Intn(v[0] + v[1] + v[2])
    if rand < v[0] {
        return Paper
    } else if rand < v[0]+v[1] {
        return Scissors
    }
    return Rock
}
 
func main() {
    fmt.Println("Rock, paper, scissors!")
    aiChoice := aiMove([3]int{0, 0, 0})
    ucf := [3]int{0, 0, 0} // user choice frequency
    score := [2]int{0, 0}
 
    for {
        fmt.Println("Please input your move: 'r', 'p' or's'. Type 'q' to quit")
 
        reader := bufio.NewReader(os.Stdin)
        input, _ := reader.ReadString('\n')
        uChoice := func() Choice {
            switch strings.ToLower(strings.TrimSpace(input)) {
            case "r":
                ucf[0]++
                return Rock
            case "p":
                ucf[1]++
                return Paper
            case "s":
                ucf[2]++
                return Scissors
            case "q":
                fmt.Println("Thank you for the game!")
                os.Exit(0)
            default:
                fmt.Println("Please enter a correct choice!")
                return uChoice()
            }
        }()
        fmt.Printf("You chose %s, I chose %s.\n", uChoice, aiChoice)
        if beats(uChoice, aiChoice) {
            score[0]++
            fmt.Println("You win!")
        } else if uChoice == aiChoice {
            fmt.Println("It's a tie!")
        } else {
            score[1]++
            fmt.Println("I win!")
        }
        fmt.Printf("-Score: You %d, Me %d\n", score[0], score[1])
 
        // only after the 1st iteration the AI knows the stats and can make
        // its weighted random move
        aiChoice = aiMove(ucf)
    }
}

package main

import (
	"fmt"
	"math/big"
)

func isqrt(x *big.Int) *big.Int {
	q := big.NewInt(1)
	r := big.NewInt(0)
	t := big.NewInt(0)
	for q.Cmp(x) <= 0 {
		q.Lsh(q, 2)
	}
	for q.Cmp(big.NewInt(1)) > 0 {
		q.Rsh(q, 2)
		t.Sub(x, r)
		t.Sub(t, q)
		r.Rsh(r, 1)
		if t.Cmp(big.NewInt(0)) >= 0 {
			x.Set(t)
			r.Add(r, q)
		}
	}
	return r
}

func main() {
	const max = 73
	const smax = 65
	power_width := ((big.NewInt(0).Exp(big.NewInt(7), big.NewInt(max), nil).String() / 3) << 2) + 3
	isqrt_width := (power_width + 1) >> 1
	fmt.Printf("Integer square root for numbers 0 to %d:\n", smax)
	for n := 0; n <= smax; n++ {
		fmt.Printf("%d ", (n / 10))
	}
	fmt.Println()
	for n := 0; n <= smax; n++ {
		fmt.Printf("%d ", n%10)
	}
	fmt.Println()
	fmt.Println(strings.Repeat("-", (smax<<1)+1))
	for n := 0; n <= smax; n++ {
		fmt.Printf("%d ", isqrt(big.NewInt(n)))
	}
	fmt.Println("\n\nInteger square roots of odd powers of 7 from 1 to %d:", max)
	s := fmt.Sprintf("[0,2] |[1,%d:n0] |[2,%d:n0]", power_width, isqrt_width).Replace("[", "{").Replace("]", "}")
	fmt.Printf(s, "n", "7 ^ n", "isqrt(7 ^ n)")
	fmt.Println(strings.Repeat("-", power_width+isqrt_width+6))
	p := big.NewInt(7)
	for n := 1; n <= max; n += 2 {
		p.Mul(p, big.NewInt(49))
		fmt.Printf(s, n, p, isqrt(p))
	}
}

package main

import (
	"fmt"
	"math/big"
)

// This function template works for any type representing integers or
// nonnegative integers, and has the standard operator overloads
// for arithmetic and comparison operators, as well as explicit
// conversion from int.
//
// OutputIterator must be an output iterator with value_type Integer.
// It receives the prime factors.
func decompose(n *big.Int, out chan *big.Int) {
	i := big.NewInt(2)
	for n.Cmp(big.NewInt(1))!= 0 {
		for n.Mod(n, i).Cmp(big.NewInt(0)) == 0 {
			out <- i
			n.Div(n, i)
		}
		i.Add(i, big.NewInt(1))
	}
}

// this is an output iterator similar to std::ostream_iterator, except
// that it outputs the separation string *before* the value, but not
// before the first value (i.e. it produces an infix notation).
type infix_ostream_iterator struct {
	stream *fmt.Stringer
	first  bool
	infix  string
}

func (iter *infix_ostream_iterator) next() {
	iter.first = false
}

func (iter *infix_ostream_iterator) operator(value *big.Int) {
	if!iter.first {
		iter.stream.String() + iter.infix
	}
	iter.stream.String() + value.String()
}

func main() {
	fmt.Println("please enter a positive number: ")
	var number big.Int
	fmt.Scanf("%d", &number)

	if number.Cmp(big.NewInt(0)) <= 0 {
		fmt.Println("this number is not positive!")
	} else {
		fmt.Println("decomposition: ")
		decompose(&number, infix_ostream_iterator{stream: fmt.Stringer, first: true, infix: " * "})
		fmt.Println("\n")
	}
}

