package main
 
import (
    "flag"
    "fmt"
    "image"
    "image/color"
    "image/png"
    "math/rand"
    "os"
    "time"
)
 
var (
    frames    = flag.Int("frames", 1000, "Number of frames")
    interval  = flag.Int("interval", 10, "Interval between frames")
    imageName = flag.String("image", "chaos_game.png", "Name of the output image")
)
 
func main() {
    flag.Parse()
 
    // Creating image
    img := image.NewRGBA(image.Rect(0, 0, 1000, 1000))
 
    // Getting data
    data := getData(*frames)
 
    // Drawing data
    drawData(img, data)
 
    // Saving image
    saveImage(img, *imageName)
}
 
func getData(n int) []image.Point {
    leg := 1000
    triangle := getTriangle(leg)
    curPoint := genPointWithinPoly(triangle)
    data := make([]image.Point, n)
    for i := 0; i < n; i++ {
        data[i] = curPoint
        curPoint = nextPoint(triangle, curPoint)
    }
    return data
}
 
func getTriangle(n int) image.Rectangle {
    ax, ay := 0, 0
 
    bx := 0.5 * n
    by := 0.75 * (n * n)
 
    cx, cy := n, 0
 
    return image.Rect(ax, ay, bx, by).Union(image.Rect(bx, by, cx, cy))
}
 
func genPointWithinPoly(poly image.Rectangle) image.Point {
    minx, miny, maxx, maxy := poly.Bounds()
    for {
        x := rand.Intn(maxx-minx) + minx
        y := rand.Intn(maxy-miny) + miny
        point := image.Point{x, y}
        if poly.Contains(point) {
            return point
        }
    }
}
 
func nextPoint(poly image.Rectangle, point image.Point) image.Point {
    vertices := poly.Bounds()
    randomVertex := image.Point{
        X: rand.Intn(vertices.Max.X-vertices.Min.X) + vertices.Min.X,
        Y: rand.Intn(vertices.Max.Y-vertices.Min.Y) + vertices.Min.Y,
    }
    line := image.Rect(point.X, point.Y, randomVertex.X, randomVertex.Y)
    return line.Add(line.Min).Div(2)
}
 
func drawData(img *image.RGBA, data []image.Point) {
    for _, point := range data {
        img.Set(point.X, point.Y, color.RGBA{255, 255, 255, 255})
    }
}
 
func saveImage(img *image.RGBA, name string) {
    file, err := os.Create(name)
    if err!= nil {
        fmt.Println(err)
        return
    }
    defer file.Close()
 
    png.Encode(file, img)
}

package main
 
import "fmt"
 
type DoublyLinkedList struct {
    value int
    next  *DoublyLinkedList
    prev  *DoublyLinkedList
}
 
func (l *DoublyLinkedList) Value() int {
    return l.value
}
 
func (l *DoublyLinkedList) Next() *DoublyLinkedList {
    return l.next
}
 
func (l *DoublyLinkedList) Prev() *DoublyLinkedList {
    return l.prev
}
 
func (l *DoublyLinkedList) Traverse() {
    for l!= nil {
        fmt.Println(l.value)
        l = l.next
    }
}
 
func (l *DoublyLinkedList) Print() {
    for l!= nil {
        fmt.Print(l.value, " ")
        l = l.next
    }
    fmt.Println()
}
 
func (l *DoublyLinkedList) Prev(prev *DoublyLinkedList) {
    l.prev = prev
}
 
func createDoublyLinkedListFromArray(ary []int) *DoublyLinkedList {
    var node, prev, head = &DoublyLinkedList{ary[0], nil, nil}
    prev = head
    for i := 1; i < len(ary); i++ {
        node = &DoublyLinkedList{ary[i], nil, prev}
        prev.next = node
        prev = node
    }
    return head
}
 
func main() {
    head := createDoublyLinkedListFromArray([]int{10, 20, 30, 40})
    head.Print()
}

package main

import (
	"fmt"
	"math"
)

func sameDigits(n, b int) bool {
	f := n % b
	for n /= b; n > 0; n /= b {
		if n%b!= f {
			return false
		}
	}
	return true
}

func isBrazilian(n int) bool {
	if n < 7 {
		return false
	}
	if n%2 == 0 {
		return true
	}
	for b := 2; b < n-1; b++ {
		if sameDigits(n, b) {
			return true
		}
	}
	return false
}

func isPrime(n int) bool {
	if n < 2 {
		return false
	}
	if n%2 == 0 {
		return n == 2
	}
	if n%3 == 0 {
		return n == 3
	}
	d := 5
	for d*d <= n {
		if n%d == 0 {
			return false
		}
		d += 2
		if n%d == 0 {
			return false
		}
		d += 4
	}
	return true
}

func main() {
	for _, kind := range []string{"", "odd ", "prime "} {
		quiet := false
		BigLim := 99999
		limit := 20
		fmt.Printf("First %d %sBrazillian numbers:\n", limit, kind)
		c := 0
		n := 7
		for c < BigLim {
			if isBrazilian(n) {
				if!quiet {
					fmt.Printf("%d ", n)
				}
				if c++; c == limit {
					fmt.Println("\n\n")
					quiet = true
				}
			}
			if quiet && kind!= "" {
				continue
			}
			if kind == "" {
				n++
			} else if kind == "odd " {
				n += 2
			} else if kind == "prime " {
				for {
					n += 2
					if isPrime(n) {
						break
					}
				}
			} else {
				panic("Unexpected")
			}
		}
		if kind == "" {
			fmt.Printf("The %dth Brazillian number is: %d\n\n", BigLim+1, n)
		}
	}
}

