package main

import (
	"bufio"
	"fmt"
	"os"
	"regexp"
	"strings"
)

func main() {
	fmt.Println("Please enter a multi-line story template terminated by a blank line\n")
	sb := strings.Builder{}
	scanner := bufio.NewScanner(os.Stdin)
	for scanner.Scan() {
		line := scanner.Text()
		if line == "" {
			break
		}
		sb.WriteString(line + "\n") // preserve line breaks
	}
	story := sb.String()
	// identify blanks
	r := regexp.MustCompile("<.*?>")
	blanks := r.FindAllString(story, -1)
	blanks = removeDuplicates(blanks)
	fmt.Println("Please enter your replacements for the following 'blanks' in the story:")
	for _, blank := range blanks {
		fmt.Printf("%s : ", blank[1:len(blank)-1])
		var repl string
		fmt.Scanln(&repl)
		story = strings.Replace(story, blank, repl, -1)
	}
	fmt.Printf("\n%s", story)
}

func removeDuplicates(elements []string) []string {
	// Use map to record duplicates as we find them.
	encountered := map[string]bool{}
	result := []string{}

	for v := range elements {
		if encountered[elements[v]] == true {
			// Do not add duplicate.
		} else {
			// Record this element as an encountered element.
			encountered[elements[v]] = true
			// Append to result slice.
			result = append(result, elements[v])
		}
	}
	// Return the new slice.
	return result
}

