package main
 
import (
    "bufio"
    "fmt"
    "io"
    "os"
    "strings"
    "time"
)
 
const FILENAME = "NOTES.TXT"
 
func showNotes() error {
    file, err := os.OpenFile(FILENAME, os.O_RDWR|os.O_CREATE, 0666)
    if err!= nil {
        return err
    }
    defer file.Close()
    bufReader := bufio.NewReader(file)
    contents, err := bufReader.ReadString('\n')
    if err!= nil {
        return err
    }
    fmt.Println(contents)
    return nil
}
 
func addToNotes(note string) error {
    file, err := os.OpenFile(FILENAME, os.O_APPEND|os.O_CREATE, 0666)
    if err!= nil {
        return err
    }
    defer file.Close()
    bufWriter := bufio.NewWriter(file)
    dateAndTime := time.Now().Format(time.RFC3339)
    _, err = bufWriter.WriteString(dateAndTime + "\n")
    if err!= nil {
        return err
    }
    _, err = bufWriter.WriteString("\t" + note + "\n")
    if err!= nil {
        return err
    }
    return bufWriter.Flush()
}
 
func main() {
    note := strings.Join(os.Args[1:], " ")
    if note == "" {
        showNotes()
    } else {
        addToNotes(note)
    }
}

package main

import (
	"fmt"
	"strings"
	"time"
)

func main() {
	fmt.Print(buildMonths(time.Date(1969, 1, 1, 0, 0, 0, 0, time.UTC)))
}

func buildMonths(date time.Time) string {
	sb := strings.Builder{}
	sb.WriteString(center("[Snoop]", 24*3))
	sb.WriteString("\n\n")
	sb.WriteString(center(date.Format("2006"), 24*3))
	sb.WriteString("\n\n")

	dts := []time.Time{}
	for {
		dts = append(dts, date)
		if date.Year()!= (date = date.AddDate(0, 1, 0)).Year() {
			break
		}
	}
	jd := make([]func() string, len(dts))
	for i, d := range dts {
		jd[i] = buildMonth(d)
	}

	sCur := 0
	for sCur < len(dts) {
		sb.WriteString("\n")
		curMonth := 0
		j := jd[sCur:sCur+3]
		sCur += len(j)
		breakOut := false
		for!breakOut {
			inj := 1
			for _, cd := range j {
				if cur := cd(); cur!= "" {
					sb.WriteString(cur)
					sb.WriteString("     ")
				} else {
					sb.WriteString("".PadRight(21,''))
					sb.WriteString("     ")
					breakOut = true
				}
				if inj%3 == 0 {
					sb.WriteString("\n")
				}
				inj++
			}
		}
	}
	return sb.String()
}

func buildMonth(date time.Time) func() string {
	return func() string {
		var sb strings.Builder
		sb.WriteString(center(date.Format("January"), 7*3))
		sb.WriteString("\n")
		sb.WriteString(strings.Join(strings.Split(strings.ToUpper(date.Format("Mon")), ""), " "))
		sb.WriteString("\n")
		cur := ""
		total := 0
		for day := -int(date.Weekday()); day < date.AddDate(0, 1, 0).Day()+int(date.Weekday()); day++ {
			cur += (day < 0? "  " : ((day < 9? " " : "") + (day + 1))) + " "
			if total++; total%7 == 0 {
				sb.WriteString(cur)
				sb.WriteString("\n")
				cur = ""
			}
		}
		sb.WriteString(cur)
		return sb.String()
	}
}

func center(s string, len int) string {
	return s.PadLeft((len-len(s))/2+len(s),'').PadRight((len),'')
}

func (s *strings.Builder) WriteString(str string) {
	s.WriteString(str)
}

func (s *strings.Builder) Write(p []byte) (n int, err error) {
	s.WriteString(string(p))
	return len(p), nil
}

func (s *strings.Builder) PadRight(n int, r rune) string {
	return s.String() + strings.Repeat(string(r), n)
}

func (s *strings.Builder) PadLeft(n int, r rune) string {
	return strings.Repeat(string(r), n) + s.String()
}

package main
 
import (
    "fmt"
    "math"
)
 
type Legendre struct {
    N int
    roots, weights []float64
    c [][]float64
}
 
func NewLegendre(N int) *Legendre {
    l := &Legendre{N: N}
    l.roots = make([]float64, N)
    l.weights = make([]float64, N)
    l.c = make([][]float64, N+1)
    for i := range l.c {
        l.c[i] = make([]float64, N+1)
    }
 
    // coefficients:
    l.c[0][0] = 1.0
    l.c[1][1] = 1.0
    for n := 2; n <= N; n++ {
        l.c[n][0] = (1-n)*l.c[n-2][0] / float64(n)
        for i := 1; i <= n; i++ {
            l.c[n][i] = ((2*n-1)*l.c[n-1][i-1]-(n-1)*l.c[n-2][i]) / float64(n)
        }
    }
 
    // roots:
    var x, x1 float64
    for i := 1; i <= N; i++ {
        x = math.Cos(math.Pi * (float64(i)-0.25) / (float64(N)+0.5))
        for {
            x1 = x
            x -= l.evaluate(N, x) / l.diff(N, x)
            if x == x1 {
                break
            }
        }
 
        x1 = l.diff(N, x)
        l.roots[i-1] = x
        l.weights[i-1] = 2 / ((1-x*x)*x1*x1)
    }
 
    fmt.Println("Roots:")
    for _, r := range l.roots {
        fmt.Printf(" %f", r)
    }
    fmt.Println()
    fmt.Println("Weights:")
    for _, w := range l.weights {
        fmt.Printf(" %f", w)
    }
    fmt.Println()
 
    return l
}
 
func (l *Legendre) evaluate(n int, x float64) float64 {
    s := l.c[n][n]
    for i := n; i > 0; i-- {
        s *= x
        s += l.c[n][i-1]
    }
    return s
}
 
func (l *Legendre) diff(n int, x float64) float64 {
    return float64(n) * (x*l.evaluate(n, x)-l.evaluate(n-1, x)) / (x*x - 1)
}
 
func (l *Legendre) integrate(f func(float64) float64, a, b float64) float64 {
    c1 := (b - a) / 2
    c2 := (b + a) / 2
    s := 0.0
    for i := 0; i < l.N; i++ {
        s += l.weights[i] * f(c1*l.roots[i]+c2)
    }
    return c1 * s
}
 
func main() {
    legendre := NewLegendre(5)
    fmt.Println("integrating Exp(x) over [-3, 3]:")
    fmt.Printf("\t%10.8f\n", legendre.integrate(math.Exp, -3.0, 3.0))
    fmt.Println("compared to actual:")
    fmt.Printf("\t%10.8f\n", math.Exp(3.0)-math.Exp(-3.0))
}

