func BubbleSort(comparable []Comparable) {
    changed := false
    for changed == false {
        changed = false
        for a := 0; a < len(comparable)-1; a++ {
            if comparable[a].CompareTo(comparable[a+1]) > 0 {
                tmp := comparable[a]
                comparable[a] = comparable[a+1]
                comparable[a+1] = tmp
                changed = true
            }
        }
    }
}

