func Worker(semaphore *sync.Semaphore, id int) {
	semaphore.Acquire()
	fmt.Printf("Thread %d has a semaphore & is now working.\n", id) // response message
	time.Sleep(2 * time.Second)
	fmt.Printf("Thread %d done.\n", id)
	semaphore.Release()
}

func main() {
	numOfThreads := runtime.NumCPU()
	semaphore := sync.NewSemaphore(numOfThreads / 2)

	var tasks []sync.Thread
	for id := 0; id < numOfThreads; id++ {
		tasks = append(tasks, sync.Thread(Worker, semaphore, id))
	}

	return 0
}

