package main
 
import "fmt"
 
type filt_t struct {
	i, v uint
}
 
// ludics with at least so many elements and reach at least such value
func ludic(min_len, min_val uint) []uint {
	var cap, i, v, active, nf uint
	f := make([]filt_t, cap)
	f[1].i = 4
	for v = 1; ; v++ {
		for i = 1; i < active && f[i].i--; i++ {
		}
		if i < active {
			f[i].i = f[i].v
		} else if nf == f[i].i {
			f[i].i = f[i].v
			active++ // enable one more filter
		} else {
			if nf >= cap {
				cap *= 2
				f = make([]filt_t, cap)
			}
			f[nf] = filt_t{v + nf, v}
			if nf >= min_len && v >= min_val {
				break
			}
			nf++
		}
	}
	// pack the sequence into a uint[]
	// filt_t struct was used earlier for cache locality in loops
	x := make([]uint, nf)
	for i = 0; i < nf; i++ {
		x[i] = f[i].v
	}
	return x
}
 
func find(a []uint, v uint) bool {
	for i := 0; a[i] <= v; i++ {
		if v == a[i] {
			return true
		}
	}
	return false
}
 
func main() {
	x := ludic(2005, 1000)
	fmt.Println("First 25:")
	for i := 0; i < 25; i++ {
		fmt.Printf(" %d", x[i])
	}
	fmt.Println()
	for i := 0; x[i] <= 1000; i++ {
	}
	fmt.Printf("Ludics below 1000: %d\n", i)
	fmt.Println("Ludic 2000 to 2005:")
	for i := 2000; i <= 2005; i++ {
		fmt.Printf(" %d", x[i-1])
	}
	fmt.Println()
	fmt.Println("Triples below 250:")
	for i := 0; x[i]+6 <= 250; i++ {
		if find(x, x[i]+2) && find(x, x[i]+6) {
			fmt.Printf(" (%d %d %d)", x[i], x[i]+2, x[i]+6)
		}
	}
	fmt.Println()
}

