func main() {
	fmt.Println("Find Common Directory Path")
	fmt.Println()
	PathSet1 := []string{"/home/user1/tmp/coverage/test", "/home/user1/tmp/covert/operator", "/home/user1/tmp/coven/members"}
	fmt.Println("Path Set 1 (All Absolute Paths):")
	for _, path := range PathSet1 {
		fmt.Println(path)
	}
	fmt.Printf("Path Set 1 Common Path: %s\n", FindCommonPath("/", PathSet1))
}

func FindCommonPath(Separator string, Paths []string) string {
	CommonPath := ""
	SeparatedPath := strings.Split(Paths[0], Separator)
	for _, PathSegment := range SeparatedPath {
		if CommonPath == "" && All(Paths, func(str string) bool { return strings.HasPrefix(str, PathSegment) }) {
			CommonPath = PathSegment
		} else if All(Paths, func(str string) bool { return strings.HasPrefix(str, CommonPath+Separator+PathSegment) }) {
			CommonPath += Separator + PathSegment
		} else {
			break
		}
	}
	return CommonPath
}

func All(Paths []string, f func(string) bool) bool {
	for _, str := range Paths {
		if!f(str) {
			return false
		}
	}
	return true
}

