	"math"
)

func eratosthenes(n int) (sieve []byte, c int) {
	if n < 2 {
		return nil, 0
	}
	c = n - 1
	m := int(math.Sqrt(float64(n)))
	sieve = make([]byte, n+1)
	sieve[0] = 1
	sieve[1] = 1
	for i := 2; i <= m; i++ {
		if sieve[i] == 0 {
			for j := i * i; j <= n; j += i {
				if sieve[j] == 0 {
					sieve[j] = 1
					c--
				}
			}
		}
	}
	return
}

func main() {
	sieve, c := eratosthenes(1000000)
	fmt.Println(c)
	fmt.Println(sieve[1000000-1])
}

