import "fmt"
 
// can be any swap function. This swap is optimized for numbers.
func swap(x, y *int) {
	if x == y {
		return
	}
	*x ^= *y
	*y ^= *x
	*x ^= *y
}
func cocktailsort(a []int) {
	for {
		// packing two similar loops into one
		flag := true
		start := []int{1, len(a) - 1}
		end := []int{len(a), 0}
		inc := []int{1, -1}
		for it := 0; it < 2; it++ {
			flag = true
			for i := start[it]; i!= end[it]; i += inc[it] {
				if a[i-1] > a[i] {
					swap(&a[i-1], &a[i])
					flag = false
				}
			}
			if flag {
				return
			}
		}
	}
}
 
func main() {
	a := []int{5, -1, 101, -4, 0, 1, 8, 6, 2, 3}
	cocktailsort(a)
	fmt.Println(a)
}

