package main
 
import (
    "fmt"
    "strconv"
    "strings"
)
 
type Cidr struct {
    Address      uint32
    MaskLength   uint32
}
 
func cidrParse(str string) (cidr Cidr, err error) {
    var a, b, c, d, m int
    _, err = fmt.Sscanf(str, "%d.%d.%d.%d/%d", &a, &b, &c, &d, &m)
    if err!= nil {
        return
    }
    if m < 1 || m > 32 || a < 0 || a > 255 || b < 0 || b > 255 || c < 0 || c > 255 || d < 0 || d > 255 {
        err = fmt.Errorf("invalid CIDR")
        return
    }
    mask := ^((1 << (32 - m)) - 1)
    address := (uint32(a) << 24) + (uint32(b) << 16) + (uint32(c) << 8) + uint32(d)
    address &= uint32(mask)
    cidr.Address = address
    cidr.MaskLength = uint32(m)
    return
}
 
func cidrFormat(cidr Cidr) string {
    address := cidr.Address
    d := address & 255
    address >>= 8
    c := address & 255
    address >>= 8
    b := address & 255
    address >>= 8
    a := address & 255
    return fmt.Sprintf("%d.%d.%d.%d/%d", a, b, c, d, cidr.MaskLength)
}
 
func main() {
    tests := []string{
        "87.70.141.1/22",
        "36.18.154.103/12",
        "62.62.197.11/29",
        "67.137.119.181/4",
        "161.214.74.21/24",
        "184.232.176.184/18",
    }
    for _, test := range tests {
        cidr, err := cidrParse(test)
        if err!= nil {
            fmt.Printf("%s: %s\n", test, err)
            continue
        }
        fmt.Printf("%-18s -> %s\n", test, cidrFormat(cidr))
    }
}

