package main

import (
	"fmt"
	"time"
)

func easterDate(year int) time.Time {
	// Anonymous Gregorian algorithm
	// http://en.wikipedia.org/wiki/Computus#Algorithms

	a := year % 19
	b, c := year/100, year%100
	d, e := b/4, b%4
	f := (b + 8) / 25
	g := (b - f + 1) / 3
	h := (19*a + b - d - g + 15) % 30
	i, k := c/4, c%4
	l := (32 + 2*e + 2*i - h - k) % 7
	m := (a + 11*h + 22*l) / 451
	numerator := h + l - 7*m + 114
	month := numerator / 31
	day := (numerator % 31) + 1
	return time.Date(year, time.Month(month), day, 0, 0, 0, 0, time.UTC)
}

var offsets = map[string]int{
	"easter":     0,
	"ascension":  39,
	"pentecost":  49,
	"trinity":    56,
	"corpus":     60,
}

func emitDates(year int) {
	e := easterDate(year)
	dates := make([]string, len(offsets))
	for item, offset := range offsets {
		dates = append(dates, e.AddDate(0, 0, offset).Format(" 2 Jan"))
	}
	fmt.Printf("%4d: %s\n", year, strings.Join(dates, ", "))
}

func main() {
	fmt.Print("year:")
	for item, _ := range offsets {
		fmt.Printf("%9s", item)
	}
	fmt.Println()
	for year := 400; year <= 2100; year += 100 {
		emitDates(year)
	}
	fmt.Println()
	for year := 2010; year <= 2020; year++ {
		emitDates(year)
	}
}

