package main

import (
	"fmt"
	"os"
)

func main() {
	file := "test.ppm"
	bitmap := Bitmap{Width: 10, Height: 10}
	WriteBitmapToPPM(file, bitmap)
}

type Bitmap struct {
	Width  int
	Height int
}

func (b *Bitmap) GetPixel(x, y int) Color {
	return Color{R: 0, G: 0, B: 0}
}

type Color struct {
	R, G, B byte
}

func WriteBitmapToPPM(file string, bitmap Bitmap) {
	//Use a streamwriter to write the text part of the encoding
	writer, _ := os.Create(file)
	writer.WriteString("P6\n")
	writer.WriteString(fmt.Sprintf("%d  %d\n", bitmap.Width, bitmap.Height))
	writer.WriteString("255\n")
	writer.Close()
	//Switch to a binary writer to write the data
	writerB, _ := os.OpenFile(file, os.O_APPEND, 0666)
	for x := 0; x < bitmap.Height; x++ {
		for y := 0; y < bitmap.Width; y++ {
			color := bitmap.GetPixel(y, x)
			writerB.Write([]byte{color.R})
			writerB.Write([]byte{color.G})
			writerB.Write([]byte{color.B})
		}
	}
	writerB.Close()
}

package main

import (
	"fmt"
	"math"
)

var smallPrimes []int

func isPrime(test int) bool {
	if test < 2 {
		return false
	}
	if test%2 == 0 {
		return test == 2
	}
	for d := 3; d*d <= test; d += 2 {
		if test%d == 0 {
			return false
		}
	}
	return true
}

func initSmallPrimes(numPrimes int) {
	smallPrimes = append(smallPrimes, 2)

	count := 0
	for n := 3; count < numPrimes; n += 2 {
		if isPrime(n) {
			smallPrimes = append(smallPrimes, n)
			count++
		}
	}
}

func divisorCount(n int) int {
	count := 1
	for n%2 == 0 {
		n /= 2
		count++
	}
	for d := 3; d*d <= n; d += 2 {
		q := n / d
		r := n % d
		dc := 0
		for r == 0 {
			dc += count
			n = q
			q = n / d
			r = n % d
		}
		count += dc
	}
	if n!= 1 {
		count *= 2
	}
	return count
}

func OEISA073916(n int) uint64 {
	if isPrime(n) {
		return uint64(math.Pow(float64(smallPrimes[n-1]), float64(n-1)))
	}

	count := 0
	var result uint64
	for i := 1; count < n; i++ {
		if n%2 == 1 {
			//  The solution for an odd (non-prime) term is always a square number
			root := int(math.Sqrt(float64(i)))
			if root*root!= i {
				continue
			}
		}
		if divisorCount(i) == n {
			count++
			result = uint64(i)
		}
	}
	return result
}

func main() {
	const MAX = 15
	initSmallPrimes(MAX)
	for n := 1; n <= MAX; n++ {
		if n == 13 {
			fmt.Printf("A073916(%d) = One more bit needed to represent result.\n", n)
		} else {
			fmt.Printf("A073916(%d) = %d\n", n, OEISA073916(n))
		}
	}
}

package main
 
import "fmt"
 
func queenPuzzle(rows, columns int) [][]int {
    if rows <= 0 {
        return [][]int{{}}
    } else {
        return addQueen(rows - 1, columns)
    }
}
 
func addQueen(newRow, columns int, prevSolution [][]int) [][]int {
    var newSolutions [][]int
    prev := queenPuzzle(newRow, columns)
    for i := 0; i < len(prev); i++ {
        solution := prev[i]
        for newColumn := 0; newColumn < columns; newColumn++ {
            if!hasConflict(newRow, newColumn, solution) {
                newSolutions = append(newSolutions, append(solution, newColumn))
            }
        }
    }
    return newSolutions
}
 
func hasConflict(newRow, newColumn int, solution []int) bool {
    for i := 0; i < newRow; i++ {
        if solution[i] == newColumn ||
            solution[i] + i == newColumn + newRow || 
            solution[i] - i == newColumn - newRow {
                return true
        }
    }
    return false
}
 
func main() {
    fmt.Println(queenPuzzle(8,8))
}

package main

import (
	"fmt"
)

func countDivisors(n int) int {
	if n < 2 {
		return 1
	}
	count := 2 // 1 and n
	for i := 2; i <= n/2; i++ {
		if n%i == 0 {
			count++
		}
	}
	return count
}

func main() {
	maxDiv := 0
	count := 0
	fmt.Println("The first 20 anti-primes are:")
	for n := 1; count < 20; n++ {
		d := countDivisors(n)
		if d > maxDiv {
			fmt.Printf("%d ", n)
			maxDiv = d
			count++
		}
	}
	fmt.Println()
}

