package main
 
import (
    "fmt"
)
 
type Amb struct {
    streams         []IValueSet
    assertsOrActions []IAssertOrAction
    stopped         bool
}
 
func (this *Amb) DefineValues(values...interface{}) IAmbValue {
    return this.DefineValueSet(values)
}
 
func (this *Amb) DefineValueSet(values []interface{}) IAmbValue {
    stream := new(ValueSet)
    stream.Enumerable = values
    this.streams = append(this.streams, stream)
    return stream
}
 
func (this *Amb) Assert(function func() bool) *Amb {
    this.assertsOrActions = append(this.assertsOrActions, &AmbAssert{
        Level:           len(this.streams),
        IsValidFunction: function,
    })
    return this
}
 
func (this *Amb) Perform(action func()) *Amb {
    this.assertsOrActions = append(this.assertsOrActions, &AmbAction{
        Level:  len(this.streams),
        Action: action,
    })
    return this
}
 
func (this *Amb) Stop() {
    this.stopped = true
}
 
func (this *Amb) Dispose() {
    this.RunLevel(0, 0)
    if!this.stopped {
        panic(AmbException{})
    }
}
 
func (this *Amb) RunLevel(level, actionIndex int) {
    for actionIndex < len(this.assertsOrActions) && this.assertsOrActions[actionIndex].Level() <= level {
        if!this.assertsOrActions[actionIndex].Invoke() || this.stopped {
            return
        }
        actionIndex++
    }
    if level < len(this.streams) {
        iterator := this.streams[level].CreateIterator()
        defer iterator.Dispose()
        for iterator.MoveNext() {
            this.RunLevel(level+1, actionIndex)
        }
    }
}
 
type IValueSet interface {
    CreateIterator() IValueSetIterator
}
 
type IValueSetIterator interface {
    MoveNext() bool
    Dispose()
}
 
type IAssertOrAction interface {
    Level() int
    Invoke() bool
}
 
type AmbAssert struct {
    Level           int
    IsValidFunction func() bool
}
 
func (this *AmbAssert) Level() int {
    return this.Level
}
 
func (this *AmbAssert) Invoke() bool {
    return this.IsValidFunction()
}
 
type AmbAction struct {
    Level  int
    Action func()
}
 
func (this *AmbAction) Level() int {
    return this.Level
}
 
func (this *AmbAction) Invoke() bool {
    this.Action()
    return true
}
 
type ValueSet struct {
    Enumerable []interface{}
    enumerator []interface{}
}
 
func (this *ValueSet) CreateIterator() IValueSetIterator {
    return &ValueSetIterator{
        Enumerable: this.Enumerable,
    }
}
 
type ValueSetIterator struct {
    Enumerable []interface{}
    index      int
}
 
func (this *ValueSetIterator) MoveNext() bool {
    if this.index < len(this.Enumerable) {
        this.index++
        return true
    }
    return false
}
 
func (this *ValueSetIterator) Dispose() {
}
 
type IAmbValue interface {
    Value() interface{}
}
 
type AmbException struct {
}
 
func (this AmbException) Error() string {
    return "AMB is angry"
}
 
func main() {
    var amb Amb
    defer amb.Dispose()
    amb.DefineValues(1, 2, 3).
        Assert(func() bool {
            return amb.DefineValues(4, 5, 6).Value().(int) < 10
        }).
        Perform(func() {
            fmt.Println(amb.DefineValues(1, 2, 3).Value(), amb.DefineValues(4, 5, 6).Value())
        })
}

