import (
	"fmt"
)

func quibble(words []string) string {
	return "{" +
		fmt.Sprintf("%s", words[:len(words)-1]) +
		(func() string {
			if len(words) > 1 {
				return " and "
			}
			return ""
		})() +
		(func() string {
			if len(words) > 0 {
				return words[len(words)-1]
			}
			return ""
		})() +
		"}"
}

func main() {
	fmt.Println(quibble([]string{}))
	fmt.Println(quibble([]string{"ABC"}))
	fmt.Println(quibble([]string{"ABC", "DEF"}))
	fmt.Println(quibble([]string{"ABC", "DEF", "G", "H"}))
}

package main

import (
	"fmt"
	"math/big"
)

func main() {
	primes := make(chan *big.Int)
	go func() {
		for i := big.NewInt(2); ; i = i.Add(i, big.NewInt(1)) {
			if i.ProbablyPrime(10) {
				primes <- i
			}
		}
	}()

	gapStarts := make(map[int]*big.Int)
	findGapStart := func(gap int) *big.Int {
		if start, ok := gapStarts[gap]; ok {
			return start
		}
		for {
			prev := <-primes
			lastPrime := <-primes
			diff := lastPrime.Sub(lastPrime, prev)
			if _, ok := gapStarts[diff.Int64()];!ok {
				gapStarts[diff.Int64()] = prev
			}
			if gap == diff.Int64() {
				return prev
			}
		}
	}

	limit := big.NewInt(100000000000)

	pm := big.NewInt(10)
	gap1 := 2
	for {
		start1 := findGapStart(gap1)
		gap2 := gap1 + 2
		start2 := findGapStart(gap2)
		diff := new(big.Int)
		if start2.Cmp(start1) > 0 {
			diff = diff.Sub(start2, start1)
		} else {
			diff = diff.Sub(start1, start2)
		}
		if diff.Cmp(pm) > 0 {
			fmt.Printf("Earliest difference > %v between adjacent prime gap starting primes:\n"+
				"Gap %v starts at %v, gap %v starts at %v, difference is %v.\n",
				pm, gap1, start1, gap2, start2, diff)
			if pm.Cmp(limit) == 0 {
				break
			}
			pm.Mul(pm, big.NewInt(10))
		} else {
			gap1 = gap2
		}
	}
}

