func isHarshad(n uint32) bool {
	sumDigits := 0
	for _, c := range strconv.Itoa(int(n)) {
		sumDigits += int(c - '0')
	}
	return n%uint32(sumDigits) == 0
}
 
func main() {
	for i := uint32(1); i < 1000000; i++ {
		if isHarshad(i) {
			fmt.Println("Harshad : ", i)
		}
	}
	for i := uint32(1001); i < 1000000; i++ {
		if isHarshad(i) {
			fmt.Println("First Harshad bigger than 1_000 : ", i)
			break
		}
	}
}

package main

import (
	"fmt"
	"math"
	"strconv"
)

type NextNum struct {
	first  int
	second int
}

func (n *NextNum) Next() int {
	result := n.first + n.second
	n.first = n.second
	n.second = result
	return result
}

func findFrequencies(fibos []int, numberfrequencies map[int]int) {
	for _, bignumber := range fibos {
		firstdigit, _ := strconv.Atoi(strconv.Itoa(bignumber)[0:1])
		if _, ok := numberfrequencies[firstdigit];!ok {
			numberfrequencies[firstdigit] = 1
		} else {
			numberfrequencies[firstdigit]++
		}
	}
}

func main() {
	fibonaccis := make([]int, 1000)
	fibonaccis[0] = 0
	fibonaccis[1] = 1
	a := 0
	b := 1
	for i := 2; i < 998; i++ {
		fibonaccis[i] = NextNum{a, b}.Next()
	}
	fmt.Println()
	numberfrequencies := make(map[int]int)
	findFrequencies(fibonaccis, numberfrequencies)
	fmt.Println("                found                    expected")
	for i := 1; i < 10; i++ {
		found := float64(numberfrequencies[i]) / 1000
		expected := math.Log10(1 + 1/float64(i))
		fmt.Printf("%d : %16.2f %% %26.2f %%\n", i, found*100, expected*100)
	}
}

