package main

import (
	"fmt"
	"image"
	"image/jpeg"
	"os"
)

type RGBColour struct {
	red, green, blue uint8
}

func (c RGBColour) minus(a_colour RGBColour) int {
	return int(c.red-a_colour.red) + int(c.green-a_colour.green) + int(c.blue-a_colour.blue)
}

type Pixmap struct {
	width, height int
	pixels        []RGBColour
}

func (p Pixmap) minus(a_pixmap Pixmap) float64 {
	if p.width!= a_pixmap.width || p.height!= a_pixmap.height {
		panic("can't compare images with different sizes")
	}
	sum := 0
	for y := 0; y < p.height; y++ {
		for x := 0; x < p.width; x++ {
			sum += p.pixels[y*p.width+x].minus(a_pixmap.pixels[y*p.width+x])
		}
	}
	return float64(sum) / float64(p.width*p.height*255*3)
}

func (p Pixmap) at(x, y int) RGBColour {
	return p.pixels[y*p.width+x]
}

func open_from_jpeg(filename string) Pixmap {
	file, err := os.Open(filename)
	if err!= nil {
		panic(err)
	}
	defer file.Close()
	img, err := jpeg.Decode(file)
	if err!= nil {
		panic(err)
	}
	bounds := img.Bounds()
	width, height := bounds.Max.X, bounds.Max.Y
	pixels := make([]RGBColour, width*height)
	for y := 0; y < height; y++ {
		for x := 0; x < width; x++ {
			r, g, b, _ := img.At(x, y).RGBA()
			pixels[y*width+x] = RGBColour{uint8(r), uint8(g), uint8(b)}
		}
	}
	return Pixmap{width, height, pixels}
}

func main() {
	lenna50 := open_from_jpeg("Lenna50.jpg")
	lenna100 := open_from_jpeg("Lenna100.jpg")
	fmt.Printf("difference: %.5f%%\n", 100.0*(lenna50.minus(lenna100)))
}

