// version 1.1.2
 
const MAX = 12
 
var sp []byte
var count [MAX]int
var pos int
 
func factSum(n int) int {
    s := 0
    x := 0
    f := 1    
    for x < n {
        f *= x + 1
        s += f
        x++
    }
    return s
}
 
func r(n int) bool {
    if n == 0 { return false }
    c := sp[pos - n]
    if count[n]--; count[n] == 0 {
        count[n] = n
        if!r(n - 1) { return false }
    }
    sp[pos] = c
    pos++
    return true
}
 
func superPerm(n int) {
    pos = n
    len := factSum(n)
    if len > 0 { sp = make([]byte, len) }
    for i := 0; i <= n; i++ { count[i] = i }
    for i := 1; i <= n; i++ { sp[i - 1] = byte('0' + i) } 
    for r(n) {}
}
 
func main() {
    for n := 0; n < MAX; n++ {
        superPerm(n)
        fmt.Printf("superPerm(%2d) len = %d\n", n, len(sp))       
    }
}

package main

import (
    "fmt"
    "strings"
    "time"
)

func fmt(a []int) string {
    var sb strings.Builder
    for i := 0; i < len(a); i++ {
        sb.WriteString(fmt.Sprintf("%5d%s", a[i], (i+1)%10 == 0? "\n" : " "))
    }
    return sb.String()
}

func main() {
    start := time.Now()
    pr := Sundaram(15500000)
    for i := 0; i < 1000000; i++ {
        _ = <-pr
    }
    elapsed := time.Since(start)
    fmt.Printf("The first 100 odd prime numbers:\n%s\n", fmt(take(100, pr)))
    fmt.Printf("The millionth odd prime number: %d\n", <-pr)
    fmt.Printf("%v ms\n", elapsed.Milliseconds())
}

func Sundaram(n int) chan int {
    ch := make(chan int)
    go func() {
        defer close(ch)
        i, k, t, v, d, s := 1, (n+1)>>1, 1, 1, 1, 1
        comps := make([]bool, k+1)
        for t < k {
            t = ((i + (s + (d += 2))) << 1) - d - 2
            for t += d + 2; t < k; t += d + 2 {
                comps[t] = true
            }
        }
        for v < k {
            if!comps[v] {
                ch <- (v << 1) + 1
            }
        }
    }()
    return ch
}

func take(n int, ch chan int) []int {
    a := make([]int, n)
    for i := 0; i < n; i++ {
        a[i] = <-ch
    }
    return a
}

package main
 
import (
    "fmt"
    "io/ioutil"
    "net/http"
    "regexp"
    "strings"
)
 
const (
    base = "http://rosettacode.org"
)
 
var (
    titlePattern = regexp.MustCompile("\"title\": \"([^\"]+)\"")
    headerPattern = regexp.MustCompile("==\\{\\{header\\|([^}]+)}}==")
    barePredicate = regexp.MustCompile("<lang>")
)
 
func main() {
    titleUri := base + "/mw/api.php?action=query&list=categorymembers&cmtitle=Category:Programming_Tasks"
    titleResponse, err := http.Get(titleUri)
    if err!= nil {
        panic(err)
    }
    defer titleResponse.Body.Close()
    if titleResponse.StatusCode == 200 {
        titleBody, err := ioutil.ReadAll(titleResponse.Body)
        if err!= nil {
            panic(err)
        }
        titleList := titlePattern.FindAllStringSubmatch(string(titleBody), -1)
        countMap := make(map[string]int)
        for _, title := range titleList {
            pageUri := base + "/wiki/action=raw&title=" + title[1]
            pageResponse, err := http.Get(pageUri)
            if err!= nil {
                panic(err)
            }
            defer pageResponse.Body.Close()
            if pageResponse.StatusCode == 200 {
                pageBody, err := ioutil.ReadAll(pageResponse.Body)
                if err!= nil {
                    panic(err)
                }
                language := "no language"
                for _, line := range strings.Split(string(pageBody), "\n") {
                    headerMatch := headerPattern.FindStringSubmatch(line)
                    if len(headerMatch) > 0 {
                        language = headerMatch[1]
                    } else if barePredicate.MatchString(line) {
                        countMap[language]++
                    }
                }
            } else {
                fmt.Printf("Got a %d status code\n", pageResponse.StatusCode)
            }
        }
        for language, count := range countMap {
            fmt.Printf("%d in %s\n", count, language)
        }
    } else {
        fmt.Printf("Got a %d status code\n", titleResponse.StatusCode)
    }
}

