package main

import (
	"fmt"
)

func main() {
	descriptions := map[string]string{
		"fly":    "I don't know why S",
		"spider": "That wriggled and jiggled and tickled inside her.",
		"bird":   "Quite absurd T",
		"cat":    "Fancy that, S",
		"dog":    "What a hog, S",
		"goat":   "She opened her throat T",
		"cow":    "I don't know how S",
		"horse":  "She's dead, of course.",
	}
	animals := []string{"fly", "spider", "bird", "cat", "dog", "goat", "cow", "horse"}

	for i, animal := range animals {
		fmt.Printf("There was an old lady who swallowed a %s.\n", animal)

		d := descriptions[animal]
		switch d[len(d)-1] {
		case 'S':
			d = d[:len(d)-1] + "she swallowed a " + animal + "."
		case 'T':
			d = d[:len(d)-1] + "to swallow a " + animal + "."
		}
		fmt.Println(d)
		if animal == "horse" {
			break
		}

		for j := i - 1; j >= 1; j-- {
			fmt.Printf("She swallowed the %s to catch the %s.\n", animals[j], animals[j-1])
			switch animals[j-1] {
			case "spider", "fly":
				fmt.Println(descriptions[animals[j-1]])
			}
		}

		fmt.Println("Perhaps she'll die.")
		fmt.Println()
	}
}

package main

import (
	"fmt"
)

func sign(x float64) int {
	if x < 0.0 {
		return -1
	} else if x > 0.0 {
		return 1
	} else {
		return 0
	}
}

func printRoots(f func(float64) float64, lowerBound float64, upperBound float64, step float64) {
	x := lowerBound
	ox := x
	y := f(x)
	oy := y
	s := sign(y)
	os := s

	for x <= upperBound {
		s = sign(y = f(x))
		if s == 0 {
			fmt.Println(x)
		} else if s!= os {
			dx := x - ox
			dy := y - oy
			cx := x - dx*(y/dy)
			fmt.Println("~", cx)
		}
		ox = x
		oy = y
		os = s
		x += step
	}
}

func main() {
	poly := func(x float64) float64 {
		return x*x*x - 3*x*x + 2*x
	}
	printRoots(poly, -1.0, 4, 0.002)
}

package main

import (
	"fmt"
	"math"
	"sort"
	"strconv"
)

type pair struct {
	first  int
	second int
}

func isVampireNumber(number int, solution []pair) bool {
	numberstring := strconv.Itoa(number)
	numberstring = sortString(numberstring)
	fanglength := len(numberstring) / 2
	start := int(math.Pow(10, float64(fanglength-1)))
	end := int(math.Sqrt(float64(number)))
	for i := start; i <= end; i++ {
		if number%i == 0 {
			quotient := number / i
			if (i%10 == 0) && (quotient%10 == 0) {
				continue
			}
			divisorstring := strconv.Itoa(i) + strconv.Itoa(quotient)
			divisorstring = sortString(divisorstring)
			if divisorstring == numberstring {
				divisors := pair{i, quotient}
				solution = append(solution, divisors)
			}
		}
	}
	return len(solution)!= 0
}

func sortString(s string) string {
	r := []rune(s)
	sort.Slice(r, func(i, j int) bool {
		return r[i] < r[j]
	})
	return string(r)
}

func printOut(solution pair) {
	fmt.Printf("[ %d, %d ]", solution.first, solution.second)
}

func main() {
	vampireNumbersFound := 0
	solutions := make([]pair, 0)
	i := 1.0
	for vampireNumbersFound < 25 {
		start := int(math.Pow(10, i))
		end := start * 10
		for num := start; num < end; num++ {
			if isVampireNumber(num, solutions) {
				vampireNumbersFound++
				fmt.Printf("%d : %d is a vampire number! These are the fangs:\n", vampireNumbersFound, num)
				for _, solution := range solutions {
					printOut(solution)
				}
				fmt.Println("\n_______________")
				solutions = make([]pair, 0)
				if vampireNumbersFound == 25 {
					break
				}
			}
		}
		i += 2.0
	}
	testnumbers := []int{16758243290880, 24959017348650, 14593825548650}
	for _, svl := range testnumbers {
		if isVampireNumber(svl, solutions) {
			fmt.Printf("%d is a vampire number! The fangs:\n", svl)
			for _, solution := range solutions {
				printOut(solution)
			}
			fmt.Println()
			solutions = make([]pair, 0)
		} else {
			fmt.Printf("%d is not a vampire number!\n", svl)
		}
	}
}

package main

import "fmt"

func makeChange(coins []int, cents int) int {
	size := cents + 1
	ways := make([]int, size)
	ways[0] = 1
	for _, coin := range coins {
		for amount := coin; amount < size; amount++ {
			ways[amount] += ways[amount-coin]
		}
	}
	return ways[cents]
}

func main() {
	fmt.Println(makeChange([]int{1, 5, 10, 25}, 100))
	fmt.Println(makeChange([]int{1, 5, 10, 25, 50, 100}, 100000))
}

package main

import (
	"fmt"
	"image"
	"image/color"
	"image/png"
	"math"
	"os"
)

func get_first_dimension(a [][]color.Color) int {
	return len(a)
}

func get_second_dimension(a [][]color.Color) int {
	return len(a[0])
}

func draw_Mandelbrot(image [][]color.Color, set_color, non_set_color color.Color, cxmin, cxmax, cymin, cymax float64, max_iterations int) {
	ixsize := get_first_dimension(image)
	iysize := get_second_dimension(image)
	for ix := 0; ix < ixsize; ix++ {
		for iy := 0; iy < iysize; iy++ {
			c := complex(cxmin+float64(ix)/(float64(ixsize)-1.0)*(cxmax-cxmin), cymin+float64(iy)/(float64(iysize)-1.0)*(cymax-cymin))
			z := complex(0, 0)
			var iterations int
			for iterations = 0; iterations < max_iterations && math.Abs(real(z)) < 2.0; iterations++ {
				z = z*z + c
			}
			if iterations == max_iterations {
				image[ix][iy] = set_color
			} else {
				image[ix][iy] = non_set_color
			}
		}
	}
}

func main() {
	const (
		cxmin, cxmax, cymin, cymax = -2.0, 1.0, -1.0, 1.0
		max_iterations             = 200
	)
	img := image.NewRGBA(image.Rect(0, 0, 1000, 1000))
	draw_Mandelbrot(img.Pix, color.RGBA{255, 0, 0, 255}, color.RGBA{0, 0, 0, 255}, cxmin, cxmax, cymin, cymax, max_iterations)
	f, _ := os.Create("mandelbrot.png")
	png.Encode(f, img)
}

package main
 
import (
    "fmt"
    "strings"
)
 
func reverseString(s string) string {
    var b strings.Builder
    for i := len(s) - 1; i >= 0; i-- {
        b.WriteByte(s[i])
    }
    return b.String()
}
 
func reverseWords(s string) string {
    var b strings.Builder
    for _, word := range strings.Fields(s) {
        b.WriteString(reverseString(word))
        b.WriteByte(' ')
    }
    return strings.TrimSuffix(b.String(), " ")
}
 
func reverseWordOrder(s string) string {
    var b strings.Builder
    for i := len(s) - 1; i >= 0; i-- {
        if s[i] =='' {
            b.WriteByte(' ')
            continue
        }
        start := i
        for i >= 0 && s[i]!='' {
            i--
        }
        b.WriteString(s[i+1 : start+1])
    }
    return b.String()
}
 
func main() {
    s := "rosetta code phrase reversal"
    fmt.Println(reverseString(s))
    fmt.Println(reverseWords(s))
    fmt.Println(reverseWordOrder(s))
}

