package main
 
import (
    "bufio"
    "fmt"
    "os"
    "sort"
    "strings"
)
 
func textChar(ch rune) rune {
    switch ch {
    case 'a', 'b', 'c':
        return '2'
    case 'd', 'e', 'f':
        return '3'
    case 'g', 'h', 'i':
        return '4'
    case 'j', 'k', 'l':
        return '5'
    case'm', 'n', 'o':
        return '6'
    case 'p', 'q', 'r','s':
        return '7'
    case 't', 'u', 'v':
        return '8'
    case 'w', 'x', 'y', 'z':
        return '9'
    default:
        return -1
    }
}
 
func textString(s string) string {
    var text strings.Builder
    for _, ch := range s {
        if t := textChar(ch); t!= -1 {
            text.WriteRune(t)
        } else {
            return ""
        }
    }
    return text.String()
}
 
func printTopWords(textonyms [][2]string, top int) {
    for _, text := range textonyms[:top] {
        fmt.Printf("%s = %s\n", text[0], strings.Join(text[1], ", "))
    }
}
 
func findTextonyms(filename string) error {
    file, err := os.Open(filename)
    if err!= nil {
        return err
    }
    defer file.Close()
 
    table := make(map[string][]string)
    count := 0
 
    scanner := bufio.NewScanner(file)
    for scanner.Scan() {
        word := strings.ToLower(scanner.Text())
        if text := textString(word); text!= "" {
            table[text] = append(table[text], word)
            count++
        }
    }
 
    textonyms := make([][2]string, 0, len(table))
    for text, words := range table {
        if len(words) > 1 {
            textonyms = append(textonyms, [2]string{text, strings.Join(words, ", ")})
        }
    }
 
    fmt.Printf("There are %d words in '%s' which can be represented by the digit key mapping.\n", count, filename)
    fmt.Printf("They require %d digit combinations to represent them.\n", len(table))
    fmt.Printf("%d digit combinations represent Textonyms.\n", len(textonyms))
 
    top := len(textonyms)
    if top > 5 {
        top = 5
    }
    sort.Slice(textonyms, func(i, j int) bool {
        return len(textonyms[i][1]) > len(textonyms[j][1])
    })
    fmt.Printf("\nTop %d by number of words:\n", top)
    printTopWords(textonyms, top)
 
    sort.Slice(textonyms, func(i, j int) bool {
        return len(textonyms[i][0]) > len(textonyms[j][0])
    })
    fmt.Printf("\nTop %d by length:\n", top)
    printTopWords(textonyms, top)
 
    return nil
}
 
func main() {
    if len(os.Args)!= 2 {
        fmt.Fprintf(os.Stderr, "usage: %s word-list\n", os.Args[0])
        os.Exit(1)
    }
    if err := findTextonyms(os.Args[1]); err!= nil {
        fmt.Fprintf(os.Stderr, "%s: %s\n", os.Args[1], err)
        os.Exit(1)
    }
}

package kata

func RealSet(set1, set2 []int, op string, values []int) []bool {
    var makeSet = func(set0 []int) []int {
        var res []int
        if set0[0] == 0 {
            for i := set0[1]; i <= set0[2]; i++ {
                res = append(res, i)
            }
        } else if set0[0] == 1 {
            for i := set0[1] + 1; i < set0[2]; i++ {
                res = append(res, i)
            }
        } else if set0[0] == 2 {
            for i := set0[1] + 1; i <= set0[2]; i++ {
                res = append(res, i)
            }
        } else {
            for i := set0[1]; i < set0[2]; i++ {
                res = append(res, i)
            }
        }
        return res
    }
    var res []bool
    var finalSet []int
    set1 = makeSet(set1)
    set2 = makeSet(set2)
    if op == "union" {
        finalSet = append(set1, set2...)
    } else if op == "intersect" {
        for i := 0; i < len(set1); i++ {
            if indexOf(set2, set1[i])!= -1 {
                finalSet = append(finalSet, set1[i])
            }
        }
    } else {
        for i := 0; i < len(set2); i++ {
            if indexOf(set1, set2[i]) == -1 {
                finalSet = append(finalSet, set2[i])
            }
        }
        for i := 0; i < len(set1); i++ {
            if indexOf(set2, set1[i]) == -1 {
                finalSet = append(finalSet, set1[i])
            }
        }
    }
    for i := 0; i < len(values); i++ {
        if indexOf(finalSet, values[i])!= -1 {
            res = append(res, true)
        } else {
            res = append(res, false)
        }
    }
    return res
}

func indexOf(arr []int, val int) int {
    for i := 0; i < len(arr); i++ {
        if arr[i] == val {
            return i
        }
    }
    return -1
}

