package main

import (
	"fmt"
	"strings"
	"unicode"
)

type integer uint64

var small = []string{
	"zero", "one", "two", "three", "four", "five", "six", "seven", "eight",
	"nine", "ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen",
	"sixteen", "seventeen", "eighteen", "nineteen",
}

var tens = []string{
	"twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety",
}

type namedNumber struct {
	name   string
	number integer
}

var namedNumbers = []namedNumber{
	{"hundred", 100},
	{"thousand", 1000},
	{"million", 1000000},
	{"billion", 1000000000},
	{"trillion", 1000000000000},
	{"quadrillion", 1000000000000000},
	{"quintillion", 1000000000000000000},
}

func getNamedNumber(n integer) namedNumber {
	for i := 0; i+1 < len(namedNumbers); i++ {
		if n < namedNumbers[i+1].number {
			return namedNumbers[i]
		}
	}
	return namedNumbers[len(namedNumbers)-1]
}

func cardinal(n integer) string {
	if n < 20 {
		return small[n]
	} else if n < 100 {
		result := tens[n/10-2]
		if n%10!= 0 {
			result += "-"
			result += small[n%10]
		}
		return result
	} else {
		num := getNamedNumber(n)
		p := num.number
		result := cardinal(n / p)
		result += " "
		result += num.name
		if n%p!= 0 {
			result += " "
			result += cardinal(n % p)
		}
		return result
	}
}

func uppercase(ch rune) rune {
	return unicode.ToUpper(ch)
}

func magic(n integer) string {
	var result strings.Builder
	for i := 0; ; i++ {
		text := cardinal(n)
		if i == 0 {
			text = string(uppercase([]rune(text)[0])) + text[1:]
		}
		result.WriteString(text)
		if n == 4 {
			result.WriteString(" is magic.")
			break
		}
		length := len(text)
		result.WriteString(" is ")
		result.WriteString(cardinal(integer(length)))
		result.WriteString(", ")
		n = integer(length)
	}
	return result.String()
}

func testMagic(n integer) {
	fmt.Println(magic(n))
}

func main() {
	testMagic(5)
	testMagic(13)
	testMagic(78)
	testMagic(797)
	testMagic(2739)
	testMagic(4000)
	testMagic(7893)
	testMagic(93497412)
	testMagic(2673497412)
	testMagic(10344658531277200972)
}

