func endsWith89(n int) bool {
    var digit int
    var sum int = 0
    var nn int = n
    for {
        for nn > 0 {
            digit = nn % 10
            sum += digit * digit
            nn /= 10
        }
        if sum == 89 {
            return true
        }
        if sum == 1 {
            return false
        }
        nn = sum
        sum = 0
    }
}
 
func main() {
    sums := make([]int, 8*81+1)
    sums[0] = 1
    sums[1] = 0
    var s int
    for n := 1; n <= 8; n++ {
        for i := n * 81; i >= 1; i-- {
            for j := 1; j <= 9; j++ {
                s = j * j
                if s > i {
                    break
                }
                sums[i] += sums[i-s]
            }
        }
    }
    var count89 int = 0
    for i := 1; i <= 8*81; i++ {
        if endsWith89(i) {
            count89 += sums[i]
        }
    }
    fmt.Printf("There are %d numbers from 1 to 100 million ending with 89\n", count89)
}

package main

import (
	"fmt"
	"math/big"
)

func main() {
	emirp := make(chan int)
	go func() {
		defer close(emirp)
		for prime := range primes() {
			rev := reverse(prime)
			if isPrime(rev) && rev!= prime {
				emirp <- prime
			}
		}
	}()

	fmt.Println("First 20 emirps:", firstN(emirp, 20))
	fmt.Println("Emirps between 7,700 and 8,000:")
	for i, prime := range takeWhile(emirp, func(prime int) bool {
		return prime < 8000
	}) {
		if prime >= 7700 {
			fmt.Print(prime, " ")
		}
		if i == 9999 {
			fmt.Println()
			fmt.Println("10,000th emirp:", prime)
			break
		}
	}
}

func firstN(ch <-chan int, n int) []int {
	var result []int
	for i := 0; i < n; i++ {
		result = append(result, <-ch)
	}
	return result
}

func takeWhile(ch <-chan int, f func(int) bool) []int {
	var result []int
	for prime := range ch {
		if!f(prime) {
			break
		}
		result = append(result, prime)
	}
	return result
}

func primes() <-chan int {
	ch := make(chan int)
	go func() {
		defer close(ch)
		for i := 2; ; i++ {
			if isPrime(i) {
				ch <- i
			}
		}
	}()
	return ch
}

func isPrime(n int) bool {
	if n < 2 {
		return false
	}
	if n == 2 {
		return true
	}
	if n%2 == 0 {
		return false
	}
	for i := 3; i*i <= n; i += 2 {
		if n%i == 0 {
			return false
		}
	}
	return true
}

func reverse(n int) int {
	rev := 0
	for n > 0 {
		rev = rev*10 + n%10
		n /= 10
	}
	return rev
}

