package main

import (
	"fmt"
	"os"
	"os/exec"
)

type recorder struct {
	paused bool
	rec    bool
	action string
}

func (r *recorder) start() {
	r.paused = false
	r.rec = false
	r.action = "IDLE"
	for {
		fmt.Println()
		fmt.Println("==", r.action, "==")
		fmt.Println()
		fmt.Println("1) Record")
		fmt.Println("2) Play")
		fmt.Println("3) Pause")
		fmt.Println("4) Stop")
		fmt.Println("5) Quit")
		var c string
		fmt.Scanln(&c)
		if c > "0" && c < "6" {
			switch c {
			case "1":
				r.record()
			case "2":
				r.play()
			case "3":
				r.pause()
			case "4":
				r.stop()
			case "5":
				r.stop()
				return
			}
		}
	}
}

func (r *recorder) record() {
	if mciExecute("open new type waveaudio alias my_sound") {
		mciExecute("record my_sound")
		r.action = "RECORDING"
		r.rec = true
	}
}

func (r *recorder) play() {
	if r.paused {
		mciExecute("play my_sound")
	} else {
		if mciExecute("open tmp.wav alias my_sound") {
			mciExecute("play my_sound")
		}
	}
	r.action = "PLAYING"
	r.paused = false
}

func (r *recorder) pause() {
	if r.rec {
		return
	}
	mciExecute("pause my_sound")
	r.paused = true
	r.action = "PAUSED"
}

func (r *recorder) stop() {
	if r.rec {
		mciExecute("stop my_sound")
		mciExecute("save my_sound tmp.wav")
		mciExecute("close my_sound")
		r.action = "IDLE"
		r.rec = false
	} else {
		mciExecute("stop my_sound")
		mciExecute("close my_sound")
		r.action = "IDLE"
	}
}

func mciExecute(cmd string) bool {
	out, err := exec.Command("mci", cmd).Output()
	if err!= nil {
		fmt.Println("Can't do this: ", cmd)
		return false
	}
	fmt.Println(string(out))
	return true
}

func main() {
	r := new(recorder)
	r.start()
}

