package main
 
import (
    "fmt"
)
 
func ffr(n int) int {
    return get(n, 0)[n-1]
}
 
func ffs(n int) int {
    return get(0, n)[n-1]
}
 
func get(rSize int, sSize int) []int {
    rlist := []int{1, 3, 7}
    slist := []int{2, 4, 5, 6}
    list := rlist
    targetSize := rSize
    if rSize == 0 {
        list = slist
        targetSize = sSize
    }
    for len(list) > targetSize {
        list = list[:len(list)-1]
    }
    for len(list) < targetSize {
        lastIndex := len(rlist) - 1
        lastr := rlist[lastIndex]
        r := lastr + slist[lastIndex]
        rlist = append(rlist, r)
        s := lastr + 1
        for s < r && len(list) < targetSize {
            slist = append(slist, s)
            s++
        }
    }
    return list
}
 
func main() {
    fmt.Print("R():")
    for i := 1; i <= 10; i++ {
        fmt.Printf(" %d", ffr(i))
    }
    fmt.Println()
 
    first40R := make([]int, 40)
    for i := 0; i < 40; i++ {
        first40R[i] = ffr(i + 1)
    }
    first960S := make([]int, 960)
    for i := 0; i < 960; i++ {
        first960S[i] = ffs(i + 1)
    }
    indices := make([]int, 0)
    for i := 0; i < 1000; i++ {
        if (i < 40 && first40R[i] == i+1) || (i < 960 && first960S[i] == i+1) {
            indices = append(indices, i+1)
        }
    }
    for _, i := range indices {
        fmt.Printf("Integer %d either in both or neither set\n", i)
    }
    fmt.Println("Done")
}

