type user int
 
func (user) m() {
    fmt.Println("method call")
}
 
func status() {
    trySlice()
    tryPointer()
    tryFunction()
    tryInterface()
    tryMap()
    tryChannel()
}
 
func reportPanic() {
    if x := recover(); x != nil {
        fmt.Println("panic:", x)
    }
}
 
func trySlice() {
    defer reportPanic()
    fmt.Println("s[0] =", s[0])
}
 
func tryPointer() {
    defer reportPanic()
    fmt.Println("*p =", *p)
}
 
func tryFunction() {
    defer reportPanic()
    f()
}
 
func tryInterface() {
    defer reportPanic()
 
    // normally the nil identifier accesses a nil value for one of
    // six predefined types.  In a type switch however, nil can be used
    // as a type.  In this case, it matches the nil interface.
    switch i.(type) {
    case nil:
        fmt.Println("i is nil interface")
    case interface {
        m()
    }:
        fmt.Println("i has method m")
    }
 
    // assert type with method and then call method
    i.(interface {
        m()
    }).m()
}
 
func tryMap() {
    defer reportPanic()
    m[0] = 0
    fmt.Println("m[0] =", m[0])
}
 
func tryChannel() {
    defer reportPanic()
    close(c)
    fmt.Println("channel closed")
}

package main
 
import "fmt"
 
func circleSort(a []int, lo, hi, swaps int) int {
    if lo == hi {
        return swaps
    }
    high, low := hi, lo
    mid := (hi - lo) / 2
    for lo < hi {
        if a[lo] > a[hi] {
            a[lo], a[hi] = a[hi], a[lo]
            swaps++
        }
        lo++
        hi--
    }
    if lo == hi {
        if a[lo] > a[hi+1] {
            a[lo], a[hi+1] = a[hi+1], a[lo]
            swaps++
        }
    }
    swaps = circleSort(a, low, low+mid, swaps)
    swaps = circleSort(a, low+mid+1, high, swaps)
    return swaps
}
 
func main() {
    aa := [][]int{
        {6, 7, 8, 9, 2, 5, 3, 4, 1},
        {2, 14, 4, 6, 8, 1, 3, 5, 7, 11, 0, 13, 12, -1},
    }
    for _, a := range aa {
        fmt.Printf("Original: %v\n", a)
        for circleSort(a, 0, len(a)-1, 0) != 0 {
            // empty block
        }
        fmt.Printf("Sorted  : %v\n\n", a)
    }
}

